UPDATE "materials" SET "content_payload" = '' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || '{"source":"非自然死亡","language":"ja","dialogues":[{"id":1,"end":10.11,"note":"","text":"せ～の","start":8.41,"favorite":false,"stableId":"5c3e33a0-6b68-4c1f-85f6-80d504c87962","sequenceId":1},{"id":2,"end":13.13,"note":"","text":"ああ 来ましたはい","start":11.78,"favorite":false,"stableId":"bdc61d79-87fa-45d1-83cc-9e8d921a246c","sequenceId":2},{"id":3,"end":14.26,"note":"","text":"これで登録完了です","start":13.18,"favorite":false,"stableId":"269cb35c-38b4-426c-bbd1-8e2805d254a2","sequenceId":3},{"id":4,"end":15.9,"note":"","text":"便利な時代だね","start":14.31,"favorite":false,"stableId":"f9a22130-1243-4030-b214-f1c4e394294c","sequenceId":4},{"id":5,"end":17.33,"note":"","text":"フッ オバちゃんか","start":15.95,"favorite":false,"stableId":"29acc818-a6eb-48da-8045-d29b52a68fcd","sequenceId":5},{"id":6,"end":19.2,"note":"","text":"-東海林 やろ-いいよ","start":17.38,"favorite":false,"stableId":"6a280940-46b2-4db3-b7b1-9089c017e41b","sequenceId":6},{"id":7,"end":21.17,"note":"","text":"えっ 何の騒ぎ？","start":19.25,"favorite":false,"stableId":"f74188ab-91e4-437b-9cad-112fff2dfc8e","sequenceId":7},{"id":8,"end":22.74,"note":"","text":"あっ 連絡先の交換です","start":21.22,"favorite":false,"stableId":"8792678e-1980-42ca-867f-ef63e91bc8ca","sequenceId":8},{"id":9,"end":24.81,"note":"","text":"三澄さんがスマホデビューして","start":22.79,"favorite":false,"stableId":"6dbb2ff2-8069-4008-8819-dad83375f977","sequenceId":9},{"id":10,"end":26.06,"note":"","text":"あっ 携帯","start":24.86,"favorite":false,"stableId":"45d2912e-6775-4ecb-88b1-89934c2f9d4f","sequenceId":10},{"id":11,"end":29.8,"note":"","text":"２人とも無事でよかったよ～","start":26.83,"favorite":false,"stableId":"597aa2fb-b18c-425c-98bb-74776131f76a","sequenceId":11},{"id":12,"end":44.63,"note":"","text":"巻き込んで ごめんね","start":42.78,"favorite":false,"stableId":"88d82c58-5881-4da9-8633-d4825ccef71d","sequenceId":12},{"id":13,"end":48.48,"note":"","text":"おわびに明日の夜 空いてる？","start":44.68,"favorite":false,"stableId":"8bedc740-62fe-4890-9c4a-437c002cbcd3","sequenceId":13},{"id":14,"end":50.83,"note":"","text":"おいしいもん食べに行こう","start":48.85,"favorite":false,"stableId":"74c34603-64c0-48ef-8a37-95c4a583f908","sequenceId":14},{"id":15,"end":52.24,"note":"","text":"絶望してる暇あったら","start":50.88,"favorite":false,"stableId":"049f7ac1-d831-49dd-bdcf-c4eb6da782ef","sequenceId":15},{"id":16,"end":54.52,"note":"","text":"うまいもん食べて寝るかな","start":52.29,"favorite":false,"stableId":"57ab56da-8247-4bad-8a1a-b0c0c5131b2a","sequenceId":16},{"id":17,"end":57.54,"note":"","text":"楽しそうなとこすいません","start":55.69,"favorite":false,"stableId":"23a811d0-4f6e-479d-a099-2ee65ceaaf79","sequenceId":17},{"id":18,"end":59.78,"note":"","text":"三澄さんにお願いがあるんですけど","start":57.59,"favorite":false,"stableId":"6c0e71fb-93af-46a1-8ea6-b855d1f91862","sequenceId":18},{"id":19,"end":61.68,"note":"","text":"-三澄さん-はい？","start":59.83,"favorite":false,"stableId":"036cd282-f6fe-49b5-932e-fd110cff58fc","sequenceId":19},{"id":20,"end":63.11,"note":"","text":"この事件 知ってます？","start":61.73,"favorite":false,"stableId":"4011082b-ee34-4f20-91d1-a52ab4c363ec","sequenceId":20},{"id":21,"end":64.05,"note":"","text":"うん？","start":63.16,"favorite":false,"stableId":"98eb1255-de05-4aeb-bd8d-b05d09aa6539","sequenceId":21},{"id":22,"end":66.68,"note":"","text":"半年前に うちで解剖したご遺体なんですけど","start":64.1,"favorite":false,"stableId":"df7125af-bfb3-4a80-aa34-76d165bbfe83","sequenceId":22},{"id":23,"end":70.34,"note":"","text":"ああ…主婦ブロガー殺人事件","start":66.73,"favorite":false,"stableId":"1753bafb-25c8-4a1c-aa6f-069f00cce1dc","sequenceId":23},{"id":24,"end":75.56,"note":"","text":"桜小路しずくは名の知れた主婦ブロガーで","start":72.17,"favorite":false,"stableId":"3acb54dd-8f9d-48af-b82e-871a838a43c8","sequenceId":24},{"id":25,"end":78.91,"note":"","text":"レシピ本を出したり結構 人気だったんだけど","start":75.61,"favorite":false,"stableId":"a9a52a67-dbbd-4fea-a7cc-fa18a009fd63","sequenceId":25},{"id":26,"end":81.73,"note":"","text":"ある日 自宅のリビングで","start":79.48,"favorite":false,"stableId":"43baa707-fd36-4c97-ad36-4d25be058c89","sequenceId":26},{"id":27,"end":83.87,"note":"","text":"刺殺体で発見された","start":81.78,"favorite":false,"stableId":"c9df009d-86e8-4562-8d61-71dbc90b8c78","sequenceId":27},{"id":28,"end":88.07,"note":"","text":"逮捕されたのはしずくの夫 桜小路要一","start":83.92,"favorite":false,"stableId":"417d84f9-19e8-41c2-9444-5628a9005a62","sequenceId":28},{"id":29,"end":92.71,"note":"","text":"しずくは日常的に 無職の夫を“役立たず”と ののしったり…","start":88.12,"favorite":false,"stableId":"f2a1040b-f43f-4593-8d99-a3bc018461de","sequenceId":29},{"id":30,"end":93.91,"note":"","text":"役立たず","start":92.76,"favorite":false,"stableId":"453add30-1ff4-4a75-98ca-6199103bbb09","sequenceId":30},{"id":31,"end":96.83,"note":"","text":"趣味のフィギュアを勝手に捨てたりしていた","start":93.96,"favorite":false,"stableId":"9080cdb3-13a6-4408-8afa-ec823b0b2ec0","sequenceId":31},{"id":32,"end":100.87,"note":"","text":"積もりに積もった不満が殺害の動機","start":96.93,"favorite":false,"stableId":"e6294e4f-2067-4259-a7b3-a9df01b3536f","sequenceId":32},{"id":33,"end":103.15,"note":"","text":"殺すくらいなら別れればいいのに","start":101.17,"favorite":false,"stableId":"4cca877a-ffe3-421e-b3b0-792539d2ed22","sequenceId":33},{"id":34,"end":104.05,"note":"","text":"それよ","start":103.2,"favorite":false,"stableId":"1e2d1890-a52b-4a81-9a46-73cc9d0426d1","sequenceId":34},{"id":35,"end":106.39,"note":"","text":"別れられないから事件が起こるんじゃない？","start":104.1,"favorite":false,"stableId":"517f05a4-805b-4bc5-8402-33c4054a9b47","sequenceId":35},{"id":36,"end":111.69,"note":"","text":"殺人事件の半数以上は親子 兄弟 夫婦といった親族間殺人","start":106.44,"favorite":false,"stableId":"7ac0ddb3-4c2d-40f3-b8a7-bdc26b24715a","sequenceId":36},{"id":37,"end":113.36,"note":"","text":"うかうか結婚もできないわ","start":111.74,"favorite":false,"stableId":"a7b82054-7af5-4803-9a36-baff8f96017a","sequenceId":37},{"id":38,"end":115.53,"note":"","text":"この事件の裁判があるんですけどね","start":113.41,"favorite":false,"stableId":"31a7d5d3-470a-4cc6-ad94-33a407ddc395","sequenceId":38},{"id":39,"end":117.97,"note":"","text":"検察側の証人として出廷してもらいたいんです","start":115.58,"favorite":false,"stableId":"187ccdef-3497-4915-91d1-1a255ec04bbd","sequenceId":39},{"id":40,"end":119.54,"note":"","text":"-私に？-解剖した先生は","start":118.02,"favorite":false,"stableId":"ba5a4124-ef5b-40d4-9fff-8b1de8279535","sequenceId":40},{"id":41,"end":122.81,"note":"","text":"うちを辞めたあと引退されて今は鹿児島の老人ホームです","start":119.59,"favorite":false,"stableId":"07c67730-1796-4208-8d7b-ceafab7a91ed","sequenceId":41},{"id":42,"end":125.21,"note":"","text":"…で 代理の証人を出さなきゃならない","start":122.86,"favorite":false,"stableId":"3d588dbc-0af0-4a80-8da4-afeaf6619de9","sequenceId":42},{"id":43,"end":127.91,"note":"","text":"でしたら中堂さんのほうがいいと思います","start":125.26,"favorite":false,"stableId":"84468bb6-8708-44a6-8831-7a3b9d541f6e","sequenceId":43},{"id":44,"end":130.71,"note":"","text":"実は 私裁判に出たことがないんです","start":127.96,"favorite":false,"stableId":"328e0ebf-b119-4fd9-a0cf-9bdda5cd70dd","sequenceId":44},{"id":45,"end":132.82,"note":"","text":"大学では いつも教授が出ていて","start":130.76,"favorite":false,"stableId":"79c78ad9-690d-4082-a87d-5171518aa47b","sequenceId":45},{"id":46,"end":134.18,"note":"","text":"中堂さんのほうが慣れてるだろうし","start":132.87,"favorite":false,"stableId":"39cb7d52-ca88-4e6a-b2dc-d9c21fbe158c","sequenceId":46},{"id":47,"end":135.89,"note":"","text":"代理証人なんて死んでもやるか","start":134.23,"favorite":false,"stableId":"8a21e3cb-d175-4f1a-870e-677807ce2976","sequenceId":47},{"id":48,"end":138.66,"note":"","text":"俺は他人の鑑定を信用しない","start":135.94,"favorite":false,"stableId":"c839fdf9-1a5c-4b3d-af11-12569969aed9","sequenceId":48},{"id":49,"end":142.16,"note":"","text":"そもそもね中堂さんは出廷させられないの","start":138.71,"favorite":false,"stableId":"1090fa05-9e94-4508-ad39-03e9a9944d0c","sequenceId":49},{"id":50,"end":143.83,"note":"","text":"-態度が悪いからですか？-おい","start":142.21,"favorite":false,"stableId":"5fec09e8-b9a5-4be8-b5a5-47c0a3faa672","sequenceId":50},{"id":51,"end":147.53,"note":"","text":"いや それもあるけど中堂さん 今 訴訟 抱えててさ","start":143.88,"favorite":false,"stableId":"ad1fe59a-7838-49d7-9e8f-e62140bbbe92","sequenceId":51},{"id":52,"end":148.63,"note":"","text":"訴訟？","start":147.58,"favorite":false,"stableId":"1ab8c097-76fd-45f1-9be4-d7446e6a783d","sequenceId":52},{"id":53,"end":149.77,"note":"","text":"訴えられてるってことですか？","start":148.68,"favorite":false,"stableId":"eb87fc22-fa5f-4d9d-ba4f-f992e7670a8b","sequenceId":53},{"id":54,"end":152.34,"note":"","text":"-誰に？-坂本さん","start":149.82,"favorite":false,"stableId":"15d6e00d-3269-4d3b-818f-147622affbce","sequenceId":54},{"id":55,"end":154,"note":"","text":"坂本さん!?","start":152.39,"favorite":false,"stableId":"f5571528-98cb-446b-9594-4a9c788484cb","sequenceId":55},{"id":56,"end":157.04,"note":"","text":"ＵＤＩラボで臨床検査技師として働いて…","start":154.05,"favorite":false,"stableId":"3125de29-15d2-4665-88e9-185af5d7f14d","sequenceId":56},{"id":57,"end":158.34,"note":"","text":"“ＵＤＩラボで”","start":157.09,"favorite":false,"stableId":"7abdc68e-7afc-40e2-bd27-0b5229936811","sequenceId":57},{"id":58,"end":161.21,"note":"","text":"“臨床検査技師として働いて３か月”","start":158.39,"favorite":false,"stableId":"03b8692f-22ea-4e52-ba85-ab6c5bcd868c","sequenceId":58},{"id":59,"end":164.95,"note":"","text":"“その間 ずっと法医解剖医 中堂 系からの”","start":161.26,"favorite":false,"stableId":"de5ca787-1ac1-4b69-a128-65ef112e4ab2","sequenceId":59},{"id":60,"end":166.75,"note":"","text":"“パワハラが続いていた”","start":165,"favorite":false,"stableId":"c80cecdc-f546-4b75-9738-cb5eb4e8b277","sequenceId":60},{"id":61,"end":169.79,"note":"","text":"“彼と これ以上一緒に働くのは苦痛である”","start":166.8,"favorite":false,"stableId":"3fbdb1d3-f611-463b-a8f0-fca03c644959","sequenceId":61},{"id":62,"end":173.66,"note":"","text":"“よって中堂 系への辞職を求める”","start":169.84,"favorite":false,"stableId":"948eb4d6-8354-4a24-8487-3fe47110b399","sequenceId":62},{"id":63,"end":176.56,"note":"","text":"中堂班を３日で辞めた人はいたけど…","start":173.71,"favorite":false,"stableId":"70d1bf49-2390-47e5-874d-a9d9669ebf8c","sequenceId":63},{"id":64,"end":179.1,"note":"","text":"辞めさせようとした人初めてですよ","start":176.61,"favorite":false,"stableId":"fccdcbb7-3108-4f20-b644-0c3fcc8ce9c6","sequenceId":64},{"id":65,"end":180.73,"note":"","text":"坂本さん ガッツありますね","start":179.15,"favorite":false,"stableId":"c2286a72-6948-4ae4-b0c7-5b8a1caff9a2","sequenceId":65},{"id":66,"end":182.1,"note":"","text":"褒めるな","start":180.78,"favorite":false,"stableId":"c6afcdde-3168-4552-9c18-01fd32854409","sequenceId":66},{"id":67,"end":183.8,"note":"","text":"-どうするんですか？-無視だな","start":182.15,"favorite":false,"stableId":"ab4dd21a-5743-4c50-99bc-e5d14c77097b","sequenceId":67},{"id":68,"end":187.17,"note":"","text":"無視できませんよ うちの監督責任だって問われるし","start":183.85,"favorite":false,"stableId":"f411039c-54dc-4b2d-94b7-b6423319213c","sequenceId":68},{"id":69,"end":189.74,"note":"","text":"“パワハラを労基に訴える”とまで言ってんですよ","start":187.22,"favorite":false,"stableId":"14349bb1-04b3-4af7-82f0-bb1e279b4ae8","sequenceId":69},{"id":70,"end":193.28,"note":"","text":"事情は分かりましたので代理証人の件は 私が引き受けます","start":189.79,"favorite":false,"stableId":"56c11128-8e8f-4ffd-b858-65307778e90a","sequenceId":70},{"id":71,"end":194.78,"note":"","text":"お願いします","start":193.33,"favorite":false,"stableId":"506e555a-8f16-4b78-89ab-304cb7d7fd3d","sequenceId":71},{"id":72,"end":196.41,"note":"","text":"検事の烏田です","start":194.83,"favorite":false,"stableId":"91265c46-c211-459c-82d3-972a894560ed","sequenceId":72},{"id":73,"end":198.45,"note":"","text":"法医解剖医の三澄です","start":196.46,"favorite":false,"stableId":"24873ebb-a0a1-4236-af91-1cfd50708b90","sequenceId":73},{"id":74,"end":200.25,"note":"","text":"あなたが三澄さん？","start":198.5,"favorite":false,"stableId":"c3918512-637b-4ee8-95bb-cb84939b05c1","sequenceId":74},{"id":75,"end":202.09,"note":"","text":"-助手ではなくて-はい","start":200.3,"favorite":false,"stableId":"489c3676-d6ed-4cf8-9290-afd1cf720ab6","sequenceId":75},{"id":76,"end":205.72,"note":"","text":"ああ…名字しか聞いていなかったもので","start":202.14,"favorite":false,"stableId":"9aaedceb-b4c1-4b7e-93e1-54d0b0350898","sequenceId":76},{"id":77,"end":207.21,"note":"","text":"女性だとは","start":205.77,"favorite":false,"stableId":"5848c83e-a74b-44dc-a1be-8b3b9dc9a2c7","sequenceId":77},{"id":78,"end":209.83,"note":"","text":"女性で 何か問題でも？","start":208.04,"favorite":false,"stableId":"c80a7b14-970e-4bde-ac5e-f7b8f878ff54","sequenceId":78},{"id":79,"end":212.68,"note":"","text":"いえ 始めましょうか","start":209.88,"favorite":false,"stableId":"9c472c02-560a-4e2b-9fc8-06fd9bbc2ab5","sequenceId":79},{"id":80,"end":216.07,"note":"","text":"司法解剖の結果⸺","start":214.35,"favorite":false,"stableId":"63965701-e52b-4caf-ae72-4afdfd90a6c0","sequenceId":80},{"id":81,"end":217.7,"note":"","text":"死因は出血性ショック","start":216.12,"favorite":false,"stableId":"3dba059c-d910-4f38-a1fb-49bd908435d9","sequenceId":81},{"id":82,"end":221.89,"note":"","text":"刃物で心臓をひと突きにされ心停止を引き起こしました","start":217.75,"favorite":false,"stableId":"41b333ad-a1d2-42a4-b372-4ad061a826a5","sequenceId":82},{"id":83,"end":225.94,"note":"","text":"凶器は 現場のキッチンで発見された この包丁です","start":221.99,"favorite":false,"stableId":"02db0f71-5c1e-4e3b-a28f-1cf5e0d2df16","sequenceId":83},{"id":84,"end":227.31,"note":"","text":"証言していただきたいのは","start":225.99,"favorite":false,"stableId":"d5b1f61f-3865-40dc-b9ff-f3df54b936df","sequenceId":84},{"id":85,"end":231.26,"note":"","text":"凶器と傷の一致と刺創管についての見解です","start":227.36,"favorite":false,"stableId":"d26fb239-3ac4-407e-b364-4986f5cbdf4a","sequenceId":85},{"id":86,"end":234.12,"note":"","text":"証言内容を 参考までにまとめておきましたので","start":231.4,"favorite":false,"stableId":"e3023013-c42e-42d8-8f7c-a9733b0af85d","sequenceId":86},{"id":87,"end":236.2,"note":"","text":"よく読んでおいてください","start":234.17,"favorite":false,"stableId":"46546ef1-ec97-4f60-9eb9-83a5a43add32","sequenceId":87},{"id":88,"end":239.27,"note":"","text":"分かりました","start":237.37,"favorite":false,"stableId":"c04a8c81-6dbf-4541-a0a9-8aea2191f4b0","sequenceId":88},{"id":89,"end":244.66,"note":"","text":"烏田さんは ＵＤＩラボの保存ルールは ご存じですか？","start":240.51,"favorite":false,"stableId":"96997ad0-f9f5-410d-928b-024b90081427","sequenceId":89},{"id":90,"end":248.7,"note":"","text":"日本の法医学教室では通常血液や臓器などの試料は","start":244.71,"favorite":false,"stableId":"3467ae19-b8b1-449d-b3ad-81c1651b48b7","sequenceId":90},{"id":91,"end":251.27,"note":"","text":"鑑定書を書き終えると処分してしまうんです","start":248.75,"favorite":false,"stableId":"1e079962-115a-4ba4-b428-f1a8944d9924","sequenceId":91},{"id":92,"end":254.6,"note":"","text":"置き場所もないですし明確な規則もないので","start":251.32,"favorite":false,"stableId":"91c9bd65-a4b2-47f5-9e50-eb1f3b9c9ca7","sequenceId":92},{"id":93,"end":257.91,"note":"","text":"ですが うちでは欧米と同じく どんなご遺体でも","start":254.65,"favorite":false,"stableId":"b95833ae-0499-4aa7-ad45-8042a9c4982a","sequenceId":93},{"id":94,"end":260.78,"note":"","text":"試料の５年保存をルールとしています","start":257.96,"favorite":false,"stableId":"9d0c7d91-4183-41de-a046-0053545b85ef","sequenceId":94},{"id":95,"end":263.75,"note":"","text":"刺殺事件の場合 傷口も残します","start":260.83,"favorite":false,"stableId":"77685309-b410-4e7f-8d95-be7c7b2fe076","sequenceId":95},{"id":96,"end":265.73,"note":"","text":"本件も このとおり","start":263.8,"favorite":false,"stableId":"510bb213-5d0c-4099-9d13-fb287fc57174","sequenceId":96},{"id":97,"end":269.95,"note":"","text":"傷や凶器の一致を補強する証拠になります","start":266.87,"favorite":false,"stableId":"74f52ae5-d612-435f-ae4b-5a15d33aa7e2","sequenceId":97},{"id":98,"end":272.32,"note":"","text":"予定外の証拠は不要です","start":270,"favorite":false,"stableId":"ce387fc4-5d07-404f-8d68-172a59e984c3","sequenceId":98},{"id":99,"end":274.89,"note":"","text":"公判前整理手続きは終わっていますので","start":272.37,"favorite":false,"stableId":"9dcba345-c47e-49f1-a1b2-327f75cf6caa","sequenceId":99},{"id":100,"end":276.63,"note":"","text":"公判前整理手続き？","start":274.94,"favorite":false,"stableId":"3f91fcfc-49cc-4015-ad6b-9da143930935","sequenceId":100},{"id":101,"end":279.76,"note":"","text":"裁判員裁判で優先されるのは迅速さです","start":276.68,"favorite":false,"stableId":"78855874-cc47-4a59-9390-1c0e59cd39e0","sequenceId":101},{"id":102,"end":282.73,"note":"","text":"裁判員の皆さんを長くは拘束できませんので","start":279.81,"favorite":false,"stableId":"0a28800a-dadf-472e-af43-89c8eabc63b8","sequenceId":102},{"id":103,"end":285.4,"note":"","text":"そのため 事前に検事 弁護士 裁判官が","start":282.78,"favorite":false,"stableId":"9040b10d-698d-4485-8102-67e1ce8f2e8e","sequenceId":103},{"id":104,"end":286.94,"note":"","text":"話し合って 流れを決めます","start":285.45,"favorite":false,"stableId":"785b3e44-66b7-4d15-999e-5f3528faeba8","sequenceId":104},{"id":105,"end":289.72,"note":"","text":"証拠も証人も決められたもの以外 出しません","start":286.99,"favorite":false,"stableId":"c5572e6d-921d-4fa6-ba6e-575fc180cd52","sequenceId":105},{"id":106,"end":291.71,"note":"","text":"出しちゃいけないんですか？","start":290.39,"favorite":false,"stableId":"dffedc4b-e785-4b9c-85d3-b506d5890305","sequenceId":106},{"id":107,"end":293.31,"note":"","text":"いけなくはありませんが…","start":291.76,"favorite":false,"stableId":"0c0292e6-4f65-4441-afad-4dd204606874","sequenceId":107},{"id":108,"end":295.21,"note":"","text":"-まず 出しません-まず","start":293.36,"favorite":false,"stableId":"621b035f-8bee-4f49-a07e-d360eae1d9a0","sequenceId":108},{"id":109,"end":297.51,"note":"","text":"余計なことは考えてくださらなくて結構","start":295.26,"favorite":false,"stableId":"18f01d5c-8497-488c-9851-fd577360fe84","sequenceId":109},{"id":110,"end":301.2,"note":"","text":"そのまとめを参考に聞かれたことだけに答えてください","start":297.56,"favorite":false,"stableId":"580618c7-310e-4b88-9927-733db578b3e4","sequenceId":110},{"id":111,"end":304,"note":"","text":"それぐらいは できますよね？","start":302.24,"favorite":false,"stableId":"d1383549-56f9-4860-b593-dcb58bafd449","sequenceId":111},{"id":112,"end":310.11,"note":"","text":"はい","start":308.54,"favorite":false,"stableId":"5eb13cbf-bb33-4ede-a1d0-d4096de8a886","sequenceId":112},{"id":113,"end":314.11,"note":"","text":"人 少なっ","start":311.78,"favorite":false,"stableId":"4283497d-ead4-4c54-91d3-a25eebcaa17a","sequenceId":113},{"id":114,"end":317.68,"note":"","text":"世間は飽きるの早いな～","start":314.75,"favorite":false,"stableId":"90d725de-311d-4b8c-99c9-397f2410d476","sequenceId":114},{"id":115,"end":320.8,"note":"","text":"まあ量刑 争うだけの裁判だからね","start":317.78,"favorite":false,"stableId":"20986e4b-a11a-4ae4-8bc1-6594086306b4","sequenceId":115},{"id":116,"end":323.34,"note":"","text":"妻を殺したって夫は認めてるんですよね？","start":320.85,"favorite":false,"stableId":"d273e16a-84d9-49e0-b75b-3ef43f888dfa","sequenceId":116},{"id":117,"end":326.93,"note":"","text":"まあ でも 殺害時は心神耗弱(こうじゃく)状態にあったと主張してる","start":323.39,"favorite":false,"stableId":"b56cac6c-5065-40b4-bb01-db953b5a57ab","sequenceId":117},{"id":118,"end":329.58,"note":"","text":"情状酌量の余地がどれだけあるかが争点","start":327.16,"favorite":false,"stableId":"d22907f0-2870-4e9c-b449-24e119d988a6","sequenceId":118},{"id":119,"end":331.08,"note":"","text":"地味すぎて寝ちゃいそう","start":329.63,"favorite":false,"stableId":"5941c9ba-7ad3-42c8-956f-466331436653","sequenceId":119},{"id":120,"end":334.1,"note":"","text":"“異議あり！”とかってめったにないらしいよ","start":331.13,"favorite":false,"stableId":"32bf7569-e655-4345-b12f-6d7dd2a268b8","sequenceId":120},{"id":121,"end":337.2,"note":"","text":"私も言われたとおり淡々と証言してくるわ","start":334.33,"favorite":false,"stableId":"b4cea1c2-9ae6-4e1f-a6f4-ab49f5092235","sequenceId":121},{"id":122,"end":338.87,"note":"","text":"私も言われたとおり淡々と証言してくるわ","start":337.2,"favorite":false,"stableId":"ff5c0ccb-95fa-46dd-a84f-86abb4b8b285","sequenceId":122},{"id":123,"end":342.31,"note":"","text":"来ました 桜小路要一","start":339.84,"favorite":false,"stableId":"9303e170-6c72-4288-b7c2-e40dd893f4c7","sequenceId":123},{"id":124,"end":345.19,"note":"","text":"-大丈夫ですか？-殺すより殺されそうな…","start":342.48,"favorite":false,"stableId":"f66a470b-5c93-43de-9071-54c7b83be342","sequenceId":124},{"id":125,"end":346.73,"note":"","text":"ああいう人ほど","start":345.24,"favorite":false,"stableId":"f1cdc4d5-2fd6-40dc-afbc-577ed4608ee6","sequenceId":125},{"id":126,"end":349.83,"note":"","text":"カーっとなったらブスーッてやんのよ","start":346.78,"favorite":false,"stableId":"eda2d917-f805-4ec2-aef6-958a9c837cc6","sequenceId":126},{"id":127,"end":351.02,"note":"","text":"ご起立ください","start":349.88,"favorite":false,"stableId":"92467354-f1df-40e2-b9ea-f1a0c507be94","sequenceId":127},{"id":128,"end":359.03,"note":"","text":"着席ください","start":357.22,"favorite":false,"stableId":"dc3bcdbb-c65e-4e0a-bff5-83077a6c540e","sequenceId":128},{"id":129,"end":361.59,"note":"","text":"開廷します","start":359.96,"favorite":false,"stableId":"e040c2b6-0a88-4dd7-8d8a-a97b78e22c5d","sequenceId":129},{"id":130,"end":364.11,"note":"","text":"名前を教えてください","start":362.56,"favorite":false,"stableId":"c5de78c9-1794-4fa3-b052-01e1ed850453","sequenceId":130},{"id":131,"end":366.65,"note":"","text":"桜小路要一です","start":364.16,"favorite":false,"stableId":"b03e8a9e-d1fe-4e2f-b815-83d9e4d51014","sequenceId":131},{"id":132,"end":367.65,"note' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || '":"","text":"職業は？","start":366.7,"favorite":false,"stableId":"d089cde2-d464-450f-8ad1-ab6c8d9d4b6c","sequenceId":132},{"id":133,"end":369.15,"note":"","text":"無職です","start":367.7,"favorite":false,"stableId":"eee2976e-20d2-4bc1-85e6-d68a75299e06","sequenceId":133},{"id":134,"end":370.29,"note":"","text":"生年月日は？","start":369.2,"favorite":false,"stableId":"4b2f1a5d-ca60-43e0-a067-4600702f3782","sequenceId":134},{"id":135,"end":371.84,"note":"","text":"昭和…","start":370.34,"favorite":false,"stableId":"29e91e7c-771f-4b9d-b23b-995d121e7882","sequenceId":135},{"id":136,"end":375.63,"note":"","text":"遺体を発見したのは被害者のマネージャーです","start":372.11,"favorite":false,"stableId":"6d586022-f8d1-43e6-9b1b-015ee5d6a1b4","sequenceId":136},{"id":137,"end":376.76,"note":"","text":"おはようございまーす","start":375.68,"favorite":false,"stableId":"1a9af1a2-20c6-47cb-954f-801730ed586b","sequenceId":137},{"id":138,"end":379.83,"note":"","text":"取材の予定があり朝８時に迎えに来たところ","start":376.81,"favorite":false,"stableId":"7582a0cd-dcf0-4177-8bba-8e7a778e04e4","sequenceId":138},{"id":139,"end":384.1,"note":"","text":"リビングで被害者が倒れており既に 絶命しておりました","start":379.88,"favorite":false,"stableId":"8201c440-ed55-4b4d-b571-fa0788c290b1","sequenceId":139},{"id":140,"end":385.94,"note":"","text":"しずく… さん？","start":384.15,"favorite":false,"stableId":"cf6b81e6-4803-4c6c-bd42-b985d1de5288","sequenceId":140},{"id":141,"end":388.14,"note":"","text":"通報を受け駆けつけた警察官が","start":385.99,"favorite":false,"stableId":"50be844e-f3ae-4be7-91bd-bcf7ad968618","sequenceId":141},{"id":142,"end":389.87,"note":"","text":"家の中を捜索","start":388.19,"favorite":false,"stableId":"12306080-d99c-4f1b-b99a-d2d7d2aa8633","sequenceId":142},{"id":143,"end":393.63,"note":"","text":"２階の部屋で眠っていた被告人を発見しました","start":389.92,"favorite":false,"stableId":"a12a4e70-5bf9-42e2-bd02-51bdc1aa329d","sequenceId":143},{"id":144,"end":396.71,"note":"","text":"“リビングで奥さんが死んでいる”と伝えたところ…","start":393.73,"favorite":false,"stableId":"9cb9d35e-2f23-41de-928e-4611d431a5d3","sequenceId":144},{"id":145,"end":398.88,"note":"","text":"夢じゃなかったのか…","start":396.76,"favorite":false,"stableId":"fcd0b48d-6795-4341-b47a-e536e7dd3d11","sequenceId":145},{"id":146,"end":402.92,"note":"","text":"…と 犯行をほのめかしたため任意で取り調べをしたところ","start":398.93,"favorite":false,"stableId":"c5fb0a75-1a3a-4422-a5ce-2f3a8e0284ec","sequenceId":146},{"id":147,"end":406.31,"note":"","text":"殺害を自供 逮捕に至りました","start":402.97,"favorite":false,"stableId":"cb54303d-e1d9-4c24-98e8-2c9a0e5bfa76","sequenceId":147},{"id":148,"end":411.01,"note":"","text":"遺体を発見した時どう思いましたか？","start":407.57,"favorite":false,"stableId":"68ca21d9-a060-46e1-bd7f-ac8e4ffbc994","sequenceId":148},{"id":149,"end":415.61,"note":"","text":"要一さんついに殺しちゃったかって","start":411.61,"favorite":false,"stableId":"7644d6d2-4bc4-4dc5-b318-e1ce8cbb634c","sequenceId":149},{"id":150,"end":418.6,"note":"","text":"夫婦は かなり ぜいたくな暮らしをしていたようですが","start":415.72,"favorite":false,"stableId":"d6e230e9-7e2d-47ae-8afb-e97e012e6183","sequenceId":150},{"id":151,"end":420.74,"note":"","text":"それは しずくさんの収入のおかげでしょうか？","start":418.65,"favorite":false,"stableId":"d6282e39-9ca8-4663-90be-f15091b18bdd","sequenceId":151},{"id":152,"end":422.31,"note":"","text":"いいえ","start":420.79,"favorite":false,"stableId":"77859819-d075-4063-9a20-5bd5aec9769c","sequenceId":152},{"id":153,"end":426.06,"note":"","text":"要一さんが 両親から引き継いだ資産のおかげです","start":422.36,"favorite":false,"stableId":"32481d17-f298-4b17-b162-63cb1c3084cb","sequenceId":153},{"id":154,"end":428.61,"note":"","text":"“無職”と ののしられていたが","start":426.63,"favorite":false,"stableId":"6e197fd1-460b-4d0e-9b21-0b2f68beab6b","sequenceId":154},{"id":155,"end":431.13,"note":"","text":"財産は被告人のものであったと","start":428.66,"favorite":false,"stableId":"3dc8d776-eb5f-485f-83e7-86897516beb2","sequenceId":155},{"id":156,"end":434.08,"note":"","text":"はい　それなのに しずくさんは","start":431.36,"favorite":false,"stableId":"13e905ba-6cc4-4e66-bd62-705855f67002","sequenceId":156},{"id":157,"end":436.62,"note":"","text":"感謝するどころか要一さんをバカにしています","start":434.13,"favorite":false,"stableId":"afce6d87-06ec-4b70-a4a7-b9874d1ee7d6","sequenceId":157},{"id":158,"end":437.8,"note":"","text":"これ","start":436.67,"favorite":false,"stableId":"b3c3a591-be65-4dd0-9054-67481e23ccb3","sequenceId":158},{"id":159,"end":439.29,"note":"","text":"何？　それ","start":438.1,"favorite":false,"stableId":"b60576ae-c3c6-4e7f-8510-5f4a872efe60","sequenceId":159},{"id":160,"end":440.94,"note":"","text":"気持ち悪い","start":439.34,"favorite":false,"stableId":"8a3d67ed-8c5a-4fac-b428-07d96701fd0e","sequenceId":160},{"id":161,"end":445.63,"note":"","text":"要一さんは 義理の弟の私にも","start":442.21,"favorite":false,"stableId":"1fbc3aa2-4ec2-4f2b-8e80-1595dd27236d","sequenceId":161},{"id":162,"end":448.1,"note":"","text":"神田(かんだ)で京料理の店を出させてくれたし","start":445.68,"favorite":false,"stableId":"24dec0fe-bf2c-4f53-b231-5b96de330504","sequenceId":162},{"id":163,"end":450.28,"note":"","text":"よくしてくれていたんです","start":448.15,"favorite":false,"stableId":"d8299878-7b85-4478-b809-f75bca3c8788","sequenceId":163},{"id":164,"end":455.02,"note":"","text":"だから 姉と こんなことになる前に相談してほしかった","start":450.38,"favorite":false,"stableId":"b6fa2826-9f99-4756-94c6-63b94f5c9f38","sequenceId":164},{"id":165,"end":457.54,"note":"","text":"被告人はどういう性格ですか？","start":455.56,"favorite":false,"stableId":"425d5804-b395-4612-bcf4-bbe683187bca","sequenceId":165},{"id":166,"end":459.31,"note":"","text":"普段は温厚です","start":457.59,"favorite":false,"stableId":"796294a1-4aef-45c1-b730-216021d12cd2","sequenceId":166},{"id":167,"end":461.54,"note":"","text":"違う時もあったということですか？","start":459.36,"favorite":false,"stableId":"2f369589-e0e1-4810-883c-9c36415e2606","sequenceId":167},{"id":168,"end":464.23,"note":"","text":"一緒にゲームをしてた時","start":461.59,"favorite":false,"stableId":"8c43d9d2-2f3a-42ed-b341-07033aa720af","sequenceId":168},{"id":169,"end":466.65,"note":"","text":"負けたら ものすごくムキになって","start":464.36,"favorite":false,"stableId":"c7a94689-a93e-4053-b335-f23564e0d04a","sequenceId":169},{"id":170,"end":470.84,"note":"","text":"カッとなりやすいのかなって思ったことはありました","start":466.7,"favorite":false,"stableId":"a285603c-1e4a-4787-a3c4-fe6636002797","sequenceId":170},{"id":171,"end":473.76,"note":"","text":"刺し傷から推測される凶器は","start":471.17,"favorite":false,"stableId":"c80a627e-640f-475d-9dc0-ec47c4b79fa3","sequenceId":171},{"id":172,"end":477.29,"note":"","text":"刃渡り18から20センチ最大幅５センチ","start":473.81,"favorite":false,"stableId":"89d53b34-588e-452e-81b7-85f890e64312","sequenceId":172},{"id":173,"end":479.86,"note":"","text":"有尖片刃器(ゆうせんへんじんき)と呼ばれる形状です","start":477.34,"favorite":false,"stableId":"16c08942-52b4-4fed-8faf-605fbbe98b43","sequenceId":173},{"id":174,"end":481.2,"note":"","text":"有尖片刃器とは？","start":479.91,"favorite":false,"stableId":"6a8c1187-6106-41bb-a8bf-e4e3e89a921f","sequenceId":174},{"id":175,"end":484.1,"note":"","text":"簡単に言うと片刃の包丁のようなものです","start":481.25,"favorite":false,"stableId":"5c326113-67d9-49f9-a625-f3490619e82c","sequenceId":175},{"id":176,"end":486.7,"note":"","text":"供述明確化のため","start":484.15,"favorite":false,"stableId":"065e0daf-4021-4018-aa9b-df18c41dc5b6","sequenceId":176},{"id":177,"end":490.54,"note":"","text":"検察官請求証拠 甲第15号証を示します","start":486.75,"favorite":false,"stableId":"cc003319-4c58-45ad-8785-fe17becdc5a1","sequenceId":177},{"id":178,"end":493.36,"note":"","text":"現場のキッチンには４本の包丁がありました","start":490.59,"favorite":false,"stableId":"ff9f05bf-d138-4bf5-a7fa-f3a8213a68ee","sequenceId":178},{"id":179,"end":497.98,"note":"","text":"これが そのうちの１本です","start":494.53,"favorite":false,"stableId":"68e1409a-11d0-445d-88d3-5fa30600c5d9","sequenceId":179},{"id":180,"end":501.12,"note":"","text":"洗われていましたが科捜研での鑑定の結果","start":498.03,"favorite":false,"stableId":"9297d5cb-9585-49e9-a462-84fd17ae4389","sequenceId":180},{"id":181,"end":503.84,"note":"","text":"被害者の血液が検出されました","start":501.17,"favorite":false,"stableId":"0716057d-5640-4e11-9e79-d1a75bd59ddc","sequenceId":181},{"id":182,"end":506.56,"note":"","text":"この包丁についてどういったことが言えますか？","start":504.14,"favorite":false,"stableId":"a6f62501-334d-48a3-afc8-79dfbecbb6ee","sequenceId":182},{"id":183,"end":510.41,"note":"","text":"サイズと形状から 凶器と考えて…","start":506.61,"favorite":false,"stableId":"9a6fbae7-7481-4fba-b8d4-4993dcf605ea","sequenceId":183},{"id":184,"end":514,"note":"","text":"えー… 矛盾はしません","start":511.38,"favorite":false,"stableId":"e46d7067-657f-4661-8936-70a0a3831ad2","sequenceId":184},{"id":185,"end":518.52,"note":"","text":"矛盾しない　凶器と傷口が一致するということですね","start":514.05,"favorite":false,"stableId":"ccf85752-dac2-43b9-9fe8-308d08705397","sequenceId":185},{"id":186,"end":520.1,"note":"","text":"刺創管については？","start":518.79,"favorite":false,"stableId":"fee0ca13-e110-4f40-9d27-c9396e9f99a3","sequenceId":186},{"id":187,"end":524.39,"note":"","text":"刺創管というのは刺し傷の通り道のことで…","start":520.15,"favorite":false,"stableId":"4ef89071-8e0f-4bc0-a302-7f34fdd91a90","sequenceId":187},{"id":188,"end":526.61,"note":"","text":"-お疲れ-お疲れさまです","start":525.36,"favorite":false,"stableId":"b3adf6e5-6db2-4fec-8b00-8f73fb0161be","sequenceId":188},{"id":189,"end":528.54,"note":"","text":"緊張した～","start":526.66,"favorite":false,"stableId":"577ac75c-f6b6-4a39-b583-eaf2ad92774a","sequenceId":189},{"id":190,"end":531.55,"note":"","text":"こちらは 遺体のＣＴ画像をもとに","start":528.59,"favorite":false,"stableId":"fd79bbbb-61f2-4fec-9576-902e8ab2de2e","sequenceId":190},{"id":191,"end":535.23,"note":"","text":"刺し傷を正確に再現した３ＤＣＧです","start":531.6,"favorite":false,"stableId":"8954e6a3-f817-437a-9b0f-3c91dcee513c","sequenceId":191},{"id":192,"end":542.26,"note":"","text":"皮膚に 柄の痕が残るほど強い力で横向きに差し込まれた包丁は","start":536.3,"favorite":false,"stableId":"2b7b5075-e46a-485b-a192-a5c62ea94f1b","sequenceId":192},{"id":193,"end":546.33,"note":"","text":"肋骨(ろっこつ)に当たることなく正確に心臓を貫き","start":542.31,"favorite":false,"stableId":"217fe53c-aa03-4d62-a67a-f5eae404fa91","sequenceId":193},{"id":194,"end":548.51,"note":"","text":"背骨まで達しています","start":546.38,"favorite":false,"stableId":"2d966448-6b66-48e0-8257-e45be3c7053b","sequenceId":194},{"id":195,"end":550.73,"note":"","text":"精神科医から見ていかがでしょうか？","start":548.85,"favorite":false,"stableId":"16f774c5-601a-456f-b4b4-2ef51d09de0b","sequenceId":195},{"id":196,"end":553.9,"note":"","text":"弁護側は心神耗弱を主張していますが","start":550.78,"favorite":false,"stableId":"5837921e-1005-40ac-a02f-fa2d1726c75b","sequenceId":196},{"id":197,"end":556.49,"note":"","text":"朦朧(もうろう)とした状態で ここまで正確に刺し込めるものでしょうか？","start":553.95,"favorite":false,"stableId":"1cf2f7d7-dd9b-460b-99f4-5bf80aeac586","sequenceId":197},{"id":198,"end":557.64,"note":"","text":"朦朧(もうろう)とした状態で ここまで正確に刺し込めるものでしょうか？","start":556.49,"favorite":false,"stableId":"eeea57f9-030d-4a61-81d6-8340eb56b8c4","sequenceId":198},{"id":199,"end":559.09,"note":"","text":"ミコト","start":557.69,"favorite":false,"stableId":"aa4d9e4a-7736-494e-9e22-bc2c2cf1c839","sequenceId":199},{"id":200,"end":561.68,"note":"","text":"傍聴人は席についてください","start":559.26,"favorite":false,"stableId":"d83a6376-c6b6-43b6-b646-844c8f9eb95c","sequenceId":200},{"id":201,"end":564.08,"note":"","text":"-ミコト-すいません","start":561.73,"favorite":false,"stableId":"b76f860a-2d5d-457b-a1eb-91667bb08c6f","sequenceId":201},{"id":202,"end":567.23,"note":"","text":"先ほど証言した三澄ですが","start":564.13,"favorite":false,"stableId":"e545e321-538e-46bd-baee-4d8206221fa1","sequenceId":202},{"id":203,"end":570.84,"note":"","text":"誠に申し上げにくいんですが…","start":567.93,"favorite":false,"stableId":"eb2e7334-551b-4106-ad4d-ba7573f1b02d","sequenceId":203},{"id":204,"end":573.94,"note":"","text":"傷と凶器が矛盾しています","start":571.77,"favorite":false,"stableId":"b50e7f62-72eb-4dd8-98e7-5e0de3baa3f9","sequenceId":204},{"id":205,"end":582.88,"note":"","text":"先ほどの証言を撤回させてください","start":580.08,"favorite":false,"stableId":"25d3da03-ec55-4f3e-b511-30a0278819de","sequenceId":205},{"id":206,"end":586.72,"note":"","text":"こちらの包丁は凶器ではありません","start":583.92,"favorite":false,"stableId":"a8722331-c2d8-4480-bffe-bf978ef7178d","sequenceId":206},{"id":207,"end":594.99,"note":"","text":"♪～","start":590.22,"favorite":false,"stableId":"9019bae1-7658-406f-814e-9cb67c588ad3","sequenceId":207},{"id":208,"end":610.41,"note":"","text":"～♪","start":605.71,"favorite":false,"stableId":"9354e839-1e17-49fe-9db4-b92fb79ec12d","sequenceId":208},{"id":209,"end":616.93,"note":"","text":"“しずく事件の裁判”","start":615.38,"favorite":false,"stableId":"a675b01a-3fb2-48d8-8ad1-ebcfaaf2636e","sequenceId":209},{"id":210,"end":619.65,"note":"","text":"“トラブルで休廷”？","start":616.98,"favorite":false,"stableId":"f4b3b197-15f7-4d2a-8d9c-289b8ec02ac8","sequenceId":210},{"id":211,"end":627.54,"note":"","text":"-はい-ねえ","start":626.13,"favorite":false,"stableId":"e4d639ee-e595-422e-9c2e-c9d4592d4f4a","sequenceId":211},{"id":212,"end":629.51,"note":"","text":"凶器が間違いだったってどういうこと？","start":627.59,"favorite":false,"stableId":"501fba1a-50dc-473c-8c4a-2b2e5827d118","sequenceId":212},{"id":213,"end":630.76,"note":"","text":"あ… あの","start":629.56,"favorite":false,"stableId":"8e32347f-60a6-4796-bd22-55bd8bfd5571","sequenceId":213},{"id":214,"end":632.56,"note":"","text":"マジか","start":631.06,"favorite":false,"stableId":"dab16c29-f140-4741-905d-f9669576d069","sequenceId":214},{"id":215,"end":633.75,"note":"","text":"どうしたんすか？","start":632.67,"favorite":false,"stableId":"38a06f0b-b3e4-41a8-ae68-b382ec64ff1f","sequenceId":215},{"id":216,"end":637.15,"note":"","text":"しずく事件ひっくり返るかもしんねえぞ","start":633.8,"favorite":false,"stableId":"ecb85212-43cf-40c9-993d-bad818d75740","sequenceId":216},{"id":217,"end":639.66,"note":"","text":"背骨の傷を よく見てください","start":637.2,"favorite":false,"stableId":"32d77156-3b70-43e0-8634-68624df18151","sequenceId":217},{"id":218,"end":641.22,"note":"","text":"上が平面です","start":639.71,"favorite":false,"stableId":"5d63d5c7-9ce4-4914-9fe3-94f8764d533f","sequenceId":218},{"id":219,"end":643.96,"note":"","text":"断面がカタカナの“レ”の形","start":641.27,"favorite":false,"stableId":"d2a2891d-7a6a-4c62-9639-54c3c2049383","sequenceId":219},{"id":220,"end":647.53,"note":"","text":"これは 一般的な包丁の断面で右利き用です","start":644.01,"favorite":false,"stableId":"6d9b0466-f1f5-4c6e-b24e-4c010462aa92","sequenceId":220},{"id":221,"end":648.63,"note":"","text":"右利き用？","start":647.58,"favorite":false,"stableId":"7dd61c88-71a7-4aa0-8dcc-29c595b818a8","sequenceId":221},{"id":222,"end":650.63,"note":"","text":"ですが 被害者は左利きです","start":648.68,"favorite":false,"stableId":"00c33fb2-a3ca-4b9c-baa1-408c2acaeb8e","sequenceId":222},{"id":223,"end":652.6,"note":"","text":"右手首に腕時計","start":650.68,"favorite":false,"stableId":"6184a971-4928-4ac5-80fc-083cb6999e60","sequenceId":223},{"id":224,"end":655.44,"note":"","text":"ブログでも左手で包丁を握っていました","start":652.65,"favorite":false,"stableId":"c6a85311-9be7-4723-9b1e-f1632d696e90","sequenceId":224},{"id":225,"end":658.49,"note":"","text":"今 凶器とされているのも左利き用の包丁で","start":655.49,"favorite":false,"stableId":"1a871f85-f0fa-4687-9433-b24c8272b65f","sequenceId":225},{"id":226,"end":660.24,"note":"","text":"もしそれで刺していたら","start":658.66,"favorite":false,"stableId":"c34129d5-18a8-4515-a64d-a2d6f50f332e","sequenceId":226},{"id":227,"end":662.56,"note":"","text":"平面が下に来るはずなんです","start":660.29,"favorite":false,"stableId":"18afeec8-3aa4-421b-8b81-171953b62b67","sequenceId":227},{"id":228,"end":667.45,"note":"","text":"あの… こういう形に","start":665.3,"favorite":false,"stableId":"0c409fc7-c114-4b70-8f26-f6978e5405fc","sequenceId":228},{"id":229,"end":670.29,"note":"","text":"ＣＴ画像ではよく分からなかったものが","start":667.5,"favorite":false,"stableId":"572bd222-d7ec-459c-a2b9-8432f57884a2","sequenceId":229},{"id":230,"end":672.27,"note":"","text":"３ＤＣＧだと よく分かる","start":670.34,"favorite":false,"stableId":"602a17b6-4afa-4156-9c04-8e7ae7954124","sequenceId":230},{"id":231,"end":674.97,"note":"","text":"便利な時代ですね","start":672.54,"favorite":false,"stableId":"8465fd71-738a-4c52-9e0e-b8baa854249f","sequenceId":231},{"id":232,"end":677.69,"note":"","text":"判決前に気づけてホントによかったです","start":675.17,"favorite":false,"stableId":"d85ed879-b261-4273-95b1-d1130c9fefab","sequenceId":232},{"id":233,"end":680.9,"note":"","text":"ここまで準備するのにどれだけかかってると思ってんだ","start":677.74,"favorite":false,"stableId":"3b2d6abb-8a34-4f6b-abc1-ecd1e107f2a9","sequenceId":233},{"id":234,"end":681.96,"note":"","text":"半年だぞ","start":680.95,"favorite":false,"stableId":"14d2418d-d844-41f2-b4db-6cc5fd05cbb8","sequenceId":234},{"id":235,"end":685.37,"note":"","text":"烏田検事今後の打ち合わせを","start":682.01,"favorite":false,"stableId":"3c87c364-365e-4414-83f6-46e75d20f53b","sequenceId":235},{"id":236,"end":687.27,"note":"","text":"申し訳ありませんでした","start":685.42,"favorite":false,"stableId":"5afbf51b-9566-43da-8c45-94223f204e8f","sequenceId":236},{"id":237,"end":688.6,"note":"","text":"やれやれですね","start":687.32,"favorite":false,"stableId":"44aa88b3-ceb6-4e76-b47d-553943daa6d0","sequenceId":237},{"id":238,"end":691.36,"note":"","text":"証人の人選を誤りました","start":688.65,"favorite":false,"stableId":"281e4713-1556-4c0a-ac56-23f44f437f10","sequenceId":238},{"id":239,"end":695.63,"note":"","text":"これを","start":694.39,"favorite":false,"stableId":"21e39b96-9914-430a-9cd1-6b410440e8f6","sequenceId":239},{"id":240,"end":697.46,"note":"","text":"どうも…","start":696.13,"favorite":false,"stableId":"bfdd673c-7662-477e-b0a6-5691cf4775da","sequenceId":240},{"id":241,"end":702.07,"note":"","text":"お待たせしました","start":699.9,"favorite":false,"stableId":"8a4d5523-73c9-4489-abc7-61366d78aa01","sequenceId":241},{"id":242,"end":712.4,"note":"","text":"何ですって!?","start":711.41,"favorite":false,"stableId":"21249cfb-aff7-456b-835e-e3c36046bbde","sequenceId":242},{"id":243,"end":714.83,"note":"","text":"ですから 弁護側の証人として","start":712.45,"favorite":false,"stableId":"5c4beccd-7667-4b36-bd29-2a2c1e87d2a8","sequenceId":243},{"id":244,"end":716.6,"note":"","text":"裁判に出ることになってしまいました","start":714.88,"favorite":false,"stableId":"8653bf5a-222d-499d-a6ba-e6dea8c94c49","sequenceId":244},{"id":245,"end":718.03,"note":"","text":"信じがたいバカだな","start":716.65,"favorite":false,"stableId":"e6995e82-8be3-4175-a17c-52955beb34b9","sequenceId":245},{"id":246,"end":720.17,"note":"","text":"検察側の証人で出た人が","start":718.08,"favorite":false,"stableId":"a65d4f1b-a954-4b10-94be-7524c7bc6f60","sequenceId":246},{"id":247,"end":723.47,"note":"","text":"次の公判で 弁護側の証人なんて聞いたことないよ！","start":720.22,"favorite":false,"stableId":"74d0e77e-c3b2-4e0b-b4be-ff4591c466c7","sequenceId":247},{"id":248,"end":726.16,"note":"","text":"仕方なかったんです 成り行きで","start":723.52,"favorite":false,"stableId":"22256828-5948-422e-b6a3-e5a3d98929db","sequenceId":248},{"id":249,"end":728.83,"note":"","text":"実は 私…","start":727.03,"favorite":false,"stableId":"297466de-c4af-4ede-8f92-0ece3eb37dad","sequenceId":249},{"id":250,"end":731.55,"note":"","text":"妻を殺した覚えがないんです","start":729.43,"favorite":false,"stableId":"77ff919a-b2c6-41ff-911d-c00c7851b164","sequenceId":250},{"id":251,"end":734.18,"note":"","text":"-えっ？-どういうことですか？","start":731.6,"favorite":false,"stableId":"67ce9a18-15b2-448e-9a09-3bcd045d3cd4","sequenceId":251},{"id":252,"end":739.54,"note":"","text":"あの夜は いつものように自分の部屋にいました","start":734.23,"favorite":false,"stableId":"ee8b3411-c413-4b46-b5ed-2ddd8f5d7e48","sequenceId":252},{"id":253,"end":743.81,"note":"","text":"ずっと オンラインゲームをしてて","start":740.57,"favorite":false,"stableId":"8de8e452-6b44-42bb-bbe4-c9939a395501","sequenceId":253},{"id":254,"end":748.98,"note":"","text":"12時くらいに精神安定剤を飲んで寝たんですけど…","start":744.31,"favorite":false,"stableId":"349dcd56-cedc-4b67-b496-54975852333b","sequenceId":254},{"id":255,"end":755.89,"note":"","text":"夜中にトイレに行きたくなって…","start":753.19,"favorite":false,"stableId":"e9d137f6-3e0b-4332-bc09-5709c96e4e9a","sequenceId":255},{"id":256,"end":766.73,"note":"","text":"その時 血まみれの妻を見たんです","start":762.83,"favorite":false,"stableId":"f8940739-e084-494a-9567-61b02c6bfd56","sequenceId":256},{"id":257,"end":768.75,"note":"","text":"リアルな夢だな～って","start":767,"favorite":false,"stableId":"405dd622-c7ba-46e1-aa4d-5f7970d93232","sequenceId":257},{"id":258,"end":771.65,"note":"","text":"そのまま 部屋に戻って…","start":768.8,"favorite":false,"stableId":"ab849540-8fe1-4f13-a38f-2bad459c84af","sequenceId":258},{"id":259,"end":772.82,"note":"","text":"旦那さん","start":771.7,"favorite":false,"stableId":"b6de3471-2272-4165-a0df-3430e3496d6e","sequenceId":259},{"id":260,"end":774.26,"note":"","text":"-旦那さん-旦那さん？","start":772.87,"favorite":false,"stableId":"a31cf22a-2de3-411d-8b6f-2dd1e84cdcea","sequenceId":260},{"id":261,"end":775.49,"note":"","text":"旦那さんですよね？","start":774.31,"favorite":false,"stableId":"1cf8cbbb-6099-488a-960d-6ff280873d6a","sequenceId":261},{"id":262,"end":779.14,"note":"","text":"朝 起きたら警察の人に囲まれてて","start":775.54,"favorite":false,"stableId":"fb41ed9d-0166-4688-931e-a32f8cf8164b","sequenceId":262},{"id":263,"end":781.8' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || '6,"note":"","text":"妻が下で死んでるって言われて…","start":779.91,"favorite":false,"stableId":"a4119aec-099b-4702-8b93-3efc7a72fedf","sequenceId":263},{"id":264,"end":783.57,"note":"","text":"夢じゃなかったのか…","start":781.91,"favorite":false,"stableId":"0068323f-6fa6-4e5f-8b1d-6cbcc2e7d545","sequenceId":264},{"id":265,"end":786.54,"note":"","text":"そのまま警察に連れていかれて","start":783.62,"favorite":false,"stableId":"2d0e0329-1328-43ba-8ac6-463096614670","sequenceId":265},{"id":266,"end":788.39,"note":"","text":"“お前が殺したんだ！”","start":786.59,"favorite":false,"stableId":"d98df4c4-c8fd-4cf6-ab8f-130eea6f567a","sequenceId":266},{"id":267,"end":791.52,"note":"","text":"凶器はうちの台所にあった包丁で","start":788.89,"favorite":false,"stableId":"0f190499-f59b-4ae8-a569-d63cbeff7211","sequenceId":267},{"id":268,"end":795.41,"note":"","text":"妻の血も お前の指紋もついてるって言われて…","start":791.72,"favorite":false,"stableId":"159bb8d5-27c5-464b-803c-329525350594","sequenceId":268},{"id":269,"end":800.45,"note":"","text":"精神安定剤を飲んでるとよく記憶が飛ぶことがあるんで","start":795.46,"favorite":false,"stableId":"9fbd2020-874e-49be-99a9-d61a6cadd00e","sequenceId":269},{"id":270,"end":802.79,"note":"","text":"もしかしたら 覚えてないだけで","start":800.5,"favorite":false,"stableId":"f9d38a87-ba10-4e88-812a-ee448e0e2a82","sequenceId":270},{"id":271,"end":807.82,"note":"","text":"夢遊病みたいな感じでやっちゃったのかな～って","start":802.84,"favorite":false,"stableId":"ae804f0d-b5e6-48f5-8c1e-cd3f81b4dcc6","sequenceId":271},{"id":272,"end":811.48,"note":"","text":"それで殺害を認めてしまったんですか？","start":807.87,"favorite":false,"stableId":"a2db555b-6ed3-46eb-ace3-81b9f6b55728","sequenceId":272},{"id":273,"end":816.63,"note":"","text":"妻が死んだら楽になるって妄想することはあったし","start":811.91,"favorite":false,"stableId":"998e4ccf-2d49-410e-93fc-abe6364adf92","sequenceId":273},{"id":274,"end":819.49,"note":"","text":"でも 凶器が違うなら！","start":816.68,"favorite":false,"stableId":"d9c781cc-1974-423e-b6a5-3b3627e130e8","sequenceId":274},{"id":275,"end":823.31,"note":"","text":"ホ… ホントに違うんですか？","start":821.12,"favorite":false,"stableId":"2f74865d-9517-4341-86c5-dab28322ef14","sequenceId":275},{"id":276,"end":826.36,"note":"","text":"はい あの包丁ではありません","start":823.36,"favorite":false,"stableId":"f095fdbd-68e6-4351-826b-fb3e09d7eddf","sequenceId":276},{"id":277,"end":833.4,"note":"","text":"いくら何でも 殺すなんて…","start":828.29,"favorite":false,"stableId":"a3e7b953-810a-4cd0-b4f0-dfb8d5a367b3","sequenceId":277},{"id":278,"end":839.2,"note":"","text":"そんな恐ろしいことしてなくてよかった","start":834.8,"favorite":false,"stableId":"9f73db1e-be5a-4151-8f5c-032881b14d81","sequenceId":278},{"id":279,"end":841.87,"note":"","text":"よかった～！","start":839.94,"favorite":false,"stableId":"9e1c9d29-f9d9-4b28-9591-aae47f9ae382","sequenceId":279},{"id":280,"end":845.29,"note":"","text":"気が弱いがゆえの悲劇だったんです","start":842.91,"favorite":false,"stableId":"32304590-18f7-4cc1-af6d-44f9c2adc77f","sequenceId":280},{"id":281,"end":847.7,"note":"","text":"弱すぎるでしょう","start":845.34,"favorite":false,"stableId":"2b5b7b11-c718-43c2-a258-23e00da3926e","sequenceId":281},{"id":282,"end":849.93,"note":"","text":"それで なんで三澄さんが？","start":847.75,"favorite":false,"stableId":"d80e94f1-5806-4cf5-a482-0d7b47596eee","sequenceId":282},{"id":283,"end":851.7,"note":"","text":"他の法医学者に頼もうよ","start":849.98,"favorite":false,"stableId":"bdf69406-97d4-44cc-a912-f2f46a175972","sequenceId":283},{"id":284,"end":853.77,"note":"","text":"この状況で引き受けるやつはいませんよ","start":851.75,"favorite":false,"stableId":"e6d3163a-04aa-425f-9358-cb9d5b34f95e","sequenceId":284},{"id":285,"end":854.87,"note":"","text":"そうなの？","start":853.82,"favorite":false,"stableId":"0c7a8d25-0887-4441-ab17-df017b9290d1","sequenceId":285},{"id":286,"end":856.84,"note":"","text":"弁護側につく法医学者を見つけるのは","start":854.92,"favorite":false,"stableId":"afe0b3af-c4ac-44c4-928f-11b1143aba5d","sequenceId":286},{"id":287,"end":858.44,"note":"","text":"ただでさえ難しいそうです","start":856.89,"favorite":false,"stableId":"2127808f-959c-427d-bcd0-96afab660ab5","sequenceId":287},{"id":288,"end":861.04,"note":"","text":"お仲間の鑑定にケチをつけることになるし","start":858.49,"favorite":false,"stableId":"5e86e631-7468-4fa9-8ad7-b1df5d789481","sequenceId":288},{"id":289,"end":862.88,"note":"","text":"検察や警察を敵に回すことにもなる","start":861.09,"favorite":false,"stableId":"956ae4bc-93ed-483e-be4a-9e72102ce3e5","sequenceId":289},{"id":290,"end":864.11,"note":"","text":"敵に回さないでくれる？","start":862.93,"favorite":false,"stableId":"75b37fa1-90cc-45eb-a8ba-e9373bed8e2c","sequenceId":290},{"id":291,"end":866.78,"note":"","text":"ＵＤＩラボは中立公正な機関ですよね？","start":864.16,"favorite":false,"stableId":"8d541ecc-8aff-48e0-abbf-332ecbdcd7de","sequenceId":291},{"id":292,"end":868.22,"note":"","text":"理念は そうですけど","start":866.83,"favorite":false,"stableId":"afd8c7f4-8753-47a4-a391-0f655bb37f82","sequenceId":292},{"id":293,"end":870.52,"note":"","text":"だから 代理証人なんて引き受けるなと言ったんだ","start":868.27,"favorite":false,"stableId":"148d173f-2832-4521-adf8-6971ee5a6059","sequenceId":293},{"id":294,"end":873.89,"note":"","text":"もとはといえば中堂さんが訴えられたから","start":870.57,"favorite":false,"stableId":"0cd5aba2-0770-4a9a-a2b6-b0353e7c4d87","sequenceId":294},{"id":295,"end":875.32,"note":"","text":"訴えられてなくても俺は引き受けない","start":873.94,"favorite":false,"stableId":"47a6e03a-3f8a-4d79-ad9e-8d2d34f7b572","sequenceId":295},{"id":296,"end":877.84,"note":"","text":"お前は いちいち うかつなんだ","start":875.37,"favorite":false,"stableId":"8169e87d-356c-4e2a-89be-ada32276afee","sequenceId":296},{"id":297,"end":881.3,"note":"","text":"だからトラックごと水に沈められる","start":878.31,"favorite":false,"stableId":"b19f69b3-e48f-463c-a7c4-250d3b135f31","sequenceId":297},{"id":298,"end":882.5,"note":"","text":"それ 言われるとね","start":881.35,"favorite":false,"stableId":"abe661bf-760a-48b2-a5e9-c29b13c21e15","sequenceId":298},{"id":299,"end":884.25,"note":"","text":"何も言えませんね","start":882.55,"favorite":false,"stableId":"94a6b536-33f5-48f5-bd73-dfc85642d23e","sequenceId":299},{"id":300,"end":887.94,"note":"","text":"裁判 勝てるんですよね？","start":885.72,"favorite":false,"stableId":"3c821d8b-ba98-4741-8a8f-8769c1b0b934","sequenceId":300},{"id":301,"end":888.84,"note":"","text":"えっ？","start":887.99,"favorite":false,"stableId":"08415118-fec6-47fe-93e3-eff96d6793d6","sequenceId":301},{"id":302,"end":892.79,"note":"","text":"負ければＵＤＩラボの信用を失います","start":888.89,"favorite":false,"stableId":"1003dec6-f497-407d-8ac7-3c0ba50f2bdb","sequenceId":302},{"id":303,"end":897.7,"note":"","text":"大丈夫です","start":896.13,"favorite":false,"stableId":"0ceddd43-bf27-418b-9d2a-e6697feb2303","sequenceId":303},{"id":304,"end":901.92,"note":"","text":"人 増えてる","start":900.1,"favorite":false,"stableId":"b72452c1-513b-4272-ad62-7b83a93d4db1","sequenceId":304},{"id":305,"end":905.24,"note":"","text":"一転して無罪 主張してますから","start":901.97,"favorite":false,"stableId":"547694e7-053c-4f3d-800f-c1c84edc2fcf","sequenceId":305},{"id":306,"end":907.04,"note":"","text":"あっ すいません","start":905.47,"favorite":false,"stableId":"5e631da6-5e61-465d-a501-e5492133c67e","sequenceId":306},{"id":307,"end":910.09,"note":"","text":"シャツのボタン上まで 閉めてください","start":907.64,"favorite":false,"stableId":"3d07f02a-eaa0-4f41-83c5-b0e2066c117b","sequenceId":307},{"id":308,"end":912.08,"note":"","text":"はい？","start":910.14,"favorite":false,"stableId":"a05b8dbd-0a8e-44be-a96b-4bdefa0bafa7","sequenceId":308},{"id":309,"end":917.7,"note":"","text":"公判スケジュールの大幅な変更で裁判員が入れ替わり","start":913.81,"favorite":false,"stableId":"44486ebc-76cd-4e25-9037-28bd0667ec52","sequenceId":309},{"id":310,"end":920.67,"note":"","text":"ほぼ年配男性が占めることになってしまいました","start":917.75,"favorite":false,"stableId":"3b724f8e-3704-4aa5-905d-bda719f977b3","sequenceId":310},{"id":311,"end":924.14,"note":"","text":"若い女性ということが不利になるかもしれません","start":920.72,"favorite":false,"stableId":"17d6ecff-7583-44ed-8555-44be0db9c8e7","sequenceId":311},{"id":312,"end":926.08,"note":"","text":"若いってほど若くも…","start":924.19,"favorite":false,"stableId":"8432ac9e-77da-4da6-809e-4b589aa55896","sequenceId":312},{"id":313,"end":928.34,"note":"","text":"裁判長も保守的な人です","start":926.13,"favorite":false,"stableId":"a41fe4dd-27cd-4d25-8395-ec3f625ec6b9","sequenceId":313},{"id":314,"end":930.65,"note":"","text":"証言の撤回で心証も悪い","start":928.39,"favorite":false,"stableId":"ce4106be-cb42-4f25-9d1c-c8f783987730","sequenceId":314},{"id":315,"end":935.42,"note":"","text":"検察は 有罪率99.９％のプライドを懸けて","start":930.7,"favorite":false,"stableId":"d2018a23-ebb6-4b9e-be50-1eb74d1037a2","sequenceId":315},{"id":316,"end":937.9,"note":"","text":"全力で潰しに来るでしょう","start":935.47,"favorite":false,"stableId":"41195765-34d1-4e37-ac73-574fc655ac69","sequenceId":316},{"id":317,"end":940.96,"note":"","text":"包丁から検出された血液は","start":938.5,"favorite":false,"stableId":"dae628a5-c6c5-4909-acea-a86d131f99be","sequenceId":317},{"id":318,"end":942.19,"note":"","text":"事件の２日前","start":941.01,"favorite":false,"stableId":"71e4da2e-c8d8-4714-b20d-5c1c89df290f","sequenceId":318},{"id":319,"end":947.1,"note":"","text":"被害者が過って 指を切った際に出血した時のもので","start":942.24,"favorite":false,"stableId":"2f836ac6-b49e-4052-8d55-14eddf0d7198","sequenceId":319},{"id":320,"end":948.91,"note":"","text":"本件とは無関係です","start":947.15,"favorite":false,"stableId":"e8aa5c58-564b-47be-a21c-3e44ace45873","sequenceId":320},{"id":321,"end":950.7,"note":"","text":"被告人の指紋は","start":949.15,"favorite":false,"stableId":"9306c790-f8a0-44ba-94dd-cb43909b4f1b","sequenceId":321},{"id":322,"end":953.44,"note":"","text":"日常的に洗い物をさせられていたため","start":950.75,"favorite":false,"stableId":"16481c4a-d8bb-4331-bb43-906cb2a327a9","sequenceId":322},{"id":323,"end":955.82,"note":"","text":"ついていても不自然ではありません","start":953.49,"favorite":false,"stableId":"55f8c247-2db9-4085-b546-9e6d63f26736","sequenceId":323},{"id":324,"end":959.34,"note":"","text":"そもそも桜小路家のセラミック包丁は","start":956.12,"favorite":false,"stableId":"0732806b-8dbb-42e6-a0d9-c06a39d87f41","sequenceId":324},{"id":325,"end":962.21,"note":"","text":"すべて特注で 左利き用であり","start":959.39,"favorite":false,"stableId":"f2635076-7fdc-4083-9494-5bccf593e279","sequenceId":325},{"id":326,"end":965.28,"note":"","text":"どれも被害者の傷とは一致しません","start":962.26,"favorite":false,"stableId":"1962a236-c5a1-46e7-ab15-cefa48ab0b81","sequenceId":326},{"id":327,"end":967.72,"note":"","text":"これは 明らかな誤認逮捕です","start":965.33,"favorite":false,"stableId":"509b701e-ebd3-4069-b7c7-f95a55cda36b","sequenceId":327},{"id":328,"end":971.45,"note":"","text":"よって 被告人の無罪を主張します","start":967.77,"favorite":false,"stableId":"295ffb98-0757-4c96-92cd-7bd72d6f8c2e","sequenceId":328},{"id":329,"end":973.67,"note":"","text":"弁護人からは以上です","start":971.5,"favorite":false,"stableId":"90775494-dd57-40fa-a73d-29eb088734d0","sequenceId":329},{"id":330,"end":977.64,"note":"","text":"それでは 検察官立証をお願いします","start":973.84,"favorite":false,"stableId":"8b29dc6a-c08c-4069-93d7-5a1ea296f22d","sequenceId":330},{"id":331,"end":980.5,"note":"","text":"えー 草野(くさの)教授","start":979.21,"favorite":false,"stableId":"1e84c7d8-4099-4439-8014-20f3c31d10d4","sequenceId":331},{"id":332,"end":983.68,"note":"","text":"これまでの ご経歴を教えていただけますか？","start":980.55,"favorite":false,"stableId":"9d4f1920-9908-4b81-b6db-e724a6ee2220","sequenceId":332},{"id":333,"end":988.27,"note":"","text":"東都(とうと)大学 法医学教室で40年","start":983.95,"favorite":false,"stableId":"709f3a41-94fb-4ef6-9f1a-b91491a66514","sequenceId":333},{"id":334,"end":990.87,"note":"","text":"法医学に携わってまいりました","start":988.32,"favorite":false,"stableId":"fd22d472-261c-4949-813c-5d616a0b4e4a","sequenceId":334},{"id":335,"end":995.31,"note":"","text":"これまで１万5000体のご遺体を解剖しました","start":990.92,"favorite":false,"stableId":"e5e996f0-68ca-47af-850d-41701ffbe1f5","sequenceId":335},{"id":336,"end":996.76,"note":"","text":"１万５…","start":995.36,"favorite":false,"stableId":"c97f1f1d-a00d-4919-8088-e60fb66248df","sequenceId":336},{"id":337,"end":1000.62,"note":"","text":"この包丁についてどんなことが言えますか？","start":998.3,"favorite":false,"stableId":"7bd6fac0-b0fe-412d-b9c6-eb388aa610a0","sequenceId":337},{"id":338,"end":1004.02,"note":"","text":"そのサイズと形状から見て","start":1000.67,"favorite":false,"stableId":"a0dae659-9b7d-489b-8e78-bf5aed10d1d5","sequenceId":338},{"id":339,"end":1008.74,"note":"","text":"凶器と考えて差し支えないかと思われます","start":1004.07,"favorite":false,"stableId":"eca29254-6cdf-49d6-a36f-154aec024fbe","sequenceId":339},{"id":340,"end":1012.43,"note":"","text":"この凶器と刺し傷が不一致であると主張する⸺","start":1008.84,"favorite":false,"stableId":"79fa39df-67eb-4c14-8a54-9ee6923b9ff8","sequenceId":340},{"id":341,"end":1017.03,"note":"","text":"若い女性の法医学者がいるのですがどう思われますか？","start":1012.48,"favorite":false,"stableId":"9ce77970-d160-40ee-8173-180df37915a1","sequenceId":341},{"id":342,"end":1021.77,"note":"","text":"その方の解剖実績数はいかほどですか？","start":1017.08,"favorite":false,"stableId":"547c1867-cc52-4d5d-ba16-06d697a99763","sequenceId":342},{"id":343,"end":1026.38,"note":"","text":"草野教授の10分の１1500件程度と聞いております","start":1021.82,"favorite":false,"stableId":"c0fb5d82-c23b-4522-b28c-b594688e90a8","sequenceId":343},{"id":344,"end":1031.51,"note":"","text":"まあ 女性だということでチヤホヤされるんでしょうが","start":1026.43,"favorite":false,"stableId":"48ef4b3d-cc3a-4c41-bea9-817f99ab9c1d","sequenceId":344},{"id":345,"end":1036.49,"note":"","text":"最近は 未熟ながらもいっぱしの口を利く⸺","start":1031.56,"favorite":false,"stableId":"9ecc257e-0f5a-4be0-ac76-eb02c36bb94d","sequenceId":345},{"id":346,"end":1040.27,"note":"","text":"女性研究者が増えております","start":1036.54,"favorite":false,"stableId":"cbc82022-f8fb-4e6f-a924-92e0419e6038","sequenceId":346},{"id":347,"end":1042.62,"note":"","text":"信用に値しないと？","start":1040.37,"favorite":false,"stableId":"1848036f-f229-4eba-b0e3-81625c08c45c","sequenceId":347},{"id":348,"end":1044.03,"note":"","text":"はい","start":1042.67,"favorite":false,"stableId":"996d5cb3-4819-4430-bfb1-92a082b5621d","sequenceId":348},{"id":349,"end":1049.35,"note":"","text":"私は数多くの解剖実績を持っております","start":1044.08,"favorite":false,"stableId":"c5778a5e-43f6-4723-97db-6a5d05c7fcce","sequenceId":349},{"id":350,"end":1056.02,"note":"","text":"その形状から見て凶器と考えて 差し支えないかと","start":1049.68,"favorite":false,"stableId":"acec9d35-b3eb-4e1d-913e-9eb9090f4de8","sequenceId":350},{"id":351,"end":1060.94,"note":"","text":"この実験結果からも分かるように","start":1058.69,"favorite":false,"stableId":"dd711911-b7fe-4461-a158-2514a38e5150","sequenceId":351},{"id":352,"end":1065.15,"note":"","text":"ご遺体の刺し傷は 右利き用の包丁でつけられたものです","start":1060.99,"favorite":false,"stableId":"f4e3cd84-4b08-4562-b38c-dd4dc7892af2","sequenceId":352},{"id":353,"end":1069.82,"note":"","text":"今 凶器とされている包丁は左利き用なので 傷と矛盾します","start":1065.2,"favorite":false,"stableId":"b26414da-e91c-4cdd-b240-fdf867ac6518","sequenceId":353},{"id":354,"end":1071.57,"note":"","text":"矛盾するということは？","start":1069.87,"favorite":false,"stableId":"a450d39c-daeb-4cba-881e-4d923524c561","sequenceId":354},{"id":355,"end":1073.94,"note":"","text":"凶器ではないということです","start":1071.94,"favorite":false,"stableId":"082f4c36-3e60-4cd2-86fa-b5993544975d","sequenceId":355},{"id":356,"end":1076.59,"note":"","text":"見ていただければ分かるように","start":1074.54,"favorite":false,"stableId":"54650c4f-2fb4-4e12-bcc6-f634fa111639","sequenceId":356},{"id":357,"end":1081.71,"note":"","text":"右利き用と左利き用では傷の形が明らかに違うんです","start":1076.64,"favorite":false,"stableId":"d9f39568-74eb-4e86-b54d-ec0e30c95880","sequenceId":357},{"id":358,"end":1084.47,"note":"","text":"法医学の権威である草野教授は","start":1081.88,"favorite":false,"stableId":"a8f904c9-a8d8-472d-a82e-eb4eadd19942","sequenceId":358},{"id":359,"end":1086.34,"note":"","text":"左利き用の包丁であっても","start":1084.52,"favorite":false,"stableId":"8b62dfc4-0dc6-4332-b61b-36a67d19d59b","sequenceId":359},{"id":360,"end":1089.32,"note":"","text":"あのような傷が残ることがあるとおっしゃっています","start":1086.39,"favorite":false,"stableId":"457d5ff6-282b-44b3-8f38-34afd35c966d","sequenceId":360},{"id":361,"end":1092.11,"note":"","text":"その事例の鑑定書を見せてください","start":1089.49,"favorite":false,"stableId":"fcfbe1ae-5aca-4271-98a6-7e9020bf648a","sequenceId":361},{"id":362,"end":1095.94,"note":"","text":"あなたは草野教授の１万5000件に及ぶ⸺","start":1092.16,"favorite":false,"stableId":"2fee64ec-5519-4cd6-b4bd-c588d18fabac","sequenceId":362},{"id":363,"end":1098.48,"note":"","text":"解剖実績を否定なさるんですか？","start":1095.99,"favorite":false,"stableId":"f0667186-3211-498f-9b49-fe91e3a1b287","sequenceId":363},{"id":364,"end":1101.12,"note":"","text":"あなたのほうが優秀だと？","start":1098.53,"favorite":false,"stableId":"ff1ac4c8-4f77-4ab7-aec3-d468599e0e22","sequenceId":364},{"id":365,"end":1102.65,"note":"","text":"この事例に関しては","start":1101.17,"favorite":false,"stableId":"741f32a0-fe31-4e03-8f4d-93365e41b63f","sequenceId":365},{"id":366,"end":1105.62,"note":"","text":"草野教授の見解が間違っていると思います","start":1102.7,"favorite":false,"stableId":"b3883504-716a-4d73-bab4-2a8441fa73f8","sequenceId":366},{"id":367,"end":1109.76,"note":"","text":"前回 あなたは検察側の証人として法廷に出廷し","start":1105.67,"favorite":false,"stableId":"e654f647-5279-41b8-9c83-038074726a6d","sequenceId":367},{"id":368,"end":1113.96,"note":"","text":"その時 “凶器は この包丁に間違いない”と証言したんですよ","start":1109.81,"favorite":false,"stableId":"1db9a2e9-f4a3-4e15-9699-6fd141b852bd","sequenceId":368},{"id":369,"end":1115.98,"note":"","text":"“矛盾しない”と言ったんです","start":1114.01,"favorite":false,"stableId":"ac10a937-14bf-40ee-8001-8893647dbad1","sequenceId":369},{"id":370,"end":1121.95,"note":"","text":"どうして意見を変えたんでしょう？","start":1119.05,"favorite":false,"stableId":"8ac0fda5-a6be-4125-8eb6-8b390737df27","sequenceId":370},{"id":371,"end":1124.67,"note":"","text":"３ＤＣＧを見て矛盾に気づいたからです","start":1122.05,"favorite":false,"stableId":"337546e8-b4a3-4294-95d7-21a3c78cba8c","sequenceId":371},{"id":372,"end":1126.61,"note":"","text":"どうして事前に確認しなかったんですか？","start":1124.72,"favorite":false,"stableId":"85e875ad-390e-4466-9075-8444e6bf9a9f","sequenceId":372},{"id":373,"end":1130.55,"note":"","text":"証言するにあたって必要な証拠確認を怠った","start":1126.66,"favorite":false,"stableId":"e8f2f3d2-974b-4f2c-be88-ecc1bedd3390","sequenceId":373},{"id":374,"end":1131.75,"note":"","text":"そういうことですよね？","start":1130.6,"favorite":false,"stableId":"f60eba93-a6b5-4448-b808-9edbd21a1467","sequenceId":374},{"id":375,"end":1135.25,"note":"","text":"それは… ３ＤＣＧがあると知らなかったので","start":1131.8,"favorite":false,"stableId":"b20a04e8-5ba4-4060-a9fa-16d8ce8467fe","sequenceId":375},{"id":376,"end":1136.72,"note":"","text":"なぜ 知らなかったんですか？","start":1135.3,"favorite":false,"stableId":"5bf7a15e-8f86-4d39-bee8-66e624982bf0","sequenceId":376},{"id":377,"end":1140.06,"note":"","text":"いや… 烏田さんが教えてくださらなかったんじゃないですか","start":1136.77,"favorite":false,"stableId":"09f3fce1-bc71-4952-8615-a9824d4fed5a","sequenceId":377},{"id":378,"end":1142.66,"note":"","text":"-余計なことはするなって-人のせいですか","start":1140.11,"favorite":false,"stableId":"03bb1cbe-22c6-4ed3-b88b-9d6c4bb0138d","sequenceId":378},{"id":379,"end":1145.91,"note":"","text":"責任転嫁は女性の特徴です","start":1142.71,"favorite":false,"stableId":"6c809635-c09f-4b93-9326-1201776ba0b2","sequenceId":379},{"id":380,"end":1147.06,"note":"","text":"はあ？","start":1146.11,"favorite":false,"stableId":"deb0d213-d6b7-4098-aedb-4943ddb6c3c9","sequenceId":380},{"id":381,"end":1150.67,"note":"","text":"自分の確認不足を棚に上げて すべて人のせいにして","start":1147.11,"favorite":false,"stableId":"a2ad7bf4-ef17-4ed7-96e1-fc58ef018ec3","sequenceId":381},{"id":382,"end":1153.32,"note":"","text":"相手を感情的に責める","start":1150.72,"favorite":false,"stableId":"97d245f2-cb1a-4fab-a7c6-07e8cba08b45","sequenceId":382},{"id":383,"end":1156.94,"note":"","text":"彼氏が相手なら結構ですがここは法廷です","start":1153.55,"favorite":false,"stableId":"d476703a-8322-4c7f-9b53-bd0e4ac85fd0","sequenceId":383},{"id":384,"end":1160.51,"note":"","text":"異議あり！証人に対する侮辱です","start":1156.99,"favorite":false,"stableId":"ed65ab64-5c89-44e8-8a27-0e9af40f48c1","sequenceId":384},{"id":385,"end":1161.64,"note":"","text":"認めます","start":1160.56,"favorite":false,"stableId":"1e149e85-c866-43e8-8c11-eaaa945c554b","sequenceId":385},{"id":386,"end":1162.91,"note":"","text":"失礼しました","start":1161.69,"favorite":false,"stableId":"3a7c62dc-a5c9-4967-bc9d-921fc6703091","sequenceId":386},{"id":387,"end":1165.88,"note":"","text":"いや しかし 証言のたびに意見をコロコロ変えられては","start":1162.96,"favorite":false,"stableId":"7f80b32e-7ef2-4c3f-8b7c-d7b020f341a2","sequenceId":387},{"id":388,"end":1168.97,"note":"","text":"裁判員の皆さんも混乱します","start":1165.93,"favorite":false,"stableId":"1528711a-bc30-477a-b3ee-bcb341c0a0c6","sequenceId":388},{"id":389,"end":1174.02,"note":"","text":"未熟な女性研究者の口車に被告人まで乗せられてしまった","start":1169.13,"favorite":false,"stableId":"c56481f0-ab63-4e36-b8a6-3a651459e51d","sequenceId":389},{"id":390,"en' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || 'd":1175.62,"note":"","text":"神聖なる司法の場が","start":1174.07,"favorite":false,"stableId":"434bee88-ce5f-45ec-bba0-0d527825e644","sequenceId":390},{"id":391,"end":1179.93,"note":"","text":"女性の気まぐれで振り回されるとはゆゆしき事態です","start":1175.67,"favorite":false,"stableId":"a0bb6224-addc-47b9-a9e8-97648e639ce4","sequenceId":391},{"id":392,"end":1181.86,"note":"","text":"-異議あり-気まぐれではありません","start":1179.98,"favorite":false,"stableId":"38f6aa14-3ffe-47d2-9b62-e72ea5cf0d40","sequenceId":392},{"id":393,"end":1185.7,"note":"","text":"私は法医学者として鑑定の事実を言っているんです","start":1181.91,"favorite":false,"stableId":"a7b3451b-e1b0-40d1-b408-e1c0851fa6c5","sequenceId":393},{"id":394,"end":1188.07,"note":"","text":"ああ～ これだすぐ感情的になる","start":1185.75,"favorite":false,"stableId":"80e4789f-c710-4149-8cfa-b1cef4273849","sequenceId":394},{"id":395,"end":1191.24,"note":"","text":"自己顕示欲が強いのは結構ですが","start":1188.12,"favorite":false,"stableId":"74721996-efe3-4271-8878-ea87041fbec0","sequenceId":395},{"id":396,"end":1195.01,"note":"","text":"法廷は あなたの自己アピールの場ではありません","start":1191.29,"favorite":false,"stableId":"40ae5b3d-8f0d-425c-91be-79bee212ce0a","sequenceId":396},{"id":397,"end":1197.5,"note":"","text":"-裁判長！-以上です","start":1195.06,"favorite":false,"stableId":"f21313d2-3bee-42d2-888f-bf6c20de646e","sequenceId":397},{"id":398,"end":1199.46,"note":"","text":"待ってください","start":1198.1,"favorite":false,"stableId":"b11abef9-9900-489d-ac11-d42e08ef87f0","sequenceId":398},{"id":399,"end":1204.1,"note":"","text":"私個人と証拠の価値は関係ないですよね","start":1200.33,"favorite":false,"stableId":"5f272c70-3b0d-43c8-9c5c-579d00ef89b5","sequenceId":399},{"id":400,"end":1208.86,"note":"","text":"女 女って 好きで女に生まれてきたわけではありません","start":1205.57,"favorite":false,"stableId":"a6defedf-9e65-4aca-a234-ef88ffd85d4c","sequenceId":400},{"id":401,"end":1210.93,"note":"","text":"あなたは選べたんですか？生まれてくる時に","start":1208.91,"favorite":false,"stableId":"08ef3c90-acc4-40d2-b529-8990aee387d3","sequenceId":401},{"id":402,"end":1211.93,"note":"","text":"誰だって選べませんよね？","start":1210.98,"favorite":false,"stableId":"f40eaad2-56b0-4b61-9e66-49f921f77c2a","sequenceId":402},{"id":403,"end":1213.55,"note":"","text":"三澄さん！","start":1211.98,"favorite":false,"stableId":"64049570-bf9f-4807-bb18-2b9d6e7f3c5b","sequenceId":403},{"id":404,"end":1227.68,"note":"","text":"ひっくり返りそうもない？","start":1225.92,"favorite":false,"stableId":"c76e1345-3cd0-4382-9f7a-098702bc49d9","sequenceId":404},{"id":405,"end":1230.9,"note":"","text":"ああ でも 記事にはなる","start":1227.73,"favorite":false,"stableId":"a6e24c9a-d7a3-417f-bb26-c2ddef4772f2","sequenceId":405},{"id":406,"end":1232.71,"note":"","text":"楽しみに待っといて","start":1231.2,"favorite":false,"stableId":"f2956585-b83a-48ea-a0cc-67eef63a001b","sequenceId":406},{"id":407,"end":1235.87,"note":"","text":"“感情的な女”みたいになってたよ","start":1232.76,"favorite":false,"stableId":"a02d0af0-d5d5-4ae0-a6e5-e769c6a72c3b","sequenceId":407},{"id":408,"end":1239.42,"note":"","text":"どうも ありがとう","start":1236.2,"favorite":false,"stableId":"a5f6b725-abc5-4fd0-85fe-a65512f1c17c","sequenceId":408},{"id":409,"end":1242.09,"note":"","text":"策に乗ってしまいましたね","start":1239.47,"favorite":false,"stableId":"ecad4c02-762f-4483-aa8a-e974cc73ece5","sequenceId":409},{"id":410,"end":1243.46,"note":"","text":"すいませんでした","start":1242.14,"favorite":false,"stableId":"a0fed6fb-ece2-4837-bd51-7a5c30b71f72","sequenceId":410},{"id":411,"end":1245.13,"note":"","text":"いえ 仕方ありません","start":1243.51,"favorite":false,"stableId":"eaa8b54e-f5ac-4bc5-8944-5dad24166ea4","sequenceId":411},{"id":412,"end":1248.43,"note":"","text":"相手は白いものも黒くする烏田検事です","start":1245.18,"favorite":false,"stableId":"e4eecd1f-4514-4449-b278-a601679ce81d","sequenceId":412},{"id":413,"end":1249.73,"note":"","text":"そんな異名が","start":1248.48,"favorite":false,"stableId":"fdc826e5-655b-490a-a015-65caeda794a5","sequenceId":413},{"id":414,"end":1251.68,"note":"","text":"来たよ カラス","start":1249.78,"favorite":false,"stableId":"1a6c9711-c3f1-4ab0-bad6-44a6ed4d0fe9","sequenceId":414},{"id":415,"end":1254.37,"note":"","text":"-お疲れさまでした-お疲れさまでした","start":1252.32,"favorite":false,"stableId":"a2a40aa6-e9a2-47e9-aa9a-2952d34c742b","sequenceId":415},{"id":416,"end":1259.59,"note":"","text":"いや～ あなたのような女性に弁護側についてもらえてよかった","start":1254.42,"favorite":false,"stableId":"ce3bc3d2-39b2-49b3-95ea-7a0b9be7e4db","sequenceId":416},{"id":417,"end":1265.4,"note":"","text":"ミコト…","start":1262.16,"favorite":false,"stableId":"715fa451-eefc-4583-b990-18a114999630","sequenceId":417},{"id":418,"end":1269.77,"note":"","text":"ダメよ ダメ感情的になったら負けだから","start":1265.96,"favorite":false,"stableId":"7fadf71b-7e43-4823-88f3-7851e10aaedd","sequenceId":418},{"id":419,"end":1272.99,"note":"","text":"負けだけど 人間だもの","start":1269.97,"favorite":false,"stableId":"c1d778c6-3948-4bf1-967b-be8c0aae45a6","sequenceId":419},{"id":420,"end":1275.34,"note":"","text":"-感情的になるべき？-べきじゃない？","start":1273.04,"favorite":false,"stableId":"97462be7-d2a2-49f6-ae11-85df11d25166","sequenceId":420},{"id":421,"end":1277.54,"note":"","text":"-いざ-いざ！","start":1275.81,"favorite":false,"stableId":"32cf94d7-3277-4102-a691-3b3c7d2a56f0","sequenceId":421},{"id":422,"end":1279.7,"note":"","text":"よっ！","start":1278.54,"favorite":false,"stableId":"9ae29bac-7465-4edd-96fe-60d1995a6a1a","sequenceId":422},{"id":423,"end":1281.46,"note":"","text":"よっ！　うおっ","start":1279.75,"favorite":false,"stableId":"a4b43e60-f4cd-4374-8a18-0549e61af728","sequenceId":423},{"id":424,"end":1285.67,"note":"","text":"出ました距離１.３ 速度125 深さ16です","start":1281.51,"favorite":false,"stableId":"ee922ac9-f5eb-4952-8fbd-2998822db5eb","sequenceId":424},{"id":425,"end":1289.07,"note":"","text":"ちょっと 何やってるの？その肉 いくらしたの!?","start":1285.72,"favorite":false,"stableId":"b9c1739a-7aab-442d-91f1-a412e8f485c5","sequenceId":425},{"id":426,"end":1290.61,"note":"","text":"-いざ！-証言なんて⸺","start":1289.12,"favorite":false,"stableId":"225b53bc-aa97-499a-aff3-a73398d91d21","sequenceId":426},{"id":427,"end":1292.27,"note":"","text":"ボランティアみたいなもんだから大赤字じゃない","start":1290.66,"favorite":false,"stableId":"327bdc5b-f118-4b9d-9a3c-e060a4ab01f9","sequenceId":427},{"id":428,"end":1294.79,"note":"","text":"-よっ… おおっ！-おっ！　おおっ！","start":1292.32,"favorite":false,"stableId":"63a109ca-a910-47fa-b9ad-1cdfa5bbe257","sequenceId":428},{"id":429,"end":1296.65,"note":"","text":"-自腹です-自腹!?","start":1295.09,"favorite":false,"stableId":"f7b408f9-d879-4f53-9b01-d56ff33ae53b","sequenceId":429},{"id":430,"end":1299.51,"note":"","text":"こんな大きな買い物全自動洗濯機を買って以来です","start":1296.7,"favorite":false,"stableId":"8a42245d-33a1-4cdb-b172-17e18df74ec3","sequenceId":430},{"id":431,"end":1301.25,"note":"","text":"思いきったね～","start":1299.56,"favorite":false,"stableId":"bf5bd045-54b3-41e8-a4fe-17f394bede9c","sequenceId":431},{"id":432,"end":1302.5,"note":"","text":"感情的にね","start":1301.3,"favorite":false,"stableId":"5c5cddce-2d3c-465d-a22b-46c4f0cdfe2b","sequenceId":432},{"id":433,"end":1306.26,"note":"","text":"ＵＤＩラボの代表として必ず無罪を勝ち取ります","start":1302.67,"favorite":false,"stableId":"ec6c1979-b2b9-4b82-9f98-52c5da689c8c","sequenceId":433},{"id":434,"end":1307.44,"note":"","text":"よろしく","start":1306.31,"favorite":false,"stableId":"a92462e3-6d02-4fc7-8af9-b9ddb20391ab","sequenceId":434},{"id":435,"end":1309.52,"note":"","text":"-よっ！-おお～","start":1307.71,"favorite":false,"stableId":"55446dbf-efd2-41fc-aeb7-a4d77dbcee83","sequenceId":435},{"id":436,"end":1312.68,"note":"","text":"速度135 深さ18です","start":1309.57,"favorite":false,"stableId":"007b14e2-bb96-4ae6-ba16-af966bd206cb","sequenceId":436},{"id":437,"end":1316.83,"note":"","text":"これ 見せないほうがいいよね？","start":1314.51,"favorite":false,"stableId":"994fbe4d-9add-4a6e-a119-278a7e3a057e","sequenceId":437},{"id":438,"end":1319.23,"note":"","text":"はい 見せちゃダメです","start":1316.88,"favorite":false,"stableId":"1adb40d8-6804-466d-af87-b0330bc69495","sequenceId":438},{"id":439,"end":1322.79,"note":"","text":"参ったななんで こんな書き方するかな？","start":1319.28,"favorite":false,"stableId":"7a948258-f708-42e1-a178-5689fd3ac233","sequenceId":439},{"id":440,"end":1326.91,"note":"","text":"“なんで”って何が？","start":1325.22,"favorite":false,"stableId":"bc2033e1-bcc7-4833-8aa5-1340b3c432ec","sequenceId":440},{"id":441,"end":1328.44,"note":"","text":"記事の内容","start":1326.96,"favorite":false,"stableId":"b2423bd6-d00b-4174-828f-01b067d6d674","sequenceId":441},{"id":442,"end":1330.81,"note":"","text":"むちゃくちゃ言ってんの烏田検事なのに","start":1328.49,"favorite":false,"stableId":"b2aa64ca-2a74-4684-87e6-bee66357f9d7","sequenceId":442},{"id":443,"end":1332.38,"note":"","text":"話 違うじゃないですか","start":1330.86,"favorite":false,"stableId":"3bd007cf-596e-4d45-a2b0-195da63394c5","sequenceId":443},{"id":444,"end":1334.38,"note":"","text":"“違う”ってことはないだろう","start":1332.43,"favorite":false,"stableId":"21a4e358-7d2f-4adb-ae18-2ac98069f27a","sequenceId":444},{"id":445,"end":1337.29,"note":"","text":"これを書いた記者の目にはそう映ったってことなんだよ","start":1334.43,"favorite":false,"stableId":"e4cd4f92-a796-48c3-8855-1b658ab8b12c","sequenceId":445},{"id":446,"end":1338.65,"note":"","text":"それにしたって…","start":1337.34,"favorite":false,"stableId":"0d4f43c4-a5cf-4b0a-aa4b-193af049ea03","sequenceId":446},{"id":447,"end":1339.82,"note":"","text":"いいじゃない","start":1338.7,"favorite":false,"stableId":"3df8584e-0ce5-45e0-bad6-e5f103381bc7","sequenceId":447},{"id":448,"end":1342.52,"note":"","text":"別の真実があるならあるで","start":1339.87,"favorite":false,"stableId":"38a16dcf-fc33-4fa9-a90d-8af35a878fb8","sequenceId":448},{"id":449,"end":1346.54,"note":"","text":"それは いずれ久部ちゃんが 自分で書けば？","start":1342.57,"favorite":false,"stableId":"50d35908-db6d-4e75-8287-d7288da0ee65","sequenceId":449},{"id":450,"end":1352.57,"note":"","text":"おっ…","start":1351.12,"favorite":false,"stableId":"3b511588-b8fb-4d90-98e9-446d02e99d7b","sequenceId":450},{"id":451,"end":1353.85,"note":"","text":"どれ？","start":1352.62,"favorite":false,"stableId":"4b55322b-4e65-4351-98e3-4de2060cce7c","sequenceId":451},{"id":452,"end":1357.17,"note":"","text":"えっ…い… いつから いました？","start":1354.32,"favorite":false,"stableId":"cbe79b75-1050-4b78-ba6d-57b072666f3c","sequenceId":452},{"id":453,"end":1359.14,"note":"","text":"電話 聞いてましたか？","start":1357.22,"favorite":false,"stableId":"79eb14e6-2153-4e44-b349-569a0f02b9ba","sequenceId":453},{"id":454,"end":1361.04,"note":"","text":"久部君？","start":1359.19,"favorite":false,"stableId":"20600242-5958-4f76-8098-52177fcf11f8","sequenceId":454},{"id":455,"end":1363.8,"note":"","text":"仕事ほっぽって 何してるの？","start":1361.09,"favorite":false,"stableId":"b40356b2-7eff-4888-9a68-fb04bcaf436c","sequenceId":455},{"id":456,"end":1365.13,"note":"","text":"すいません","start":1363.9,"favorite":false,"stableId":"c132072a-a346-4242-88b6-bc6ff6e8329b","sequenceId":456},{"id":457,"end":1369.42,"note":"","text":"え～と…","start":1367.8,"favorite":false,"stableId":"f98ad570-22a2-410b-a836-0dbbbfc4c413","sequenceId":457},{"id":458,"end":1370.32,"note":"","text":"ちょっ…","start":1369.47,"favorite":false,"stableId":"6c894d9b-9e44-4175-823a-14d6d49fb701","sequenceId":458},{"id":459,"end":1373.67,"note":"","text":"事実は明々白々じゃなかったのか？","start":1370.37,"favorite":false,"stableId":"50416088-d8e0-467b-a020-f5217bcce6c4","sequenceId":459},{"id":460,"end":1379.51,"note":"","text":"“ヒステリー女法医学者”格好の餌だな","start":1375.24,"favorite":false,"stableId":"5db8117f-aad0-4324-894b-fe453e7c6061","sequenceId":460},{"id":461,"end":1381.61,"note":"","text":"見して","start":1379.95,"favorite":false,"stableId":"25136caa-6dec-4fab-a1c5-9f0fceb7b795","sequenceId":461},{"id":462,"end":1384,"note":"","text":"そちらの訴訟はどうなんです？","start":1381.81,"favorite":false,"stableId":"613399b8-d05f-4c35-aa0b-a46645ae4cc8","sequenceId":462},{"id":463,"end":1386.33,"note":"","text":"坂本さんの代理人と会ったんですよね？","start":1384.05,"favorite":false,"stableId":"b9f03a48-e70e-4464-864a-ec15be4a48f3","sequenceId":463},{"id":464,"end":1389.6,"note":"","text":"ああ…訳が分からなかった","start":1386.38,"favorite":false,"stableId":"bc0af2e6-bdfc-4ab8-830a-d315ddcd30e4","sequenceId":464},{"id":465,"end":1393.34,"note":"","text":"坂本さんは中堂さんの辞職を望んでいます","start":1389.65,"favorite":false,"stableId":"bcdfed3d-eb04-4178-8424-075bfd4844d8","sequenceId":465},{"id":466,"end":1396.19,"note":"","text":"-無理だな-中堂さん まず 聞いて…","start":1393.39,"favorite":false,"stableId":"73b11c43-ac57-48b5-a29e-517bebcf8a97","sequenceId":466},{"id":467,"end":1397.66,"note":"","text":"はい","start":1396.43,"favorite":false,"stableId":"544343e0-2f69-4117-9c76-fac0b8deffb3","sequenceId":467},{"id":468,"end":1400.88,"note":"","text":"和解を拒否するのであれば","start":1398.66,"favorite":false,"stableId":"95fbea6d-413f-4a3c-b45f-a7861d90b2d0","sequenceId":468},{"id":469,"end":1404.49,"note":"","text":"精神的苦痛に対する慰謝料と心からの謝罪を","start":1400.93,"favorite":false,"stableId":"0219f3ad-b8c7-4408-8af1-0c62c49ad732","sequenceId":469},{"id":470,"end":1407.19,"note":"","text":"裁判で認めていただきますのでそのおつもりで","start":1404.54,"favorite":false,"stableId":"5c2a2a0b-b8c7-41c1-856c-e7604362dcb0","sequenceId":470},{"id":471,"end":1408.26,"note":"","text":"何の謝罪だ？","start":1407.24,"favorite":false,"stableId":"2540b4e3-b2ec-45c4-af2f-cae07f0317f9","sequenceId":471},{"id":472,"end":1410.91,"note":"","text":"-はい？-何一つ 心当たりがない","start":1408.31,"favorite":false,"stableId":"350669b7-cc95-45bd-a2ef-8100452b72e3","sequenceId":472},{"id":473,"end":1414.96,"note":"","text":"パワハラで訴えられてるの分かってます？","start":1412.58,"favorite":false,"stableId":"5c5c574e-4f34-497e-bbbd-2db682c7b256","sequenceId":473},{"id":474,"end":1416.3,"note":"","text":"何をもってパワハラなんだ？","start":1415.01,"favorite":false,"stableId":"1a0df49a-ce2a-492a-9701-827afc828446","sequenceId":474},{"id":475,"end":1418.73,"note":"","text":"今まで検査技師の人たち辞めさせてますよね？","start":1416.35,"favorite":false,"stableId":"f84d372c-ce90-470a-8995-3a2b8aa37e72","sequenceId":475},{"id":476,"end":1420.27,"note":"","text":"あいつらが勝手に辞めた","start":1418.78,"favorite":false,"stableId":"f20c276e-506d-40fd-8530-e1aea0434afd","sequenceId":476},{"id":477,"end":1422.25,"note":"","text":"俺は何もしてない","start":1420.32,"favorite":false,"stableId":"7f77bc10-b321-4aea-90a1-71a21f414f60","sequenceId":477},{"id":478,"end":1430.2,"note":"","text":"中堂さん…","start":1428.36,"favorite":false,"stableId":"799c3077-4ccb-46e2-a3d4-76648cda5ddf","sequenceId":478},{"id":479,"end":1435.58,"note":"","text":"今まで 言おうか言うまいか","start":1432.13,"favorite":false,"stableId":"4cf5f869-4baa-4e88-8a77-20fa123375a3","sequenceId":479},{"id":480,"end":1439.42,"note":"","text":"ず～っと 迷ってたんですけど","start":1435.63,"favorite":false,"stableId":"da8ddfbf-a59f-4cda-87b9-bcb3c176c79d","sequenceId":480},{"id":481,"end":1441.01,"note":"","text":"うん？　何だ？","start":1439.47,"favorite":false,"stableId":"ac8b41b4-15de-4b2c-b674-944e58953ad8","sequenceId":481},{"id":482,"end":1443.24,"note":"","text":"中堂さんって…","start":1441.17,"favorite":false,"stableId":"44d402ac-7d50-4eeb-9147-8d35dbcee06c","sequenceId":482},{"id":483,"end":1447.18,"note":"","text":"相当 感じ悪いですよ","start":1445.34,"favorite":false,"stableId":"6ab6df48-60db-4b6a-822e-6530f15f2c1f","sequenceId":483},{"id":484,"end":1448.85,"note":"","text":"プッ…","start":1447.51,"favorite":false,"stableId":"fe426675-29c1-49a3-bd6d-c10f20330632","sequenceId":484},{"id":485,"end":1455.07,"note":"","text":"よ… よくはないかもです","start":1453.45,"favorite":false,"stableId":"13a1e1e0-3eae-47f1-bcd9-9b8bdf1f8c25","sequenceId":485},{"id":486,"end":1456.94,"note":"","text":"人の感じ方まで 責任 持てるか！","start":1455.12,"favorite":false,"stableId":"5b88d579-b026-4dcd-aab6-54a9010c1e47","sequenceId":486},{"id":487,"end":1459.41,"note":"","text":"いや 愛想を振りまけとは言いませんけど","start":1456.99,"favorite":false,"stableId":"02add4c5-cd88-49a0-a2ec-52e0273342ba","sequenceId":487},{"id":488,"end":1461.89,"note":"","text":"立てなくていい角を立てることはないでしょ","start":1459.46,"favorite":false,"stableId":"6dcd8d3c-8cea-40d4-b154-c19560d85fc0","sequenceId":488},{"id":489,"end":1466.46,"note":"","text":"108回と言われた","start":1462.43,"favorite":false,"stableId":"4cc25583-0944-4412-b2ad-ea2f9512389f","sequenceId":489},{"id":490,"end":1470.8,"note":"","text":"こちらは証拠として裁判所にも提出しますが","start":1466.77,"favorite":false,"stableId":"c324582a-e062-4d91-b2c0-fad20333bc4a","sequenceId":490},{"id":491,"end":1475.21,"note":"","text":"依頼人は こんなにも暴言を吐かれたと言っています","start":1471.14,"favorite":false,"stableId":"c35c5855-85ad-424e-83ef-b88cc2a33d9f","sequenceId":491},{"id":492,"end":1481.06,"note":"","text":"“クソだ”“クソだぜ” “クソだな”","start":1477.84,"favorite":false,"stableId":"fd5fe66f-a783-4f8b-b28e-efb2e4e5e1cd","sequenceId":492},{"id":493,"end":1484.77,"note":"","text":"“クソが” “クソかよ”“クソ野郎” “クソか”…","start":1481.11,"favorite":false,"stableId":"2f988022-7310-468b-acc3-f6e6bf4e9e73","sequenceId":493},{"id":494,"end":1486.67,"note":"","text":"こ… こんなに“クソ”","start":1484.82,"favorite":false,"stableId":"d52c5983-2f20-4ad3-8d34-3edc02e7a8a9","sequenceId":494},{"id":495,"end":1487.77,"note":"","text":"こんなバリエーションあるんですよ クソって","start":1486.72,"favorite":false,"stableId":"8a77a77e-d34f-42fc-a9be-d78e06f69dcf","sequenceId":495},{"id":496,"end":1488.67,"note":"","text":"あー はいはいはい","start":1487.82,"favorite":false,"stableId":"095c9aeb-75f6-4555-8dd9-46fce8d19da0","sequenceId":496},{"id":497,"end":1490.66,"note":"","text":"クソってこんなあります？","start":1488.72,"favorite":false,"stableId":"397c9d02-0122-432c-9cab-da6a9fdad959","sequenceId":497},{"id":498,"end":1492.66,"note":"","text":"うわっ","start":1490.99,"favorite":false,"stableId":"b980f3b0-2786-464b-8bea-d7e44f2fe123","sequenceId":498},{"id":499,"end":1497.85,"note":"","text":"クソだな クソすぎる","start":1495.39,"favorite":false,"stableId":"e9991ebf-d4a7-49b2-8778-7afbb0f857e8","sequenceId":499},{"id":500,"end":1500.55,"note":"","text":"クソが！　あ～ クソ！","start":1497.9,"favorite":false,"stableId":"ab26871c-e115-43e0-8003-b7a320fd5847","sequenceId":500},{"id":501,"end":1501.97,"note":"","text":"クソなのか！","start":1500.6,"favorite":false,"stableId":"ede0bda3-0e5c-4415-8b70-85665627fc07","sequenceId":501},{"id":502,"end":1504.44,"note":"","text":"やっぱり 月曜日は多いな","start":1502.2,"favorite":false,"stableId":"9aaf7085-8c0c-4a5e-95b2-72bbb857264e","sequenceId":502},{"id":503,"end":1507.57,"note":"","text":"いちいち記録してたんだ あいつは","start":1505.2,"favorite":false,"stableId":"8a8fc445-1bce-4f26-afc3-fc09fd75ba35","sequenceId":503},{"id":504,"end":1508.96,"note":"","text":"信じがたい","start":1508.01,"favorite":false,"stableId":"d059d352-81c1-4f4f-b1f5-c1e1ff92ee40","sequenceId":504},{"id":505,"end":1510.96,"note":"","text":"108回も言うほうが信じがたいです","start":1509.01,"favorite":false,"stableId":"0cb4aea6-d293-4ef2-a88d-2f4540efc03d","sequenceId":505},{"id":506,"end":1512.94,"note":"","text":"あいつに言ったわけじゃない","start":1511.01,"favorite":false,"stableId":"865f94f2-430a-42a0-867b-e869c7bc3f50","sequenceId":506},{"id":507,"end":1515.43,"note":"","text":"俺が俺の仕事中に何 言おうが勝手だろう","start":1513.35,"favorite":false,"stableId":"e50d3012-f2a3-4111-b10b-9ae4a723fd0a","sequenceId":507},{"id":508,"end":1517.57,"note":"","text":"聞こえるように言うのが問題なんですよ","start":1515.48,"favorite":false,"stableId":"fba3f598-62f5-4d31-960a-56f2ae6c7158","sequenceId":508},{"id":509,"end":1518.77,"note":"","text":"風紀委員か お前は","start":1517.62,"favorite":false,"stableId":"24b4cb9b-4763-46f4-a589-ae4124bfe5b1","sequenceId":509},{"id":510,"end":1520.5,"note":"","text":"お前って言い方もよくないと思います","start":1518.82,"favorite":false,"stableId":"c28dc494-e678-435c-9074-55241da42493","sequenceId":510},{"id":511,"end":1522.84,"note":"","text":"とりあえず 中堂さん謝っちゃったら…","start":1520.55,"favorite":false,"stableId":"ff075d9c-b2ec-4f95-bfa1-d08e99746df1","sequenceId":511},{"id":512,"end":1523.84,"note":"","text":"だから 何を謝んだ？","start":1522.89,"favorite":false,"stableId":"3d6dc8cc-5a4b-472e-bee9-4ac0edd1b77c","sequenceId":512},{"id":513,"end":1525.21,"note":"","text":"じゃあ もう 辞めるしかないですね","start":1523.89,"favorite":false,"stableId":"db94f8b0-2406-46d9-ac24-e676cba6e420","sequenceId":513},{"id":514,"end":1526.39,"note":"","text":"バカか","start":1525.26,"favorite":false,"stableId":"779a1915-2483-4978-ae30-e542ea6c62a8","sequenceId":514},{"id":515,"end":1529.24,"note":"","text":"私も これから“バカ”って言われた回数を記録します","start":1526.76,"favorite":false,"stableId":"1bc85c21-d392-4e01-a06b-1c8dfff13466","sequenceId":515},{"id":516,"end":1531.73,"note":"","text":"俺はＵＤＩを辞めない","start":1529.29,"favorite":false,"stableId":"7ecd2a41-7b7d-46bf-a4f6-e409138a9c47","sequenceId":516},{"id":517,"end":1534.6,"note":"","text":"誰に何を言われようとな","start":1532.5,"favorite":false,"stableId":"f7fb1939-e9ef-4b2d-a188-df3475ed6065","sequenceId":517},{"id":518,"end":1547.81,"note":"","text":"えっ!?　ええっ…","start":1545.31,"favorite":false,"stableId":"019fda7c-3bfe-4947-ba2b-f440a5f3e021","sequenceId":518},{"id":519,"end":1550.58,"note":"","text":"どういうことですか？","start":1548.61,"favorite":false,"stableId":"d33a3335-b41d-4bb2-995a-1dd9fb69884b","sequenceId":519},{"id":520,"end":1553.24,"note":"","text":"やっぱり 罪を認める？","start":1551.58,"favorite":false,"stableId":"c4d9b07b-5840-4ca3-b4cc-5a4a35cdce2b","sequenceId":520},{"id":521,"end":1554.97,"note":"","text":"要一さんの希望です","start":1553.29,"favorite":false,"stableId":"2e697e03-0c0' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || 'a-4c88-8301-0cd97b1fa281","sequenceId":521},{"id":522,"end":1556.34,"note":"","text":"実は 殺してたんですか？","start":1555.02,"favorite":false,"stableId":"c2087a64-8983-47d1-a408-0c911f37bec1","sequenceId":522},{"id":523,"end":1559.07,"note":"","text":"いえ そうではなくて…","start":1556.39,"favorite":false,"stableId":"982111bb-71d5-4577-8f8d-14909c94a78f","sequenceId":523},{"id":524,"end":1561.84,"note":"","text":"え… じゃあ どうして？","start":1559.12,"favorite":false,"stableId":"c2ddd589-f182-4acc-a721-529ff8427d79","sequenceId":524},{"id":525,"end":1566.93,"note":"","text":"公判を見て不安になってしまったようで","start":1561.89,"favorite":false,"stableId":"a1d7c681-46b1-4ae7-a009-cae8dbecdafd","sequenceId":525},{"id":526,"end":1569.58,"note":"","text":"だって 勝てないでしょ","start":1567.33,"favorite":false,"stableId":"43aa77b9-757f-496e-9c23-28568142d6e2","sequenceId":526},{"id":527,"end":1573.42,"note":"","text":"でも それで また罪を認めるだなんて","start":1569.63,"favorite":false,"stableId":"4826c7a6-8112-432e-90c5-b53efba80c7c","sequenceId":527},{"id":528,"end":1575.86,"note":"","text":"無罪を主張して負けたら","start":1573.47,"favorite":false,"stableId":"78eb0f5a-871c-4f43-96b2-d4afc7347b14","sequenceId":528},{"id":529,"end":1578.16,"note":"","text":"反省の色が見られないって思われて","start":1575.91,"favorite":false,"stableId":"7b08a66f-2636-46e2-837a-982fe5d39eaf","sequenceId":529},{"id":530,"end":1581.66,"note":"","text":"15年とか18年とか刑が重くなるじゃないですか","start":1578.21,"favorite":false,"stableId":"99a160df-5320-4b76-bbb3-f449ed529b17","sequenceId":530},{"id":531,"end":1585.13,"note":"","text":"だったら 罪を認めて心神耗弱で争ったほうが","start":1581.71,"favorite":false,"stableId":"54a126af-2c13-4c52-9a6a-38de54ef7ad6","sequenceId":531},{"id":532,"end":1588.57,"note":"","text":"情状酌量もつくし刑務所で真面目に過ごせば","start":1585.18,"favorite":false,"stableId":"48d842d7-7dc1-4c07-8dd7-32d48d154749","sequenceId":532},{"id":533,"end":1590.71,"note":"","text":"10年くらいで出られるじゃないですか","start":1588.62,"favorite":false,"stableId":"0fbdf841-1b9e-453a-bd77-6537c26b2975","sequenceId":533},{"id":534,"end":1595.78,"note":"","text":"三澄先生が 今 証拠となる新しい実験をしてくれてますから","start":1590.76,"favorite":false,"stableId":"c92d5ef0-e971-4c53-8280-79d45c153cf3","sequenceId":534},{"id":535,"end":1597.93,"note":"","text":"あの人だって同じです","start":1595.83,"favorite":false,"stableId":"e41993a0-11a1-4c88-a33e-2136a0236bad","sequenceId":535},{"id":536,"end":1603.35,"note":"","text":"女っていうのは都合が悪くなると人のせいにして","start":1599.46,"favorite":false,"stableId":"65653b0f-c1b9-4c85-806e-534bad6538f4","sequenceId":536},{"id":537,"end":1605.64,"note":"","text":"あげく被害者面するんです","start":1603.4,"favorite":false,"stableId":"fe36cf71-4564-4ba4-951a-50f6f57f514b","sequenceId":537},{"id":538,"end":1608.64,"note":"","text":"自分の損得でしか動かない","start":1605.87,"favorite":false,"stableId":"a55954c1-da6b-4f05-a5de-9ff6d95e17bb","sequenceId":538},{"id":539,"end":1614.65,"note":"","text":"私の人生女なんかには預けられません","start":1610.31,"favorite":false,"stableId":"f11a8518-287e-4a67-8c29-4ff098b36698","sequenceId":539},{"id":540,"end":1619.45,"note":"","text":"説得はしたんですが意志が固くて…","start":1615.75,"favorite":false,"stableId":"2181ef45-33bb-4c21-8ca4-ef13ae80ac61","sequenceId":540},{"id":541,"end":1623.35,"note":"","text":"無理言って お願いしたのに申し訳ありません","start":1619.65,"favorite":false,"stableId":"0098445c-4696-4e26-a268-e0d141dcca32","sequenceId":541},{"id":542,"end":1626.34,"note":"","text":"奥さんにしいたげられてきたせいで","start":1623.72,"favorite":false,"stableId":"ecb639fc-fda4-4881-a42f-9668b988e0bf","sequenceId":542},{"id":543,"end":1628.44,"note":"","text":"女という女が信じられないんだって","start":1626.39,"favorite":false,"stableId":"c53a7e0f-7e8f-452e-8a8c-79197a77f302","sequenceId":543},{"id":544,"end":1630.05,"note":"","text":"こじらせてんな～","start":1628.49,"favorite":false,"stableId":"0e00c887-f440-46d1-ab8a-c3d7c83c9b5b","sequenceId":544},{"id":545,"end":1633.35,"note":"","text":"代理戦争の様相を呈してきたわね","start":1630.1,"favorite":false,"stableId":"e3bd7c76-43a7-49a8-9937-9f45b66113e3","sequenceId":545},{"id":546,"end":1634.63,"note":"","text":"えっ？","start":1633.4,"favorite":false,"stableId":"390951c2-b04a-4f73-bfd2-617438c9df15","sequenceId":546},{"id":547,"end":1637.34,"note":"","text":"ネットで論争が起こってる","start":1634.93,"favorite":false,"stableId":"20664868-cf1d-4bd0-9967-6d7eea0d1234","sequenceId":547},{"id":548,"end":1639.94,"note":"","text":"男ＶＳ女","start":1637.5,"favorite":false,"stableId":"8a9886c5-f67f-4649-a296-06d0446d0d9e","sequenceId":548},{"id":549,"end":1641.62,"note":"","text":"どうしよう…","start":1640.37,"favorite":false,"stableId":"50d343dd-8fa0-4107-a1c7-80e7f9a0f10c","sequenceId":549},{"id":550,"end":1643.63,"note":"","text":"ほっとけよそんな失礼な被告人","start":1641.67,"favorite":false,"stableId":"66444ce2-0cbe-4edf-bc7b-1d85dc719940","sequenceId":550},{"id":551,"end":1647.1,"note":"","text":"いや～ でもな気が弱いってだけで","start":1643.68,"favorite":false,"stableId":"11a03bae-4ba4-4240-96a1-fce227401ea3","sequenceId":551},{"id":552,"end":1649.4,"note":"","text":"有罪なろうとしてる人ほっとくってのも","start":1647.15,"favorite":false,"stableId":"da22abc6-bbeb-4494-92a9-ee6ab242b55c","sequenceId":552},{"id":553,"end":1652.23,"note":"","text":"気が弱い人や声が小さい人が","start":1649.45,"favorite":false,"stableId":"a895d0a1-2d42-44e8-896a-88671c7ae4f4","sequenceId":553},{"id":554,"end":1655.62,"note":"","text":"損しちゃう世の中なのよね～悲しいかな","start":1652.28,"favorite":false,"stableId":"e441788a-96e5-450f-bca2-36938a1fd494","sequenceId":554},{"id":555,"end":1660.98,"note":"","text":"そういう人の味方をするのが弁護士の仕事","start":1657.36,"favorite":false,"stableId":"55649e5f-39e0-4c75-88a9-c7cb972d298c","sequenceId":555},{"id":556,"end":1663.71,"note":"","text":"もう お母さん 弁護してよ～","start":1661.03,"favorite":false,"stableId":"7f7303c4-6ec0-4da5-a6cd-67d01960ffe2","sequenceId":556},{"id":557,"end":1666.93,"note":"","text":"ミコトにはミコトの仕事がある","start":1663.76,"favorite":false,"stableId":"8d0ded7c-c69d-473d-acdf-2cea8e93ea0c","sequenceId":557},{"id":558,"end":1669.87,"note":"","text":"法医学","start":1668.53,"favorite":false,"stableId":"3b5c0533-0403-4053-a78f-62d65fb308e3","sequenceId":558},{"id":559,"end":1673.02,"note":"","text":"そりゃ まあ 法医学者だけど","start":1670.74,"favorite":false,"stableId":"4265e80f-1acd-41c9-8bb3-5cf092a9a72e","sequenceId":559},{"id":560,"end":1675.26,"note":"","text":"これ 何？　豚肉？","start":1673.07,"favorite":false,"stableId":"d2d2beeb-f1b7-4f03-80a3-7339f4eb41da","sequenceId":560},{"id":561,"end":1676.81,"note":"","text":"ああ…","start":1675.31,"favorite":false,"stableId":"7a6b4e36-9ac3-412e-8a8a-0e5c2cf6588f","sequenceId":561},{"id":562,"end":1679.43,"note":"","text":"非力で体重の軽い夫が","start":1677.14,"favorite":false,"stableId":"ea9e9418-eeca-4604-8bd1-68ae7511a2be","sequenceId":562},{"id":563,"end":1682.96,"note":"","text":"背骨に これほどの傷を残すくらい強く刺すためには","start":1679.48,"favorite":false,"stableId":"9a6179ca-f35d-409e-84eb-145baa8fb00a","sequenceId":563},{"id":564,"end":1685.1,"note":"","text":"どのくらいの助走が必要なのか","start":1683.01,"favorite":false,"stableId":"e44c46e8-5a7a-4abf-96d9-0e9b71d24ea8","sequenceId":564},{"id":565,"end":1687.2,"note":"","text":"現場のリビングでは難しいという推論","start":1685.15,"favorite":false,"stableId":"aef119d9-0a21-4b69-8c86-ec83abacee11","sequenceId":565},{"id":566,"end":1690.96,"note":"","text":"ぬるい！あきれるほど ぬるい！","start":1687.25,"favorite":false,"stableId":"69bbfb53-27e1-4d4d-b9f2-f7ebfb73e078","sequenceId":566},{"id":567,"end":1696.06,"note":"","text":"その程度じゃ烏田検事に負けちゃうわね～","start":1691.72,"favorite":false,"stableId":"8b7d739a-0e19-48b2-903d-7fd450996cad","sequenceId":567},{"id":568,"end":1701.18,"note":"","text":"しずく事件の試料？","start":1699.33,"favorite":false,"stableId":"546f2128-28de-4893-9f42-b59ae495b544","sequenceId":568},{"id":569,"end":1702.92,"note":"","text":"調べ直す","start":1701.23,"favorite":false,"stableId":"2133f4e0-ec97-449e-b39a-084bcb2a635c","sequenceId":569},{"id":570,"end":1704.29,"note":"","text":"もう いいって言われたんじゃないの？","start":1702.97,"favorite":false,"stableId":"50184eed-c41d-40a0-ba3a-c826f5ba7ed2","sequenceId":570},{"id":571,"end":1709.26,"note":"","text":"桜小路さんは 明日の被告人質問で罪を認める答弁をするつもりでいる","start":1704.34,"favorite":false,"stableId":"2d7fb49a-a23d-44f9-b1b5-6980f1578959","sequenceId":571},{"id":572,"end":1712.59,"note":"","text":"そうなったら 凶器のことはうやむやのまま有罪確定","start":1709.31,"favorite":false,"stableId":"5b64f781-ecd7-46ff-9dcd-40c195890231","sequenceId":572},{"id":573,"end":1713.9,"note":"","text":"だから そうなる前に","start":1712.64,"favorite":false,"stableId":"718a33ff-67a6-4c29-b778-da314c3d3e31","sequenceId":573},{"id":574,"end":1716.46,"note":"","text":"検察に ぎゃふんと言わせる証拠を見つけて","start":1713.95,"favorite":false,"stableId":"889bdbfd-c0c1-46b3-9ed7-81b4a22bc50e","sequenceId":574},{"id":575,"end":1718.3,"note":"","text":"桜小路さんを説得する","start":1716.51,"favorite":false,"stableId":"4fefe18e-f56e-4f3f-80ca-45f1a7452b9b","sequenceId":575},{"id":576,"end":1721.19,"note":"","text":"カラスに ぎゃふん！言わせたい","start":1718.35,"favorite":false,"stableId":"b192a9cb-d063-4fb7-8410-6ab17025ff6f","sequenceId":576},{"id":577,"end":1723.76,"note":"","text":"まずは これ","start":1721.59,"favorite":false,"stableId":"284a77dc-e057-48db-b861-8d7c4076ab8a","sequenceId":577},{"id":578,"end":1726.78,"note":"","text":"分かる？","start":1725.42,"favorite":false,"stableId":"d4ac1ea7-3610-4405-9416-f2640d3c1ece","sequenceId":578},{"id":579,"end":1730.29,"note":"","text":"微妙すぎて分かんないな～","start":1726.83,"favorite":false,"stableId":"e1b7cea4-445a-443a-8daa-59718a550bed","sequenceId":579},{"id":580,"end":1735.22,"note":"","text":"大体さ左利き用か 右利き用かなんて","start":1731.43,"favorite":false,"stableId":"aae42c62-4b3a-4fdf-affa-904c090184dc","sequenceId":580},{"id":581,"end":1738.42,"note":"","text":"３ＤＣＧで初めて分かったことじゃん","start":1735.27,"favorite":false,"stableId":"bef4c569-e2ee-408b-a57a-36c7e610d1e9","sequenceId":581},{"id":582,"end":1740.91,"note":"","text":"他に証明しようがなくない？","start":1738.47,"favorite":false,"stableId":"7c65134e-8426-4c40-962d-e6824c7f1e2e","sequenceId":582},{"id":583,"end":1745.16,"note":"","text":"右か左か… 以外の証拠？","start":1741.07,"favorite":false,"stableId":"d03976de-42c9-4e23-801d-343111882008","sequenceId":583},{"id":584,"end":1747.41,"note":"","text":"被害者の血液","start":1745.21,"favorite":false,"stableId":"365123f9-0f2d-4097-8fab-02f873bebc11","sequenceId":584},{"id":585,"end":1752.4,"note":"","text":"解剖中に血液を採取する時心臓から出た血液をすくうよね","start":1747.58,"favorite":false,"stableId":"bf3c9f79-958d-4f3b-9ce4-ccc5baa865ae","sequenceId":585},{"id":586,"end":1755.94,"note":"","text":"つまり これは刺し傷の ごく近くの血液で","start":1752.45,"favorite":false,"stableId":"b70bcd91-b3cf-4353-9300-56dc68d72547","sequenceId":586},{"id":587,"end":1757.61,"note":"","text":"背骨からも近い","start":1755.99,"favorite":false,"stableId":"1ff0f3fd-b9bf-45a6-ac4b-2777a9db49e9","sequenceId":587},{"id":588,"end":1760.51,"note":"","text":"背骨にガツンと当たった包丁が…","start":1757.66,"favorite":false,"stableId":"06702557-24c8-4edc-9b0d-043b4735e630","sequenceId":588},{"id":589,"end":1762.88,"note":"","text":"わずかでも刃こぼれしてたら","start":1760.56,"favorite":false,"stableId":"7b5cb21f-ddc9-4e13-bffd-683465619315","sequenceId":589},{"id":590,"end":1764.48,"note":"","text":"真の凶器の成分が検出できる","start":1762.93,"favorite":false,"stableId":"7ba791af-4dd2-4fdf-b00b-c02278991677","sequenceId":590},{"id":591,"end":1765.66,"note":"","text":"イエス！","start":1764.53,"favorite":false,"stableId":"90645ca7-1e88-402e-9514-c2904f7a6a7e","sequenceId":591},{"id":592,"end":1773.07,"note":"","text":"-ハッ…-坂本さん","start":1770.67,"favorite":false,"stableId":"bc02508a-d31c-4b6a-a2e9-a50859f8709e","sequenceId":592},{"id":593,"end":1777.73,"note":"","text":"えっ？　ちょ… 坂本さん","start":1774.94,"favorite":false,"stableId":"72c05aa4-c43a-431e-88d6-c613499732de","sequenceId":593},{"id":594,"end":1780.16,"note":"","text":"坂本さん 坂本さん！","start":1777.78,"favorite":false,"stableId":"c197b591-8566-45e0-acb6-90a622cd658f","sequenceId":594},{"id":595,"end":1781.93,"note":"","text":"あっ 落ちてます 落ちてますよ！","start":1780.21,"favorite":false,"stableId":"ddc8e028-53ca-45a6-819c-c35674ad7e27","sequenceId":595},{"id":596,"end":1784.32,"note":"","text":"お気に入りのムーミンのツボ押し","start":1781.98,"favorite":false,"stableId":"22a61ad8-3c41-4097-95cd-5723731d33ee","sequenceId":596},{"id":597,"end":1786.32,"note":"","text":"えっ？","start":1784.95,"favorite":false,"stableId":"9244b90c-d413-4544-b592-ef0bee251531","sequenceId":597},{"id":598,"end":1790.74,"note":"","text":"うん？","start":1789.35,"favorite":false,"stableId":"a0794919-2b75-41ce-a5f0-45ee752c4aec","sequenceId":598},{"id":599,"end":1792.62,"note":"","text":"何か出た？","start":1790.79,"favorite":false,"stableId":"8aa10309-455c-43c2-8366-176d24c7bf5a","sequenceId":599},{"id":600,"end":1794.04,"note":"","text":"疑問が出た","start":1792.89,"favorite":false,"stableId":"b7c9833f-15a7-4e4e-89b9-2d92a21c1355","sequenceId":600},{"id":601,"end":1795.33,"note":"","text":"疑問？","start":1794.09,"favorite":false,"stableId":"6eb266dc-b6b8-498c-8d82-230324b13e52","sequenceId":601},{"id":602,"end":1798.28,"note":"","text":"真の凶器って何？","start":1795.73,"favorite":false,"stableId":"51e15873-a98f-43f5-afc8-834a905e0777","sequenceId":602},{"id":603,"end":1800.01,"note":"","text":"まだ見つかってない別の包丁","start":1798.33,"favorite":false,"stableId":"06035ef2-f1f6-44f7-ab1d-705e2e193aaa","sequenceId":603},{"id":604,"end":1801.48,"note":"","text":"その包丁の材質","start":1800.06,"favorite":false,"stableId":"b10fc749-ff52-46ac-a761-22d77ebf2b19","sequenceId":604},{"id":605,"end":1804.49,"note":"","text":"検察の主張する凶器はセラミックでしょ？","start":1801.53,"favorite":false,"stableId":"c70907a1-5ec2-4bcd-ae12-fe20dc06610c","sequenceId":605},{"id":606,"end":1806.96,"note":"","text":"セラミックじゃない包丁って…","start":1804.54,"favorite":false,"stableId":"0eca6477-0e04-41a6-8157-d7b26ce5c6de","sequenceId":606},{"id":607,"end":1808.52,"note":"","text":"鉄かステンレス","start":1807.01,"favorite":false,"stableId":"f5495152-4a76-4415-a5e6-3c427dc49214","sequenceId":607},{"id":608,"end":1809.79,"note":"","text":"ああ…","start":1808.57,"favorite":false,"stableId":"4514d082-b6f0-432a-bb4f-adf87e254408","sequenceId":608},{"id":609,"end":1813.29,"note":"","text":"だとすると 血液じゃ検出できるかどうか怪しい","start":1809.84,"favorite":false,"stableId":"182ed203-f756-4ad3-ae42-fcf77a1f74e2","sequenceId":609},{"id":610,"end":1814.3,"note":"","text":"うん？","start":1813.34,"favorite":false,"stableId":"bb058101-3b44-4d41-a695-53f4363d2224","sequenceId":610},{"id":611,"end":1816.73,"note":"","text":"鉄もステンレスも主成分は鉄でしょ？","start":1814.35,"favorite":false,"stableId":"938f16a4-1509-4e3d-b709-9f01ea5052c4","sequenceId":611},{"id":612,"end":1821.14,"note":"","text":"血液中に含まれる鉄分と混じって判別できない","start":1816.78,"favorite":false,"stableId":"b28eb702-463a-4b05-9184-24bd00371e3b","sequenceId":612},{"id":613,"end":1822.9,"note":"","text":"セラミックが出たところで","start":1821.19,"favorite":false,"stableId":"4a91d2f8-3a95-4d5f-9d8e-f769e6c11c0b","sequenceId":613},{"id":614,"end":1826.69,"note":"","text":"検察の凶器の否定にはならないしね～","start":1822.95,"favorite":false,"stableId":"5317cdac-ca14-466f-bb1c-88602a8fd5d1","sequenceId":614},{"id":615,"end":1830.7,"note":"","text":"じゃあ あれは？","start":1828.89,"favorite":false,"stableId":"cffe5a8c-db25-474a-a3a2-2261a3a15cf3","sequenceId":615},{"id":616,"end":1832.55,"note":"","text":"さっき調べたじゃん","start":1831.06,"favorite":false,"stableId":"2cf898da-f8cb-4f95-a27a-4e148711cd04","sequenceId":616},{"id":617,"end":1836.6,"note":"","text":"いや 皮膚じゃなくて液体 ホルマリン液","start":1832.6,"favorite":false,"stableId":"4404846a-a395-42e4-af3f-2b04efe4910a","sequenceId":617},{"id":618,"end":1841.29,"note":"","text":"傷口に付着した凶器の成分がこの中に拡散してたら…","start":1837.4,"favorite":false,"stableId":"2b793927-831f-4539-afde-7a91cc98042c","sequenceId":618},{"id":619,"end":1843.96,"note":"","text":"凶器の主成分が鉄だったとしても…","start":1841.34,"favorite":false,"stableId":"96e81b8a-da1b-4e8d-8c0c-ffca4800cdc7","sequenceId":619},{"id":620,"end":1846.24,"note":"","text":"血液と違って分離できる","start":1844.01,"favorite":false,"stableId":"51efe7a1-c4f0-4080-b554-17b53fbd28a0","sequenceId":620},{"id":621,"end":1849.48,"note":"","text":"よし！","start":1847.98,"favorite":false,"stableId":"3ce9be79-5a1c-45fe-8e9c-9c80030b456a","sequenceId":621},{"id":622,"end":1853.33,"note":"","text":"中堂さん辞める気ないみたいですよ","start":1851.02,"favorite":false,"stableId":"97be4556-c58b-4e52-8e16-fa5c783ac5f8","sequenceId":622},{"id":623,"end":1855.04,"note":"","text":"だろうね","start":1853.38,"favorite":false,"stableId":"f08d250c-f637-43ff-9b2b-33852af2cc06","sequenceId":623},{"id":624,"end":1858.47,"note":"","text":"ＵＤＩとしても 法医解剖医を辞めさせるわけにはいかない","start":1855.09,"favorite":false,"stableId":"98b55201-6670-4695-967f-ca72d2767baf","sequenceId":624},{"id":625,"end":1862.41,"note":"","text":"とどのつまり 替わりの利く僕のほうが辞めるしかない ねっ","start":1858.52,"favorite":false,"stableId":"b220f4ba-f32b-4b05-b60b-5b2ac7f875f5","sequenceId":625},{"id":626,"end":1864.85,"note":"","text":"分かってて なんで？","start":1862.46,"favorite":false,"stableId":"6157e059-bb24-4925-b236-7530425233c7","sequenceId":626},{"id":627,"end":1866.15,"note":"","text":"慰謝料 もらうため","start":1864.9,"favorite":false,"stableId":"3f8a5c87-6006-49e8-a564-d368be5ca0ef","sequenceId":627},{"id":628,"end":1867.78,"note":"","text":"お金目当てだったんですか？","start":1866.2,"favorite":false,"stableId":"8b9ab35e-ebd9-430f-a761-0863a962b8dc","sequenceId":628},{"id":629,"end":1869.93,"note":"","text":"そうだよ 悪い？","start":1867.83,"favorite":false,"stableId":"e58b7da2-c6b5-4327-af88-8736662bdbfe","sequenceId":629},{"id":630,"end":1875.34,"note":"","text":"検査技師なんて どこも１年契約でその先の保障もない","start":1870.9,"favorite":false,"stableId":"ff722e1e-e3b0-4999-9feb-87b8ba1e2ea6","sequenceId":630},{"id":631,"end":1877.79,"note":"","text":"この年じゃ採用が見つかるかも分からない","start":1875.61,"favorite":false,"stableId":"fb89cee3-f25a-4925-b7ae-22cde50d6bf0","sequenceId":631},{"id":632,"end":1880.08,"note":"","text":"お金ぐらいもらったっていいでしょ","start":1877.84,"favorite":false,"stableId":"77c6affa-cd46-4955-a039-2e366ced1df8","sequenceId":632},{"id":633,"end":1885.47,"note":"","text":"久部君は いい人だけどそっち側の人間だよね","start":1881.11,"favorite":false,"stableId":"05a972bf-add1-4884-873a-e612211bb7a8","sequenceId":633},{"id":634,"end":1886.37,"note":"","text":"そっち？","start":1885.52,"favorite":false,"stableId":"cf586c4b-8a2f-4fba-ab6c-b8e97c85abaa","sequenceId":634},{"id":635,"end":1888.77,"note":"","text":"何年か浪人したって言ってたけど","start":1886.42,"favorite":false,"stableId":"1160966b-2200-4937-ad08-9ae9f01c9da9","sequenceId":635},{"id":636,"end":1893.46,"note":"","text":"浪人してまで医学部 入れるなんてお金持ちだけだよ","start":1888.82,"favorite":false,"stableId":"54cd55a1-c27e-4871-927a-6bb2185eff55","sequenceId":636},{"id":637,"end":1896.23,"note":"","text":"育ちもよさそうだし","start":1893.86,"favorite":false,"stableId":"ad711dd3-b0ea-4698-b060-dfc3d9dc1d83","sequenceId":637},{"id":638,"end":1899,"note":"","text":"開業医の息子さんだよね？","start":1896.56,"favorite":false,"stableId":"db657582-307a-4a7a-87d8-6bfef7e1fdd4","sequenceId":638},{"id":639,"end":1902.65,"note":"","text":"いずれ 医者になって将来は安泰","start":1899.9,"favorite":false,"stableId":"c135dc58-cf44-41c8-869a-bebdb16b8c05","sequenceId":639},{"id":640,"end":1904.52,"note":"","text":"未来がある人から見れば","start":1902.7,"favorite":false,"stableId":"55cf7e91-40a1-4f0a-bfc7-04aa13713259","sequenceId":640},{"id":641,"end":1907.97,"note":"","text":"僕のやってることなんてあさましいんだろうね","start":1904.57,"favorite":false,"stableId":"7883d41e-be29-4e36-9d14-1c8f1a5898e1","sequenceId":641},{"id":642,"end":1912.01,"note":"","text":"出た！","start":1910.61,"favorite":false,"stableId":"7176f569-1713-44fa-9592-6f94b70399e6","sequenceId":642},{"id":643,"end":1915.16,"note":"","text":"鉄 クロム ニッケル","start":1913.68,"favorite":false,"stableId":"c8d81c0f-dd8e-4832-ad0a-e2ece68d4f08","sequenceId":643},{"id":644,"end":1916.06,"note":"","text":"ステンレスの成分","start":1915.21,"favorite":false,"stableId":"d8134419-a93d-45ee-ac1d-105a1baad1ea","sequenceId":644},{"id":645,"end":1917.9,"note":"","text":"ぎゃふん いただきました～！","start":1916.11,"favorite":false,"stableId":"8e65a0e6-fc70-4a35-a20d-8f40b6f7e09a","sequenceId":645},{"id":646,"end":1919.03,"note":"","text":"-ちょっと待って-何？","start":1917.95,"favorite":false,"stableId":"ec9b6f32-1c92-40e4-8ca6-eabc4f86407b","sequenceId":646},{"id":647,"end":1921.05,"note":"","text":"“Ｓｉ”って これ ケイ素でしょ？","start":1919.08,"favorite":false,"stableId":"db44f0ee-ff1e-4a03-a37f-9730b2935a03","sequenceId":647},{"id":648,"end":1924.31,"note":"","text":"包丁の成分にしては数値が異常に高くない？","start":1921.55,"favorite":false,"stableId":"aebbf049-a993-4ca1-b4ff-2991dd1dca00","sequenceId":648},{"id":649,"end":1925.71,"note":"","text":"すこぶる高いね","start":1924.36,"favorite":false,"stableId":"7791aad1-e7ee-4faa-bc46-b1bc0cca80ba","sequenceId":649},{"id":650,"end":1927.38,"note":"","text":"-なんで？-分かんない","start":1925.76,"favorite":false,"stableId":"4da815fd-17d8-4fc4-b529-d25cf8d40e2b","sequenceId":650},{"id":651,"end":1929.71,"note":"","text":"分かんないままじゃ これ証拠として まずいよね","start":1927.43,"favorite":false,"stableId":"884dad09-90af-4582-8f33-757e8833946b","sequenceId":651},{' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || '"id":652,"end":1931.28,"note":"","text":"-ぎゃふん お預け？-お預け","start":1929.76,"favorite":false,"stableId":"748929c3-1cfe-4e41-a122-c0897b7c9936","sequenceId":652},{"id":653,"end":1932.25,"note":"","text":"理由 調べないと","start":1931.33,"favorite":false,"stableId":"8da2a795-9847-4d44-8c91-fd33047d2a05","sequenceId":653},{"id":654,"end":1936.52,"note":"","text":"え～と え～と元素分析ができる企業…","start":1932.3,"favorite":false,"stableId":"81818abd-591d-4692-be94-b6e71c36d220","sequenceId":654},{"id":655,"end":1937.87,"note":"","text":"ミクロリサーチ社！","start":1936.57,"favorite":false,"stableId":"06d22a67-e12e-44ad-9bfa-97984598e33d","sequenceId":655},{"id":656,"end":1942.01,"note":"","text":"え～っ 帰ってるし！","start":1939.44,"favorite":false,"stableId":"4c59debf-d580-4cfb-8d9e-4ae68837640c","sequenceId":656},{"id":657,"end":1943.22,"note":"","text":"あっ！","start":1942.27,"favorite":false,"stableId":"1c9add81-4c4f-46c7-b40c-a36ebf9de593","sequenceId":657},{"id":658,"end":1944.73,"note":"","text":"-何？-拘置所の面会時間⸺","start":1943.27,"favorite":false,"stableId":"ec4120da-1c8e-4d7d-b557-0f0a3d4e50b7","sequenceId":658},{"id":659,"end":1945.83,"note":"","text":"とっくに過ぎてる","start":1944.78,"favorite":false,"stableId":"3bfca16e-6eec-426c-881c-0b7834c6d67f","sequenceId":659},{"id":660,"end":1947.46,"note":"","text":"桜小路さんの説得ができない","start":1945.88,"favorite":false,"stableId":"f11dcabe-d7bc-4170-827e-5b16da8f1c68","sequenceId":660},{"id":661,"end":1950.78,"note":"","text":"-どうすんの？-いや とにかく元素分析","start":1947.51,"favorite":false,"stableId":"a693d5fe-26e3-42af-9bff-0722ac6f6d82","sequenceId":661},{"id":662,"end":1955.14,"note":"","text":"じゃ 私 ミクロリサーチ社の本社に電話してみるね　ねっ？","start":1950.95,"favorite":false,"stableId":"fbb56023-f631-4d52-9dc1-265209b88f81","sequenceId":662},{"id":663,"end":1958.36,"note":"","text":"あっ どうしよう…あっ どうするか…","start":1955.19,"favorite":false,"stableId":"e4593e98-5ca8-422f-815e-dfda0a73db7e","sequenceId":663},{"id":664,"end":1961.73,"note":"","text":"三澄さん","start":1960.23,"favorite":false,"stableId":"958630da-f5e6-42a2-a896-2c840ab60301","sequenceId":664},{"id":665,"end":1964.96,"note":"","text":"さっき 坂本さんが来てました","start":1962.56,"favorite":false,"stableId":"3be8b9f0-1d20-49b7-9048-27f352afd629","sequenceId":665},{"id":666,"end":1966.71,"note":"","text":"坂本さん？","start":1965.2,"favorite":false,"stableId":"fa70dd7e-6b98-4525-84bf-8580b0fea9a9","sequenceId":666},{"id":667,"end":1969.82,"note":"","text":"だから 金目当てといえばそうなんですけど","start":1966.76,"favorite":false,"stableId":"8b2c9ed7-777b-4f4d-9c48-032cf512d1bc","sequenceId":667},{"id":668,"end":1972.49,"note":"","text":"先行きの見えない不安というかそういうの ひっくるめての訴えで","start":1969.87,"favorite":false,"stableId":"b7d22962-bc91-4ae7-9d33-12c9b43adc04","sequenceId":668},{"id":669,"end":1974.19,"note":"","text":"あいつの不安なんか知るか","start":1972.54,"favorite":false,"stableId":"9604bedc-1878-4bfa-be9e-d5de034170f4","sequenceId":669},{"id":670,"end":1976.66,"note":"","text":"中堂さんが坂本さんとうまくやってさえすれば","start":1974.24,"favorite":false,"stableId":"e16d390a-3453-42af-bda3-6b028f784449","sequenceId":670},{"id":671,"end":1979.56,"note":"","text":"坂本さんだって こんなことする必要なかったんですよ","start":1976.71,"favorite":false,"stableId":"29537f9f-804d-4682-a56d-66c2c151402a","sequenceId":671},{"id":672,"end":1981.2,"note":"","text":"うまくやるってのは何だ？","start":1979.61,"favorite":false,"stableId":"df6ee31f-4231-43f0-9e56-8754a4c98b0d","sequenceId":672},{"id":673,"end":1984.57,"note":"","text":"ありがとうだの すばらしいだの褒めそやして仕事しろってのか？","start":1981.25,"favorite":false,"stableId":"f845ef09-e6ab-4ca8-ad74-a961b678e0bd","sequenceId":673},{"id":674,"end":1985.77,"note":"","text":"コミュニケーションです","start":1984.62,"favorite":false,"stableId":"0b2f17ce-8d7e-4214-859f-8d67d45a19ff","sequenceId":674},{"id":675,"end":1987.3,"note":"","text":"したくもない","start":1985.82,"favorite":false,"stableId":"bb8e582b-eeb9-42fc-a850-d70f4312f91d","sequenceId":675},{"id":676,"end":1989.57,"note":"","text":"自分の仕事のモチベーションぐらい自分で保て","start":1987.35,"favorite":false,"stableId":"cfc50d4d-8543-4d02-96a3-734990ad0218","sequenceId":676},{"id":677,"end":1990.77,"note":"","text":"話にならない","start":1989.62,"favorite":false,"stableId":"a9ddd90c-b968-4eb7-9150-a64abb058366","sequenceId":677},{"id":678,"end":1992.67,"note":"","text":"話をしなきゃ解決しませんよ","start":1990.82,"favorite":false,"stableId":"aa8c2661-dd6c-4496-bf87-720c10079642","sequenceId":678},{"id":679,"end":1995.11,"note":"","text":"“本人と話 させろ”と言ったら拒否された","start":1992.72,"favorite":false,"stableId":"34f4739d-ea88-454e-8e1c-5b8742699b15","sequenceId":679},{"id":680,"end":1997.29,"note":"","text":"どうしろってんだよ","start":1995.16,"favorite":false,"stableId":"804fe37b-afff-4a20-993f-b2ba4cf50aed","sequenceId":680},{"id":681,"end":2005.94,"note":"","text":"中堂さん私たち 協力しませんか？","start":2002.57,"favorite":false,"stableId":"3ad5a15b-dedd-4989-9c22-f8b88f0c0ac2","sequenceId":681},{"id":682,"end":2010.31,"note":"","text":"窮地に立たされた今こそ 協力","start":2007.11,"favorite":false,"stableId":"1532d348-1ff0-45c0-82ff-264a6ebd9c49","sequenceId":682},{"id":683,"end":2018.2,"note":"","text":"はい 亀岡です","start":2017.22,"favorite":false,"stableId":"2991912d-177c-400d-89e1-b6a8e22ced20","sequenceId":683},{"id":684,"end":2020.7,"note":"","text":"あっ ＵＤＩの三澄ですやっと つながった","start":2018.25,"favorite":false,"stableId":"9e90ce44-24a2-44a2-8c86-926407b01197","sequenceId":684},{"id":685,"end":2022.9,"note":"","text":"あの… 相談というか提案なんですが","start":2020.75,"favorite":false,"stableId":"3308209c-3533-4adf-bc80-0755b048c040","sequenceId":685},{"id":686,"end":2024.94,"note":"","text":"所長から上の人に連絡してください","start":2022.95,"favorite":false,"stableId":"787d2864-dd6a-4f2e-b359-621e3fa840a0","sequenceId":686},{"id":687,"end":2026.01,"note":"","text":"どういうこと？","start":2024.99,"favorite":false,"stableId":"22d757d9-60b5-45db-bb43-d332e282d43a","sequenceId":687},{"id":688,"end":2028.14,"note":"","text":"久部君がミクロリサーチ社の本社に","start":2026.06,"favorite":false,"stableId":"3ec63d8c-6080-486c-84b9-8d899ccd61f6","sequenceId":688},{"id":689,"end":2029.81,"note":"","text":"ホルマリン液を届けに行きました","start":2028.19,"favorite":false,"stableId":"bf618a15-3460-4200-9ce8-8e4019a507bd","sequenceId":689},{"id":690,"end":2033.76,"note":"","text":"何としても 明日の公判までに元素分析をしてもらいたいんです","start":2029.86,"favorite":false,"stableId":"5dab48d2-951f-49fc-8d15-f6420533a302","sequenceId":690},{"id":691,"end":2036.42,"note":"","text":"私が電話しても らちが明かなくて","start":2033.97,"favorite":false,"stableId":"9dce91d7-66b8-4b00-bb7b-c92bba9a82ec","sequenceId":691},{"id":692,"end":2037.65,"note":"","text":"私で何とかなるかな？","start":2036.47,"favorite":false,"stableId":"23a34dfb-3c03-4ca2-ae39-7dc3885ca2f6","sequenceId":692},{"id":693,"end":2040.22,"note":"","text":"何のための元厚労省ですか","start":2037.7,"favorite":false,"stableId":"98ceb9f3-f82b-4e03-ba5b-aa9d95990acf","sequenceId":693},{"id":694,"end":2043.36,"note":"","text":"天下りの力を 今 使わないでいつ使うんですか？","start":2040.27,"favorite":false,"stableId":"c1925c6c-fef6-4f3c-8c07-d2ffec1bea8b","sequenceId":694},{"id":695,"end":2044.83,"note":"","text":"私は 天下りじゃありません！","start":2043.41,"favorite":false,"stableId":"a34a2288-1811-4579-bb16-1a63514b8805","sequenceId":695},{"id":696,"end":2046.06,"note":"","text":"ごまかさなくていいですよ","start":2044.88,"favorite":false,"stableId":"262f3736-5cd2-4504-99c8-13b5cec95598","sequenceId":696},{"id":697,"end":2048.43,"note":"","text":"-違います-クソうぜえ","start":2046.11,"favorite":false,"stableId":"67c10240-43c5-48ba-b74d-8a8f19413465","sequenceId":697},{"id":698,"end":2049.86,"note":"","text":"はい この提案なら","start":2048.48,"favorite":false,"stableId":"1d23b334-55ca-4de7-8e28-0afbbf8b19cd","sequenceId":698},{"id":699,"end":2052,"note":"","text":"桜小路さんの意向にも沿えるんじゃないでしょうか","start":2049.91,"favorite":false,"stableId":"fcf1eef8-9186-4cd5-be61-50721d236b06","sequenceId":699},{"id":700,"end":2054.09,"note":"","text":"しかし…","start":2052.05,"favorite":false,"stableId":"57b647e5-f47b-4663-9388-a582563c0b35","sequenceId":700},{"id":701,"end":2057.69,"note":"","text":"このまま決着して本当にいいんですか？","start":2054.75,"favorite":false,"stableId":"47652091-e041-453e-9ace-10fbdc7ce3e8","sequenceId":701},{"id":702,"end":2072.57,"note":"","text":"-どうぞ-おお","start":2070.9,"favorite":false,"stableId":"e5811a1f-47dd-42e3-8e00-351694b4b0b4","sequenceId":702},{"id":703,"end":2077.09,"note":"","text":"盛り上がってますね～検事ＶＳヒステリー女法医学者","start":2072.84,"favorite":false,"stableId":"12ef5053-1747-4ba5-be15-1479c2fb9c0f","sequenceId":703},{"id":704,"end":2079.13,"note":"","text":"こういうのはな単純なほうが盛り上がんだよ","start":2077.14,"favorite":false,"stableId":"6c18c81c-f183-4091-a3c3-03a6ebb380c3","sequenceId":704},{"id":705,"end":2080.23,"note":"","text":"どっち賭ける？　俺 カラス","start":2079.18,"favorite":false,"stableId":"b74e9fb3-059d-4336-8921-3505dee414b6","sequenceId":705},{"id":706,"end":2081.46,"note":"","text":"いやいや先に決めたら ずるいっすよ","start":2080.28,"favorite":false,"stableId":"216be99f-ceca-4eb3-b058-ca896f05c78f","sequenceId":706},{"id":707,"end":2083.71,"note":"","text":"-早いもん勝ち-え～っ！","start":2081.51,"favorite":false,"stableId":"1bad3f3b-773a-41a5-9a8d-0374c9c550c2","sequenceId":707},{"id":708,"end":2085.12,"note":"","text":"すいません","start":2083.88,"favorite":false,"stableId":"28930d19-aa23-43d1-a188-6e8092fae853","sequenceId":708},{"id":709,"end":2087.32,"note":"","text":"じゃ お願いします","start":2085.65,"favorite":false,"stableId":"1745f480-c2e4-49d7-b3dd-2d4ff396231d","sequenceId":709},{"id":710,"end":2089.84,"note":"","text":"開廷します","start":2088.72,"favorite":false,"stableId":"02336d20-1506-49a8-9487-b8f0f8403eca","sequenceId":710},{"id":711,"end":2091.09,"note":"","text":"裁判長","start":2089.89,"favorite":false,"stableId":"8b0485e6-f1ff-4704-9dfc-1bcaeb49ec56","sequenceId":711},{"id":712,"end":2095.08,"note":"","text":"-烏田検事-はい","start":2092.89,"favorite":false,"stableId":"0b1a2fe4-f244-40c5-9887-73416a533021","sequenceId":712},{"id":713,"end":2097.38,"note":"","text":"-少し いいでしょうか？-はい","start":2095.13,"favorite":false,"stableId":"db64df67-15f9-4314-80e7-3ee9feea5eb2","sequenceId":713},{"id":714,"end":2100.78,"note":"","text":"本日 再度証言を予定していた⸺","start":2097.43,"favorite":false,"stableId":"58e4a3b8-05fd-46a9-893c-892f8273ba36","sequenceId":714},{"id":715,"end":2104.35,"note":"","text":"証人の三澄ミコト先生ですが","start":2100.83,"favorite":false,"stableId":"23c71b8d-1e64-446a-b808-46d50d8cd8b8","sequenceId":715},{"id":716,"end":2106.04,"note":"","text":"出廷できなくなりました","start":2104.4,"favorite":false,"stableId":"6eb9e8cc-69e7-4dd6-8c7d-20ea0210d3d3","sequenceId":716},{"id":717,"end":2109.66,"note":"","text":"静粛に","start":2108.21,"favorite":false,"stableId":"1273e4a1-8401-4053-96d7-26e389950a91","sequenceId":717},{"id":718,"end":2111.09,"note":"","text":"何だよ つまんねえな～","start":2109.71,"favorite":false,"stableId":"c2e98081-038e-4b6c-ae17-476c944e1cfc","sequenceId":718},{"id":719,"end":2112.74,"note":"","text":"静粛に！","start":2111.14,"favorite":false,"stableId":"1294a30c-c8d8-4476-94df-06e251f6d239","sequenceId":719},{"id":720,"end":2116.28,"note":"","text":"烏田検事 よろしいでしょうか？","start":2113.68,"favorite":false,"stableId":"29dca537-47fa-4ef9-a918-7c6fc94499df","sequenceId":720},{"id":721,"end":2118.9,"note":"","text":"賢明な ご判断でしょう","start":2117.22,"favorite":false,"stableId":"a793691d-8d72-466d-9ae2-a26227c62689","sequenceId":721},{"id":722,"end":2122.75,"note":"","text":"では 本日は被告人質問のみということで","start":2118.95,"favorite":false,"stableId":"7e65ed4a-49bb-4a10-8a44-17ef7f6cc2e6","sequenceId":722},{"id":723,"end":2126.19,"note":"","text":"いえ 代理の証人を申請します","start":2122.92,"favorite":false,"stableId":"30b26cb3-722e-4439-9052-73e4f9c869e8","sequenceId":723},{"id":724,"end":2128.39,"note":"","text":"代理？","start":2126.59,"favorite":false,"stableId":"6715cbf1-6b0c-4d57-97e6-c7055503f0f8","sequenceId":724},{"id":725,"end":2138.9,"note":"","text":"法医学者の中堂 系先生です","start":2136,"favorite":false,"stableId":"2c3c34b2-b6fd-4be1-bf83-c7dfb5a3f048","sequenceId":725},{"id":726,"end":2141.26,"note":"","text":"同一の立証趣旨を前提に","start":2139.24,"favorite":false,"stableId":"5b3ec3e0-9716-411a-a067-5a00d9b76243","sequenceId":726},{"id":727,"end":2145.64,"note":"","text":"より適切な証人であると考え急きょ お呼びしました","start":2141.31,"favorite":false,"stableId":"9a02b9dd-c9df-4b17-a0f4-5d0288c52fa5","sequenceId":727},{"id":728,"end":2150.68,"note":"","text":"これに伴い 新証拠の取り調べを請求したいと思います","start":2145.88,"favorite":false,"stableId":"24659ac5-30ce-44c4-bce4-c75a597f7b16","sequenceId":728},{"id":729,"end":2156.59,"note":"","text":"所長が来るなら ともかくなんで三澄さんなの？","start":2153.55,"favorite":false,"stableId":"6cd05e39-a40f-4784-9cc9-ac1cb135f666","sequenceId":729},{"id":730,"end":2158.52,"note":"","text":"戻ってきませんか？","start":2157.06,"favorite":false,"stableId":"c01653c4-3ba3-42f8-b461-2cb9e01b3657","sequenceId":730},{"id":731,"end":2165.46,"note":"","text":"中堂さんには “クソ”の禁止を誓ってもらいました","start":2160.16,"favorite":false,"stableId":"229db407-04e4-442c-bff3-8747ad9a97b7","sequenceId":731},{"id":732,"end":2170.67,"note":"","text":"もう 同じ場所にいることが苦痛","start":2167.13,"favorite":false,"stableId":"96dccc18-b8b5-4800-a80d-3daa6fd51723","sequenceId":732},{"id":733,"end":2178.23,"note":"","text":"まあ 苦痛を感じてまで一緒に働くことないですね","start":2172.07,"favorite":false,"stableId":"1938dd1b-3d2a-4b7b-8898-b0d53fcb04f3","sequenceId":733},{"id":734,"end":2180.81,"note":"","text":"分かり合えない相手は います","start":2178.28,"favorite":false,"stableId":"993ce550-e987-4c3a-a96e-85fa25302ba0","sequenceId":734},{"id":735,"end":2183.91,"note":"","text":"代わりに これを","start":2181.95,"favorite":false,"stableId":"5a8ee7d1-3fcb-44a2-9068-17424a440c22","sequenceId":735},{"id":736,"end":2187.59,"note":"","text":"紹介状です","start":2185.75,"favorite":false,"stableId":"0f021bbd-e669-4f6a-927b-ce28172b748a","sequenceId":736},{"id":737,"end":2189.64,"note":"","text":"私の知り合いの教授が","start":2187.79,"favorite":false,"stableId":"509ef60a-6a81-4daa-9ab2-4d7c4e52e27b","sequenceId":737},{"id":738,"end":2193.12,"note":"","text":"“優秀な臨床検査技師なら雇いたい”と言っています","start":2189.69,"favorite":false,"stableId":"983d3049-cdda-4caf-a6b3-da3c33f931c4","sequenceId":738},{"id":739,"end":2197.39,"note":"","text":"教授は穏やかな人柄です","start":2194.09,"favorite":false,"stableId":"6a823469-e7db-49f5-894d-78a2b7a3b386","sequenceId":739},{"id":740,"end":2199.63,"note":"","text":"坂本さんに合うと思います","start":2197.56,"favorite":false,"stableId":"ab44f907-113b-4539-9fff-c07c980aeead","sequenceId":740},{"id":741,"end":2206.24,"note":"","text":"教授… ムーミン 好きかな？","start":2203.37,"favorite":false,"stableId":"4f6b21a3-6412-49f3-9199-bb22732c8cc6","sequenceId":741},{"id":742,"end":2208.46,"note":"","text":"はい？","start":2207.47,"favorite":false,"stableId":"3d53bdc4-79b4-4d56-a7e6-1f25ec4249ed","sequenceId":742},{"id":743,"end":2210.63,"note":"","text":"皮膚を保存していたホルマリン液から","start":2208.51,"favorite":false,"stableId":"e707b413-73b7-4467-92dc-5dc8c0f65ea6","sequenceId":743},{"id":744,"end":2213.66,"note":"","text":"鉄 クロムニッケルが検出された","start":2210.68,"favorite":false,"stableId":"bbc3be9c-2448-491c-8039-3e807fddd3b4","sequenceId":744},{"id":745,"end":2215.51,"note":"","text":"ステンレスを構成する成分だ","start":2213.71,"favorite":false,"stableId":"b9bc2902-fb6c-4828-93b0-99c8dc646e38","sequenceId":745},{"id":746,"end":2218.2,"note":"","text":"つまり 真の凶器は","start":2215.98,"favorite":false,"stableId":"396cefcd-0844-44c7-84af-decade1bec5f","sequenceId":746},{"id":747,"end":2220.6,"note":"","text":"ステンレスの包丁であるということですね","start":2218.25,"favorite":false,"stableId":"79af9f6e-3761-4061-95eb-584044aece44","sequenceId":747},{"id":748,"end":2221.74,"note":"","text":"お疲れさまです","start":2220.65,"favorite":false,"stableId":"b20e989a-72ae-47b3-b9a1-61c2fb464dac","sequenceId":748},{"id":749,"end":2223.24,"note":"","text":"-どんな感じ？-それが…","start":2221.79,"favorite":false,"stableId":"9ee6ebd1-a252-4bcb-b58c-c95b01e563d6","sequenceId":749},{"id":750,"end":2226.91,"note":"","text":"検察の主張する凶器はセラミックの包丁ですが","start":2223.29,"favorite":false,"stableId":"aaf0b67f-2b9c-4573-a029-509482cac0d4","sequenceId":750},{"id":751,"end":2229.88,"note":"","text":"ありえない成分表を見ればバカでも分かる","start":2226.96,"favorite":false,"stableId":"adf00894-f594-469c-a8da-454187cfec6f","sequenceId":751},{"id":752,"end":2232.26,"note":"","text":"態度が悪いです","start":2229.93,"favorite":false,"stableId":"388107f0-a143-4e56-a628-b6343cda49c2","sequenceId":752},{"id":753,"end":2237.52,"note":"","text":"中堂さん","start":2235.4,"favorite":false,"stableId":"1317c28f-77f4-4b53-bbb8-d774bd8bc259","sequenceId":753},{"id":754,"end":2241.21,"note":"","text":"あなたの解剖実績はいかほどでしょうか？","start":2237.57,"favorite":false,"stableId":"00d7a64b-b088-4180-878a-d943264fa584","sequenceId":754},{"id":755,"end":2246.51,"note":"","text":"ああ…3100だか 200だったか","start":2241.57,"favorite":false,"stableId":"62d14f69-129e-4c76-bcfb-a00f140d0ec2","sequenceId":755},{"id":756,"end":2251.17,"note":"","text":"先日この包丁が凶器に間違いないと","start":2247.31,"favorite":false,"stableId":"1907f936-f94e-4f81-a4bf-e1566daf3864","sequenceId":756},{"id":757,"end":2252.97,"note":"","text":"おっしゃった草野教授は⸺","start":2251.22,"favorite":false,"stableId":"aaf49435-cd37-4b3c-8fc5-40b566359f52","sequenceId":757},{"id":758,"end":2256.9,"note":"","text":"１万5000件の解剖実績をお持ちでした","start":2253.02,"favorite":false,"stableId":"d291bd2b-b8aa-4023-9c46-1e5c8999db6f","sequenceId":758},{"id":759,"end":2259.91,"note":"","text":"それに比べるとかなり少ないですね～","start":2256.95,"favorite":false,"stableId":"1425718d-d5ab-4faf-8c6b-35d01149604c","sequenceId":759},{"id":760,"end":2261.93,"note":"","text":"カビの生えた経験が何になる","start":2259.96,"favorite":false,"stableId":"51b83d92-154a-4bbf-a1d2-4147d4dfadb8","sequenceId":760},{"id":761,"end":2265.41,"note":"","text":"医療と同じで法医学も年々 進歩してる","start":2262.83,"favorite":false,"stableId":"ad8cba5b-5c59-42b1-8538-566c1d36bc56","sequenceId":761},{"id":762,"end":2268.07,"note":"","text":"件数より 目の前の鑑定結果を見ろ","start":2265.46,"favorite":false,"stableId":"9c5fb00d-8f3b-4a84-a042-30c27d9c0d87","sequenceId":762},{"id":763,"end":2270.87,"note":"","text":"それがすべてだ","start":2269.07,"favorite":false,"stableId":"3c1e61af-d7fc-4bfb-8701-03df64e98fd8","sequenceId":763},{"id":764,"end":2273.69,"note":"","text":"あなたが凶器を否定される根拠は","start":2270.97,"favorite":false,"stableId":"8ad392cf-0bb4-4864-99bc-cd81389bdb6a","sequenceId":764},{"id":765,"end":2275.02,"note":"","text":"鉄 クロム ニッケル","start":2273.74,"favorite":false,"stableId":"8b0b1d6a-88a2-47fb-884a-4528e569b896","sequenceId":765},{"id":766,"end":2277.09,"note":"","text":"しかし それらの成分が","start":2275.07,"favorite":false,"stableId":"dffde1c0-ff16-4e65-a7fe-1413b177414b","sequenceId":766},{"id":767,"end":2280.64,"note":"","text":"凶器から出たものとは言いきれませんよね？","start":2277.14,"favorite":false,"stableId":"668e7c29-afcc-4de2-8b16-cb8318ae714f","sequenceId":767},{"id":768,"end":2284.77,"note":"","text":"解剖には メス ハサミなどさまざまな器具を使います","start":2280.98,"favorite":false,"stableId":"2f2248ab-6691-4cb6-9b7a-21e768b341e1","sequenceId":768},{"id":769,"end":2287.1,"note":"","text":"その解剖器具の素材にも","start":2284.82,"favorite":false,"stableId":"a708dbc0-d59c-49a6-b5ae-84029ea95212","sequenceId":769},{"id":770,"end":2289.74,"note":"","text":"鉄 クロム ニッケルは含まれるのではありませんか？","start":2287.15,"favorite":false,"stableId":"5d358fcb-dc63-4ea2-a9f9-445e7e2588f2","sequenceId":770},{"id":771,"end":2292.57,"note":"","text":"つまり ホルマリン溶液から検出されたのは","start":2289.79,"favorite":false,"stableId":"407e21be-53fb-4335-8a72-500f64d904fd","sequenceId":771},{"id":772,"end":2296.36,"note":"","text":"その解剖器具の微粒子とも考えられるわけです","start":2292.62,"favorite":false,"stableId":"788de318-46c4-4fe0-97ac-1050ad0c0245","sequenceId":772},{"id":773,"end":2299.13,"note":"","text":"バカか","start":2297.26,"favorite":false,"stableId":"5bac342e-c04b-42a7-894d-a1630ad93cc7","sequenceId":773},{"id":774,"end":2303.95,"note":"","text":"解剖器具から そんなポロポロ微粒子が落っこちてたまるか","start":2300.36,"favorite":false,"stableId":"e73d5cc2-422c-472f-a9d9-95b0ee3d7a7b","sequenceId":774},{"id":775,"end":2306.12,"note":"","text":"凶器と背骨がぶつかったから出た成分だ","start":2304,"favorite":false,"stableId":"56f5866c-90a8-4cc2-915d-258b279ff60b","sequenceId":775},{"id":776,"end":2307.96,"note":"","text":"それは あなたの思い込みでしょう","start":2306.17,"favorite":false,"stableId":"5cb40ca4-e4e7-49b2-825d-12b405f5ef7f","sequenceId":776},{"id":777,"end":2309.82,"note":"","text":"何の根拠も客観性もない","start":2308.01,"favorite":false,"stableId":"9fa7bdba-ae54-4621-8b60-35c25b8f86fb","sequenceId":777},{"id":778,"end":2312.16,"note":"","text":"まともな法医学者とは思えない言葉です","start":2309.87,"favorite":false,"stableId":"b7d1af8e-f366-4bb8-a4af-4357d9adb720","sequenceId":778},{"id":779,"end":2314.51,"note":"","text":"知らないようだから教えてやる","start":2312.21,"favorite":false,"stableId":"ba095c9c-ec29-43a9-a9ab-51352fee95bd","sequenceId":779},{"id":780,"end":2316.86,"note":"","text":"解剖で使うハサミは","start":2315.58,"favorite":false,"stableId":"c847a4e2-6f4f-4082-bdf4-ca0287b26b11","sequenceId":780},{"id":781,"end":2319.6,"note":"","' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || 'text":"切れなくなったら捨てて新しいものに替える","start":2316.91,"favorite":false,"stableId":"4e0e38ec-b2eb-454e-949d-efe20dd8eb0e","sequenceId":781},{"id":782,"end":2321.44,"note":"","text":"解剖で使うメスは","start":2319.65,"favorite":false,"stableId":"32738ef4-e8d2-4481-a5ac-d0e36cc8ed41","sequenceId":782},{"id":783,"end":2323.04,"note":"","text":"カッターのような替え刃になっていて","start":2321.49,"favorite":false,"stableId":"953b0164-10fd-4d15-a270-d4537c66fd48","sequenceId":783},{"id":784,"end":2325.54,"note":"","text":"切れなくなったら刃を交換する","start":2323.09,"favorite":false,"stableId":"20efe3dd-0793-47d2-a2d3-b724d19b4a66","sequenceId":784},{"id":785,"end":2328.86,"note":"","text":"解剖医によって気に入りのメスがあってな","start":2325.59,"favorite":false,"stableId":"413af8e3-5a62-435f-be7a-58756eaeabc7","sequenceId":785},{"id":786,"end":2331.18,"note":"","text":"俺はドイツ製が気に入りだ","start":2329.59,"favorite":false,"stableId":"0419d5d1-a087-4a17-bfab-f18bd617740e","sequenceId":786},{"id":787,"end":2334.65,"note":"","text":"裁判長 証人のムダ話をやめさせてください","start":2331.23,"favorite":false,"stableId":"02cb6009-409f-46eb-9e61-4a90b27b8f56","sequenceId":787},{"id":788,"end":2336.92,"note":"","text":"証人は聞かれたことに答えるように","start":2334.7,"favorite":false,"stableId":"a36076bb-5cb4-472f-8089-752e2e800109","sequenceId":788},{"id":789,"end":2339.22,"note":"","text":"聞かれたことに答えてる","start":2336.97,"favorite":false,"stableId":"a697d2d2-13f5-42ad-80a5-024293728d5d","sequenceId":789},{"id":790,"end":2340.29,"note":"","text":"何を聞いてたんだ？","start":2339.27,"favorite":false,"stableId":"4fe1beca-d056-44c3-9d67-c7ffc561a778","sequenceId":790},{"id":791,"end":2342.76,"note":"","text":"いいかげんにしなさい！","start":2340.34,"favorite":false,"stableId":"61e743cd-c9e9-4740-9a42-b6be7f97fd0a","sequenceId":791},{"id":792,"end":2344.83,"note":"","text":"法廷を侮辱するつもりですか！","start":2342.81,"favorite":false,"stableId":"181ac6ee-3cbe-4b12-bfd7-ebc58aee956c","sequenceId":792},{"id":793,"end":2347.83,"note":"","text":"まあまあ そう感情的になるな","start":2344.88,"favorite":false,"stableId":"e670ca5e-2c96-456c-aaaf-90c3692bc0ea","sequenceId":793},{"id":794,"end":2350.71,"note":"","text":"大事なことだからもう一度だけ教えてやる","start":2347.88,"favorite":false,"stableId":"59e3f34b-06e9-4852-a063-6e95af990c1e","sequenceId":794},{"id":795,"end":2353.48,"note":"","text":"メスもハサミも 刃は使い捨て","start":2350.88,"favorite":false,"stableId":"fbfc2c9f-a2c2-41ae-8f00-a6ae6f5c609d","sequenceId":795},{"id":796,"end":2355.69,"note":"","text":"研いだりはしない","start":2353.88,"favorite":false,"stableId":"2d48dd50-bf60-42e2-8567-f7ee8d926928","sequenceId":796},{"id":797,"end":2357.44,"note":"","text":"それが どうした？","start":2356.29,"favorite":false,"stableId":"df13314b-e301-4e00-98c7-d8ae1a0062d7","sequenceId":797},{"id":798,"end":2359.19,"note":"","text":"成分表をよく見てみろ","start":2357.49,"favorite":false,"stableId":"6ff358ee-b39b-4852-81db-7bd01d083ec6","sequenceId":798},{"id":799,"end":2361.43,"note":"","text":"ケイ素の数値が異常に高い","start":2359.36,"favorite":false,"stableId":"24c48b17-c504-4f96-9745-04cabfc19adb","sequenceId":799},{"id":800,"end":2364.16,"note":"","text":"包丁だけではあんな数値にはならない","start":2361.59,"favorite":false,"stableId":"df98b71a-0446-4989-923f-f848d44b4efa","sequenceId":800},{"id":801,"end":2366.85,"note":"","text":"元素分析で原因を特定したら","start":2364.66,"favorite":false,"stableId":"1c0088e3-4466-47f2-91af-0811dd1219ae","sequenceId":801},{"id":802,"end":2368.43,"note":"","text":"合砥(あわせど)だった","start":2366.9,"favorite":false,"stableId":"e687da11-b493-4b2a-a1bc-117964a14d71","sequenceId":802},{"id":803,"end":2370.63,"note":"","text":"あわせど？","start":2369.2,"favorite":false,"stableId":"87faad2d-e1cd-43cc-b82a-28fc105525d8","sequenceId":803},{"id":804,"end":2373.79,"note":"","text":"希少な石で","start":2372.3,"favorite":false,"stableId":"075cde6e-2378-48ab-842e-01d449eb4a00","sequenceId":804},{"id":805,"end":2375.56,"note":"","text":"京都の料理人が包丁を研ぐ時に使う⸺","start":2373.84,"favorite":false,"stableId":"f3a80096-e36d-4f62-ae1d-92c781e27d92","sequenceId":805},{"id":806,"end":2377.84,"note":"","text":"中でも最高の砥石(といし)","start":2375.61,"favorite":false,"stableId":"62244a31-3be9-4d28-8a86-1c627e2e34ac","sequenceId":806},{"id":807,"end":2379.26,"note":"","text":"セラミックの包丁は","start":2378.01,"favorite":false,"stableId":"f7799bf3-b513-43ae-abd8-e5a1e606430e","sequenceId":807},{"id":808,"end":2380.9,"note":"","text":"合砥では研げない","start":2379.31,"favorite":false,"stableId":"953fd946-525e-48ba-907a-e4de3fa3da75","sequenceId":808},{"id":809,"end":2383.05,"note":"","text":"解剖器具は刃を研がない","start":2380.95,"favorite":false,"stableId":"923c757b-747c-4dd9-a755-d6eb9ea80672","sequenceId":809},{"id":810,"end":2385.18,"note":"","text":"残された可能性は１つ","start":2383.28,"favorite":false,"stableId":"ce10896a-e380-429a-91b5-7d56c85ae7d8","sequenceId":810},{"id":811,"end":2390.79,"note":"","text":"真の凶器は 合砥で手入れをされたステンレスの包丁","start":2385.62,"favorite":false,"stableId":"59ae0154-c797-4442-a90b-ec54b5aa170d","sequenceId":811},{"id":812,"end":2395.28,"note":"","text":"以上だ","start":2394.09,"favorite":false,"stableId":"abe546a1-f0fa-48f8-9f85-6c291e373e7b","sequenceId":812},{"id":813,"end":2398.13,"note":"","text":"勝手に終わらせるな！","start":2395.33,"favorite":false,"stableId":"87360084-92f8-46b9-945c-2c99c905dac1","sequenceId":813},{"id":814,"end":2408.14,"note":"","text":"合砥…","start":2405.94,"favorite":false,"stableId":"cdc9c0b9-1b65-48ac-ae06-d075c84653cc","sequenceId":814},{"id":815,"end":2414.9,"note":"","text":"京都の… 料理人","start":2411.34,"favorite":false,"stableId":"0789a458-598b-493b-9924-061e8635add9","sequenceId":815},{"id":816,"end":2417.47,"note":"","text":"神田で京料理の店を出させてくれたし","start":2414.95,"favorite":false,"stableId":"8ba9a09c-ad53-4fea-937b-297a62a48615","sequenceId":816},{"id":817,"end":2422.82,"note":"","text":"♪～","start":2417.52,"favorite":false,"stableId":"42005168-e1c6-4685-93f2-d703e619355a","sequenceId":817},{"id":818,"end":2431.83,"note":"","text":"殺してません！","start":2429.79,"favorite":false,"stableId":"1a35c6c3-c9c6-4ba2-8e9c-8771e0c92d01","sequenceId":818},{"id":819,"end":2437,"note":"","text":"私は… やってない","start":2433.53,"favorite":false,"stableId":"8b3e56f8-72d5-4423-984b-d6b26b775af0","sequenceId":819},{"id":820,"end":2440.44,"note":"","text":"殺してないんです！","start":2438.57,"favorite":false,"stableId":"12d5d581-c1dd-4d75-9a6c-17e3d3737a69","sequenceId":820},{"id":821,"end":2452.32,"note":"","text":"ありがとうございました！","start":2450.61,"favorite":false,"stableId":"ba2a16db-9ee9-4ded-8176-98cef0a83d10","sequenceId":821},{"id":822,"end":2454.32,"note":"","text":"ふざけるな","start":2452.88,"favorite":false,"stableId":"2fab8332-4adc-46cb-b5ac-e74eaee0f0f8","sequenceId":822},{"id":823,"end":2456.04,"note":"","text":"女は信用できねえだと⸺","start":2454.49,"favorite":false,"stableId":"6783d6b0-92e5-49a0-94b2-e06267d38d8e","sequenceId":823},{"id":824,"end":2458.99,"note":"","text":"お前がクソ小せえこと言ってるから俺が駆り出されたんだ","start":2456.09,"favorite":false,"stableId":"6dd64927-bf5c-4583-afbd-ddc8f79c69a6","sequenceId":824},{"id":825,"end":2462.91,"note":"","text":"人なんて どいつもこいつも","start":2461.49,"favorite":false,"stableId":"606c52de-4d60-413f-8228-140706f1bab3","sequenceId":825},{"id":826,"end":2465.7,"note":"","text":"切り開いて 皮を剥げばただの肉の塊だ","start":2462.96,"favorite":false,"stableId":"3064e785-3664-4fc3-8d82-c158ec66c43b","sequenceId":826},{"id":827,"end":2467.63,"note":"","text":"死ねば分かる","start":2466.03,"favorite":false,"stableId":"3cc63704-7e74-44b3-ac88-81dc7d58bef0","sequenceId":827},{"id":828,"end":2479.66,"note":"","text":"宍戸さん １万円","start":2476.77,"favorite":false,"stableId":"f0e6b881-a1a8-4187-bcd7-9f1b8758833b","sequenceId":828},{"id":829,"end":2482.66,"note":"","text":"何 言ってんだお前が賭けたの 女法医学者だろ？","start":2479.71,"favorite":false,"stableId":"6fca6143-3492-4650-9109-b073b870e064","sequenceId":829},{"id":830,"end":2484.53,"note":"","text":"女法医学者は負けたの","start":2482.71,"favorite":false,"stableId":"8dd255c1-e7ce-4015-a23d-e567cf7868f2","sequenceId":830},{"id":831,"end":2488.22,"note":"","text":"烏田との戦いに尻尾巻いて逃げたんだよ","start":2484.58,"favorite":false,"stableId":"d39ec588-1c94-4d48-ac89-da9391fe8596","sequenceId":831},{"id":832,"end":2490.65,"note":"","text":"おっ それよりもあっち","start":2488.39,"favorite":false,"stableId":"823feec4-8e76-4ec1-8b2a-d7a58c54955f","sequenceId":832},{"id":833,"end":2493.41,"note":"","text":"元 日彰(にっしょう)医大の中堂 系先生","start":2490.76,"favorite":false,"stableId":"0b8929e2-a70d-4df8-80c5-36e1853298a2","sequenceId":833},{"id":834,"end":2495.06,"note":"","text":"あっ 中堂さん","start":2493.46,"favorite":false,"stableId":"7244b431-6349-4d60-8208-0ac3c32e39a3","sequenceId":834},{"id":835,"end":2502.8,"note":"","text":"法廷で お会いするとは思いませんでしたよ","start":2499.33,"favorite":false,"stableId":"8c874f5f-2868-4ed6-8eb9-b445a6427715","sequenceId":835},{"id":836,"end":2506.97,"note":"","text":"それも まさか証言台に立つとは","start":2503.5,"favorite":false,"stableId":"ba6b7a6e-cb18-4eba-8eb1-79ed1b5a80e4","sequenceId":836},{"id":837,"end":2512.48,"note":"","text":"これね","start":2511.24,"favorite":false,"stableId":"99fbec26-4ca5-4e05-b0a9-1dba49be9f0c","sequenceId":837},{"id":838,"end":2516.46,"note":"","text":"セルマランドゲランドのゲランドの塩","start":2513.01,"favorite":false,"stableId":"c28fb0ca-743c-49b8-b2e2-b72f17a456bd","sequenceId":838},{"id":839,"end":2518.37,"note":"","text":"な… 何 言ってるか分かんないっす","start":2516.51,"favorite":false,"stableId":"fbf03ce8-b533-4d45-91fe-f9cf0477da6c","sequenceId":839},{"id":840,"end":2521.47,"note":"","text":"お肉が優しくおいし～くなるんです","start":2518.42,"favorite":false,"stableId":"20bb890f-c10c-4409-b2e6-45baa90053e8","sequenceId":840},{"id":841,"end":2523.12,"note":"","text":"失礼します","start":2521.52,"favorite":false,"stableId":"639e14e3-e90d-4707-b8d1-0cd0eac9ff07","sequenceId":841},{"id":842,"end":2525.86,"note":"","text":"被害者の弟 自供しました","start":2523.45,"favorite":false,"stableId":"a5c5f59b-40ea-49dc-8fc0-020e4f361f6f","sequenceId":842},{"id":843,"end":2529.64,"note":"","text":"しずくさんのレシピは全部 弟さんが考えていて","start":2526.26,"favorite":false,"stableId":"340bb2b2-cd0f-4089-86fd-e600332c95e4","sequenceId":843},{"id":844,"end":2532.61,"note":"","text":"事件の日も 新しいレシピを頼まれていたそうです","start":2529.69,"favorite":false,"stableId":"2f7dd8cd-e315-438e-8046-2d0f2f855852","sequenceId":844},{"id":845,"end":2535.95,"note":"","text":"印税 半分くれよ俺にだって その権利はある！","start":2532.66,"favorite":false,"stableId":"fc1e0901-6cf7-4c36-8ffb-0abf48322179","sequenceId":845},{"id":846,"end":2537.65,"note":"","text":"バッカじゃない","start":2536,"favorite":false,"stableId":"82e07d81-bf0e-4852-8106-a4f0a51d9d4d","sequenceId":846},{"id":847,"end":2540.35,"note":"","text":"弟さんは自分の京料理の店が","start":2537.7,"favorite":false,"stableId":"5b414deb-4cb7-4787-8669-77a08f1ab049","sequenceId":847},{"id":848,"end":2542.06,"note":"","text":"傾きかけてたこともあって","start":2540.4,"favorite":false,"stableId":"ae5d2e96-ba25-4bdf-b0b7-a482b200519c","sequenceId":848},{"id":849,"end":2544.86,"note":"","text":"レシピを提供する代わりに印税をよこせと","start":2542.11,"favorite":false,"stableId":"6312bbdc-5cc9-4785-8ff4-c562c112cab9","sequenceId":849},{"id":850,"end":2546.03,"note":"","text":"姉に迫ったものの…","start":2544.91,"favorite":false,"stableId":"e79511cc-afce-4aa4-9872-79cf0213d4b4","sequenceId":850},{"id":851,"end":2548.46,"note":"","text":"さっさと潰れちゃえばいいのよそんな店","start":2546.08,"favorite":false,"stableId":"53c349d1-5d8c-443a-829d-bd9a1b233178","sequenceId":851},{"id":852,"end":2550.28,"note":"","text":"冷たく あしらわれ…","start":2548.51,"favorite":false,"stableId":"4655b236-70c5-4f4d-9e57-eed012d885a7","sequenceId":852},{"id":853,"end":2553.77,"note":"","text":"それで ブスーッといったか","start":2551.42,"favorite":false,"stableId":"1aa55b7c-9f37-4905-a90d-5c6eb85c7236","sequenceId":853},{"id":854,"end":2556.8,"note":"","text":"親族間の殺人は別れられないから起こる","start":2553.82,"favorite":false,"stableId":"5d45a3c3-1bc1-4f78-b0f9-b97ad93965c8","sequenceId":854},{"id":855,"end":2559.51,"note":"","text":"面倒くさい話だよね～","start":2556.85,"favorite":false,"stableId":"c4fef145-34b8-4004-8a0a-bc3685a64bf2","sequenceId":855},{"id":856,"end":2562.01,"note":"","text":"冤罪(えんざい)が防げて よかったです","start":2559.56,"favorite":false,"stableId":"eea408e8-f75f-45cb-8a2d-0982301e3788","sequenceId":856},{"id":857,"end":2563.71,"note":"","text":"お疲れさまでした","start":2562.06,"favorite":false,"stableId":"15371a1a-814f-4e2a-9d0e-20e7812f83bc","sequenceId":857},{"id":858,"end":2567.63,"note":"","text":"-お疲れさまでした-お疲れさまでした","start":2563.76,"favorite":false,"stableId":"660ede0a-1fe4-4344-90a0-260158e71e53","sequenceId":858},{"id":859,"end":2572.85,"note":"","text":"でもさ 私はミコトに証言台に立ってほしかったな～","start":2567.83,"favorite":false,"stableId":"a04d5de3-517e-47ef-9ad9-c453b2ef597b","sequenceId":859},{"id":860,"end":2575.26,"note":"","text":"ぎゃふんと言わせてビシッと勝ってほしかった","start":2572.9,"favorite":false,"stableId":"babdb971-d5a7-4b83-aa5d-39381bec2e87","sequenceId":860},{"id":861,"end":2579.13,"note":"","text":"しょうがないでしょ女じゃ ヤダって言われたんだから","start":2575.31,"favorite":false,"stableId":"081f4c28-df57-4384-a17c-3d05e45beab7","sequenceId":861},{"id":862,"end":2581.6,"note":"","text":"また 変な記事 書かれるよ","start":2579.18,"favorite":false,"stableId":"26376a35-a863-42bc-bac9-39ea78c197cb","sequenceId":862},{"id":863,"end":2583.93,"note":"","text":"“女法医学者の敗北”","start":2581.65,"favorite":false,"stableId":"66a7f702-9a6e-4074-897b-170d9ac6cc74","sequenceId":863},{"id":864,"end":2585.5,"note":"","text":"勝手に言ってろ","start":2583.98,"favorite":false,"stableId":"c401a4e3-1de9-4d04-a46a-1a0380799d82","sequenceId":864},{"id":865,"end":2587.89,"note":"","text":"法医学とは 何なのかって話よ","start":2585.55,"favorite":false,"stableId":"971840dc-6107-48d7-a753-7b34c679053a","sequenceId":865},{"id":866,"end":2589.55,"note":"","text":"何なのか…","start":2588.32,"favorite":false,"stableId":"8c126d56-36b9-4e60-a942-d7dd5cb8b564","sequenceId":866},{"id":867,"end":2594.11,"note":"","text":"法医学は 法治国家に不可欠な学問","start":2590.32,"favorite":false,"stableId":"bc3846c6-998b-4704-be80-4f5fb13031c5","sequenceId":867},{"id":868,"end":2596.14,"note":"","text":"法医学が おざなりにされるっていうことは","start":2594.16,"favorite":false,"stableId":"0e740cf7-f289-49c7-9d68-1b0b3be6d107","sequenceId":868},{"id":869,"end":2598.66,"note":"","text":"無法の国になるってこと","start":2596.19,"favorite":false,"stableId":"a4d522f4-fbd5-4be2-9bc0-38a065bcd7e0","sequenceId":869},{"id":870,"end":2599.93,"note":"","text":"-無法の国 住みたい？-嫌です","start":2598.93,"favorite":false,"stableId":"99286171-9e73-422f-a796-9e02ef4fedf0","sequenceId":870},{"id":871,"end":2601.6,"note":"","text":"-無法の国 住みたい？-嫌です","start":2599.93,"favorite":false,"stableId":"1ea87673-236b-4266-a6a8-4368e2f7b2f7","sequenceId":871},{"id":872,"end":2601.6,"note":"","text":"～♪","start":2599.93,"favorite":false,"stableId":"a6a3a01a-a60f-4695-830f-44aa38824932","sequenceId":872},{"id":873,"end":2601.67,"note":"","text":"～♪","start":2601.6,"favorite":false,"stableId":"1570df5c-4997-4ec5-8f4d-66b8164ed5d7","sequenceId":873},{"id":874,"end":2604.94,"note":"","text":"～♪","start":2601.67,"favorite":false,"stableId":"c3936647-c9f0-4d84-83d7-448456d5b28c","sequenceId":874},{"id":875,"end":2605.24,"note":"","text":"だから 今日のところは法医学の勝利でよしとしとくの","start":2601.67,"favorite":false,"stableId":"af7bd527-0cc0-42b1-9090-9e24701268e6","sequenceId":875},{"id":876,"end":2607.62,"note":"","text":"理想は遠いね～","start":2605.67,"favorite":false,"stableId":"a90d3cfa-5aec-4ec7-9351-049f6688604d","sequenceId":876},{"id":877,"end":2612.26,"note":"","text":"アイ ハブ ア ドリーム！いつか あらゆる差別のない世界を","start":2607.67,"favorite":false,"stableId":"4ecb5e6b-05ea-46aa-95a7-185e96548fcc","sequenceId":877},{"id":878,"end":2613.73,"note":"","text":"諦めないことが肝心です","start":2612.31,"favorite":false,"stableId":"8075741b-1b7f-4209-9cb2-a3a283fe1ba8","sequenceId":878},{"id":879,"end":2615.1,"note":"","text":"はい","start":2613.78,"favorite":false,"stableId":"8ec869fd-b309-48a8-8db9-be0bb26f70c7","sequenceId":879},{"id":880,"end":2618.43,"note":"","text":"残る問題は坂本さんの訴訟かな～","start":2615.15,"favorite":false,"stableId":"d499bed2-4b28-42fa-9c25-83f5b7aa522c","sequenceId":880},{"id":881,"end":2620.3,"note":"","text":"あっ 訴え取り下げてくれそうですよ","start":2618.48,"favorite":false,"stableId":"ae99b139-9fb4-4b45-bd67-40ad7abc59eb","sequenceId":881},{"id":882,"end":2621.52,"note":"","text":"えっ ホントに？","start":2620.35,"favorite":false,"stableId":"b4b56c61-54b1-4221-91c9-63a272268bfa","sequenceId":882},{"id":883,"end":2624.57,"note":"","text":"先方の教授が ムーミンを好きなら","start":2621.79,"favorite":false,"stableId":"6a982fc1-fb52-486e-9eee-35e44ab3bdfa","sequenceId":883},{"id":884,"end":2625.71,"note":"","text":"ムーミン？","start":2624.62,"favorite":false,"stableId":"26bb28cd-d9a2-42c5-9e61-48ea4adfa458","sequenceId":884},{"id":885,"end":2626.99,"note":"","text":"はい","start":2625.76,"favorite":false,"stableId":"dc889166-1782-43e6-8c71-845349d9ed80","sequenceId":885},{"id":886,"end":2629.54,"note":"","text":"おいしそうですね～","start":2628.19,"favorite":false,"stableId":"1a6914da-d244-40af-b37a-942f3df1fc0a","sequenceId":886},{"id":887,"end":2631.38,"note":"","text":"木林さん 一緒にどう？","start":2629.59,"favorite":false,"stableId":"fb1b1972-f2d3-4402-af40-408daabc554f","sequenceId":887},{"id":888,"end":2634.28,"note":"","text":"ああ すいませんこれから用事が… 失礼します","start":2631.43,"favorite":false,"stableId":"d1a8e110-4284-4f00-884b-bdc0c3ce4ed3","sequenceId":888},{"id":889,"end":2637.3,"note":"","text":"あら お疲れさまで～す","start":2634.33,"favorite":false,"stableId":"95ab98e2-e3ae-4f6b-9c77-3b336b877d77","sequenceId":889},{"id":890,"end":2646.44,"note":"","text":"あの２人 妙に仲いいよね","start":2643.21,"favorite":false,"stableId":"b9ae631f-147d-43e1-8622-c8fbc5ef16ca","sequenceId":890},{"id":891,"end":2648.83,"note":"","text":"-そういう関係？-そういう？","start":2646.54,"favorite":false,"stableId":"d7e58368-8068-46e4-819a-2d6a1af66267","sequenceId":891},{"id":892,"end":2650.13,"note":"","text":"ほっときなさいよ","start":2648.88,"favorite":false,"stableId":"ec4ff7e7-c0ef-4e3a-9a89-a1b973b0736d","sequenceId":892},{"id":893,"end":2652.55,"note":"","text":"東海林さん手が お留守になってる","start":2650.18,"favorite":false,"stableId":"fd207622-bcca-4471-a8f9-7764b6475811","sequenceId":893},{"id":894,"end":2657.34,"note":"","text":"法廷で お会いするとは","start":2655.42,"favorite":false,"stableId":"97995b70-d55a-45f0-94a1-3db2c3c3fa06","sequenceId":894},{"id":895,"end":2659.12,"note":"","text":"思いませんでしたよ","start":2657.39,"favorite":false,"stableId":"61ca5c79-9707-42f8-9d6e-776c4402d803","sequenceId":895},{"id":896,"end":2662.18,"note":"","text":"それも まさか証言台に立つとは","start":2659.32,"favorite":false,"stableId":"9e87129d-6b54-4001-ad37-12be8d6a012e","sequenceId":896},{"id":897,"end":2665.65,"note":"","text":"皮を剥げば 全員同じ","start":2662.23,"favorite":false,"stableId":"f9217c2e-2226-4f1d-8a56-397e6e3fb0e7","sequenceId":897},{"id":898,"end":2667.46,"note":"","text":"あなたが言うと説得力がある","start":2665.7,"favorite":false,"stableId":"54c4dbc6-dc86-4fdf-ad51-2cf141f8eb34","sequenceId":898},{"id":899,"end":2670.25,"note":"","text":"法医学者は人殺しの方法を","start":2668,"favorite":false,"stableId":"2398bfdb-7c4e-434b-baa6-32140fb2120a","sequenceId":899},{"id":900,"end":2673,"note":"","text":"知り尽くしたプロですからね","start":2670.3,"favorite":false,"stableId":"2a563794-5253-4e28-900d-ba2cb89baa9b","sequenceId":900},{"id":901,"end":2681.04,"note":"","text":"いつまでも逃げおおせると思うなよ","start":2676.74,"favorite":false,"stableId":"9e53baee-e7f4-41aa-b834-2baa40d44b24","sequenceId":901},{"id":902,"end":2703.65,"note":"","text":"交通事故の責任の","start":2702.6,"favorite":false,"stableId":"46623281-f8d1-44d5-bd95-20fdda96e4b9","sequenceId":902},{"id":903,"end":2704.99,"note":"","text":"所在を明らかにする","start":2703.7,"favorite":false,"stableId":"d97fdceb-3313-496e-bec8-99ea8a59ba3e","sequenceId":903},{"id":904,"end":2707.79,"note":"","text":"過労か事故死か 病死か","start":2705.04,"favorite":false,"stableId":"badd41fb-9315-4b12-a670-04709a600565","sequenceId":904},{"id":905,"end":2709.36,"note":"","text":"うちの工場は無関係です！","start":2707.84,"favorite":false,"stableId":"7da6187d-66ce-4a60-9151-86cb4de06d67","sequenceId":905},{"id":906,"end":2711.43,"note":"","text":"そんな大人の姿を見せられたら","start":2709.41,"favorite":false,"stableId":"7daf3091-b5d6-4088-8fe5-8e4d3393fe9d","sequenceId":906},{"id":907,"end":2713.93,"note":"","text":"子供は 石を投げるしかないですよ","start":2711.48,"favorite":false,"stableId":"6ea0daf2-2a43-4233-9692-e4f1fb5658bb","sequenceId":907},{"id":908,"end":2715.2,"note":"","text":"中堂さんは","start":2713.98,"favorite":false,"stableId":"9252e395-4ae9-4916-bbad-bb3cf6988ce0","sequenceId":908},{"id":909,"end":2717.21,"note":"","text":"誰を殺したんですか？","start":2715.25,"favorite":false,"stableId":"8f485136-f368-4526-831e-0b0cf0aa127d","sequenceId":909}],"subtitleSeason":"1","subtitleEpisode":"3","subtitleNoAudio":true,"subtitleWorkTitle":"非自然死亡","subtitleSourceType":"TV"}' WHERE "id" = '1e2d815d-24f8-459a-91e2-1af9f72aa57f' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = '' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || '{"source":"钟表馆事件","language":"ja","dialogues":[{"id":1,"end":115.27,"note":"","text":"(鹿谷門実) コナンくん 紅茶でいいかい？","start":112.56,"favorite":false,"stableId":"84630a40-59ae-4dae-9f85-eb613b5b5ba1","sequenceId":1},{"id":2,"end":118.63,"note":"","text":"(江南孝明) あっ すいません ありがとうございます","start":115.32,"favorite":false,"stableId":"18660c9f-9741-46e4-9d13-15997419d63d","sequenceId":2},{"id":3,"end":123.41,"note":"","text":"(江南) <鹿谷さんの顔は――>","start":121.44,"favorite":false,"stableId":"328aff5e-8478-4fb5-93ce-52c066f53731","sequenceId":3},{"id":4,"end":124.58,"note":"","text":"<最後に会ったときと――>","start":123.46,"favorite":false,"stableId":"0e6f0c0d-c437-4486-83df-5bd527ce86b3","sequenceId":4},{"id":5,"end":127.22,"note":"","text":"<全く変わるところがなかった>","start":124.63,"favorite":false,"stableId":"5b7d5acb-1179-46bc-87d4-b5a24e8a4abe","sequenceId":5},{"id":6,"end":142.01,"note":"","text":"<３年前 1986年の３月>","start":138.04,"favorite":false,"stableId":"d5e74c1b-9210-4934-9f3b-8c0797f65138","sequenceId":6},{"id":7,"end":144.97,"note":"","text":"<当時 Ｋ大学の学生だった僕は――>","start":142.06,"favorite":false,"stableId":"39343000-73f5-4633-8f5b-1122ccbe4a04","sequenceId":7},{"id":8,"end":151.37,"note":"","text":"<まだ作家デビュー前の鹿谷門実 本名 島田 潔と偶然 出会った>","start":145.02,"favorite":false,"stableId":"3071d535-b796-44f3-a14a-1e5a78a54ffc","sequenceId":8},{"id":9,"end":153.85,"note":"","text":"<好奇心旺盛な彼は――>","start":151.42,"favorite":false,"stableId":"08644e0e-69fc-4335-ae44-9d87e0a9a886","sequenceId":9},{"id":10,"end":158.61,"note":"","text":"<僕に届いた“死者からの手紙”の謎を一緒に探ることになり――>","start":153.9,"favorite":false,"stableId":"a16b2009-3a69-4ac1-97be-9b661b24e82c","sequenceId":10},{"id":11,"end":161.53,"note":"","text":"<十角館という 建物を舞台に――>","start":158.66,"favorite":false,"stableId":"652cdad1-1f24-4b04-932d-a1ffba320c2c","sequenceId":11},{"id":12,"end":163.78,"note":"","text":"<僕が かつて所属していた――>","start":161.58,"favorite":false,"stableId":"958ecb09-8f17-43e5-bfc0-9305966c0a9a","sequenceId":12},{"id":13,"end":166.08,"note":"","text":"<ミステリ研究会の 友人たちを見舞った――>","start":163.83,"favorite":false,"stableId":"580276c3-576c-43cf-a5b4-6e9b8bee6f82","sequenceId":13},{"id":14,"end":168.55,"note":"","text":"<殺人事件に行き当たる ハメになった>","start":166.13,"favorite":false,"stableId":"ec074e97-f381-4bf3-9b40-723f48645b2b","sequenceId":14},{"id":15,"end":173.62,"note":"","text":"<その事件で 僕は 大勢の友人を亡くした>","start":168.86,"favorite":false,"stableId":"546922d5-8067-4614-81e5-5d194ac71250","sequenceId":15},{"id":16,"end":175.96,"note":"","text":"(鹿谷) こいつは おいしいぞ","start":173.67,"favorite":false,"stableId":"ea9c2296-b4ed-45b0-a448-afcd4fc93472","sequenceId":16},{"id":17,"end":178.92,"note":"","text":"(江南) すみません 時間 遅れてしまって","start":176.01,"favorite":false,"stableId":"9a449563-395d-4d5e-a9a1-79eb51c8d8dc","sequenceId":17},{"id":18,"end":180.44,"note":"","text":"(鹿谷) うん？","start":178.97,"favorite":false,"stableId":"2c129dd0-927d-48e1-9a74-7732bea7982b","sequenceId":18},{"id":19,"end":182.8,"note":"","text":"約束は４時だっただろう","start":180.87,"favorite":false,"stableId":"f386d70c-ece7-459a-a41e-49d04b13ea69","sequenceId":19},{"id":20,"end":184.76,"note":"","text":"別に遅れてなんかいないじゃないか","start":182.85,"favorite":false,"stableId":"755c000d-aac9-4e3d-9ef1-aae20774bc67","sequenceId":20},{"id":21,"end":187.35,"note":"","text":"(江南) もう４時半を過ぎてるんですけど","start":184.81,"favorite":false,"stableId":"a2a17c98-a2c5-4b96-8ef4-3204f1712218","sequenceId":21},{"id":22,"end":189.07,"note":"","text":"(鹿谷) そりゃ変だ","start":187.4,"favorite":false,"stableId":"def5a640-fab5-4fcf-97df-1cf73cd38d97","sequenceId":22},{"id":23,"end":192.87,"note":"","text":"だって まだ４時前…","start":190.34,"favorite":false,"stableId":"50d7871a-a053-4188-bb14-ce645dd64967","sequenceId":23},{"id":24,"end":195.27,"note":"","text":"あれ？","start":193.76,"favorite":false,"stableId":"1b4362b7-eb8e-4112-9104-38b2a36efcdb","sequenceId":24},{"id":25,"end":197.11,"note":"","text":"止まってるじゃないか","start":195.32,"favorite":false,"stableId":"0913e14f-9be0-4ed6-9f0a-0f3ee4bd3b76","sequenceId":25},{"id":26,"end":198.73,"note":"","text":"ええっ？","start":197.16,"favorite":false,"stableId":"875e31d7-b534-4224-9d49-1817e10577e8","sequenceId":26},{"id":27,"end":203.3,"note":"","text":"えっ… 古道具屋で見つけて 買ったばかりなんだけどなぁ","start":198.78,"favorite":false,"stableId":"ea1900f1-2d00-4c2b-924a-d0661f0f6599","sequenceId":27},{"id":28,"end":206.13,"note":"","text":"えっ？ 壊れてるのかな？","start":203.81,"favorite":false,"stableId":"a25cdf03-ab77-42a3-811f-71475401e88e","sequenceId":28},{"id":29,"end":209.43,"note":"","text":"(鹿谷) おいおい おいおい","start":206.82,"favorite":false,"stableId":"63e4dc87-ac54-4ae4-bf7e-8db02162770d","sequenceId":29},{"id":30,"end":216.23,"note":"","text":"(江南) ホントびっくりしちゃいましたよ","start":213.16,"favorite":false,"stableId":"c48d3eea-dd10-4864-bd30-21c37eca30d1","sequenceId":30},{"id":31,"end":222.06,"note":"","text":"知らないうちに 作家になってるんですから","start":219.12,"favorite":false,"stableId":"1ee27054-375f-4fb7-b50f-d016fdcaf5e4","sequenceId":31},{"id":32,"end":225.4,"note":"","text":"(鹿谷) 僕のほうこそ 驚いたねえ","start":222.62,"favorite":false,"stableId":"acd76f2d-6c60-4c70-8a45-536f32d5f142","sequenceId":32},{"id":33,"end":230.72,"note":"","text":"工学部出身の君が よりにもよって 稀譚社に就職したっていうんだから","start":225.88,"favorite":false,"stableId":"c4b7c06a-f7ac-4498-abae-129020a86128","sequenceId":33},{"id":34,"end":233.39,"note":"","text":"(江南) いや… 冷やかしのつもりで受けたら――","start":230.77,"favorite":false,"stableId":"4b8645bb-20d4-47f9-b2bc-28106a61f732","sequenceId":34},{"id":35,"end":235.35,"note":"","text":"採用になっちゃったんです","start":233.44,"favorite":false,"stableId":"8a722ce2-f911-42a6-9c77-b2f43a9390e6","sequenceId":35},{"id":36,"end":237.65,"note":"","text":"あっ でも おかげで この春から――","start":235.4,"favorite":false,"stableId":"01dd7a4c-8bae-4f3e-98b4-346a0127354c","sequenceId":36},{"id":37,"end":240.82,"note":"","text":"｢CHAOS｣っていう月刊誌の 編集部に回されて…","start":237.7,"favorite":false,"stableId":"014dfb47-35a1-4cfd-a1e6-2b2c9f1b25f2","sequenceId":37},{"id":38,"end":242.25,"note":"","text":"(鹿谷) 読んだことあるよ","start":240.87,"favorite":false,"stableId":"78e972f7-46b8-4489-90b7-28a4cf51b406","sequenceId":38},{"id":39,"end":246.28,"note":"","text":"ミステリーとはいっても 超常現象方面の雑誌だよね","start":242.94,"favorite":false,"stableId":"0fa2be06-81cc-48ad-a56d-f1bdb6eefe5c","sequenceId":39},{"id":40,"end":248.32,"note":"","text":"(江南) ええ　その｢CHAOS｣で――","start":246.33,"favorite":false,"stableId":"3a02a4dd-0d21-449d-a1f1-11be0b92c29d","sequenceId":40},{"id":41,"end":252.18,"note":"","text":"僕が担当している 特別企画があって…","start":248.37,"favorite":false,"stableId":"f56ab8fd-1003-495d-8065-b810164bc851","sequenceId":41},{"id":42,"end":258.64,"note":"","text":"“鎌倉･時計屋敷の 亡霊に挑む”っていう企画なんです","start":253.7,"favorite":false,"stableId":"264cb409-1f0c-49c3-936e-178c96715c30","sequenceId":42},{"id":43,"end":260.96,"note":"","text":"(鹿谷) 時計屋敷？","start":259.33,"favorite":false,"stableId":"c1f5880c-f48d-4f83-8c0d-def127113f65","sequenceId":43},{"id":44,"end":263.51,"note":"","text":"(江南) 地元では “時計館”とも呼ばれてる――","start":261.01,"favorite":false,"stableId":"89622af8-f715-4d1e-bb4b-32080e239773","sequenceId":44},{"id":45,"end":265.61,"note":"","text":"奇妙な建物だそうで…","start":263.56,"favorite":false,"stableId":"24971383-c3c0-4f84-b944-62bece76ca70","sequenceId":45},{"id":46,"end":268.99,"note":"","text":"それで 調べてみたら…","start":265.83,"favorite":false,"stableId":"cc8ec277-902c-4683-b313-0db5530a650b","sequenceId":46},{"id":47,"end":280.83,"note":"","text":"その時計館 あの中村青司が 設計した建物のひとつらしいんです","start":273.67,"favorite":false,"stableId":"fa30cec8-06f7-4d76-bcb8-47c6a45e272f","sequenceId":47},{"id":48,"end":284.21,"note":"","text":"フフッ…","start":282.52,"favorite":false,"stableId":"96e92555-4318-49b5-ae09-a5bae624e767","sequenceId":48},{"id":49,"end":298.35,"note":"","text":"あの十角館を設計した 建築家の中村青司…","start":291.07,"favorite":false,"stableId":"a0aa0a58-3399-4ba1-a93f-82a1b232e665","sequenceId":49},{"id":50,"end":302.19,"note":"","text":"(鹿谷) 妙に子供じみた趣味があってね","start":298.7,"favorite":false,"stableId":"88fbaac7-661a-4fbd-8635-db32882acd0e","sequenceId":50},{"id":51,"end":305.34,"note":"","text":"自分が関わった建物には――","start":302.79,"favorite":false,"stableId":"bb83671b-9c5b-4a89-8ec4-333e69b42e1a","sequenceId":51},{"id":52,"end":309.3,"note":"","text":"隠し扉とか 秘密の抜け道とか――","start":305.39,"favorite":false,"stableId":"596146e0-7cf1-4632-9de9-de7f1263246e","sequenceId":52},{"id":53,"end":312.05,"note":"","text":"その手の からくり仕掛けを…","start":309.35,"favorite":false,"stableId":"7f70c266-c3f7-4565-844b-828de395a2ad","sequenceId":53},{"id":54,"end":315.98,"note":"","text":"時には 建築主にもナイショで 作ることもあったという――","start":312.1,"favorite":false,"stableId":"e24f5548-da81-4ffc-ba23-9a5c5e3c2ab6","sequenceId":54},{"id":55,"end":317.73,"note":"","text":"あの中村青司","start":316.03,"favorite":false,"stableId":"da5a3cf1-cfd5-4c0f-ad74-2d11f53fa021","sequenceId":55},{"id":56,"end":319.23,"note":"","text":"はい","start":317.78,"favorite":false,"stableId":"370664a2-f8a7-4f18-aa0c-f26dfcb18a86","sequenceId":56},{"id":57,"end":320.69,"note":"","text":"その時計館は――","start":319.28,"favorite":false,"stableId":"64ca8b39-7ace-462d-a3cb-157827b29b0b","sequenceId":57},{"id":58,"end":324.69,"note":"","text":"もともとは 古峨倫典っていう人の 持ち物だったんですが","start":320.74,"favorite":false,"stableId":"ab01d56d-ccfe-4b0a-bf25-fcbf3358e374","sequenceId":58},{"id":59,"end":326.79,"note":"","text":"(鹿谷) 古峨倫典？","start":324.74,"favorite":false,"stableId":"dbc5cede-17af-4873-b42f-ae2b90d62918","sequenceId":59},{"id":60,"end":328.99,"note":"","text":"聞いたことある名前だなぁ","start":327.19,"favorite":false,"stableId":"0f1d902c-7c21-4e1f-8a16-a8a37ecf72a6","sequenceId":60},{"id":61,"end":330.57,"note":"","text":"有名人ですよ","start":329.04,"favorite":false,"stableId":"03389ea9-ccbf-45cf-a2ea-2fb04e0c28ef","sequenceId":61},{"id":62,"end":333.33,"note":"","text":"日本で１～２を争う時計メーカー","start":330.62,"favorite":false,"stableId":"9cbe9a9b-d523-491e-9fe2-c54794bd57ec","sequenceId":62},{"id":63,"end":336.68,"note":"","text":"古峨精計社の前会長ですから","start":333.38,"favorite":false,"stableId":"37ca3054-393c-4573-a772-3d2f2d468ad3","sequenceId":63},{"id":64,"end":341.75,"note":"","text":"古峨会長は ９年前に亡くなったんですが――","start":338.16,"favorite":false,"stableId":"a5fba1ba-e496-43c1-86ad-567badf9af8a","sequenceId":64},{"id":65,"end":346.36,"note":"","text":"その前後から 周辺で やたら 人死にが出ているらしくて","start":341.8,"favorite":false,"stableId":"ae68fd04-b14e-4164-b2e5-6865b6827d5d","sequenceId":65},{"id":66,"end":350.26,"note":"","text":"ある時期から 少女の幽霊が出るって ウワサが立つようになったそうです","start":346.58,"favorite":false,"stableId":"df717a3e-871f-41db-8e2f-9048c5702d4f","sequenceId":66},{"id":67,"end":351.44,"note":"","text":"(鹿谷) んん…","start":350.31,"favorite":false,"stableId":"18e8dc2b-c488-417d-82ac-a8d0e1aa5605","sequenceId":67},{"id":68,"end":356.35,"note":"","text":"(江南) その時計館も かなり奇妙な建物で――","start":352.67,"favorite":false,"stableId":"51a11201-a20a-4812-9f1d-7d9574abc271","sequenceId":68},{"id":69,"end":358.39,"note":"","text":"ヘンテコな時計塔があって――","start":356.4,"favorite":false,"stableId":"ec446f7b-7227-4869-8376-3cd659ac12ef","sequenceId":69},{"id":70,"end":360.48,"note":"","text":"複雑な形をした家の中は――","start":358.44,"favorite":false,"stableId":"a48d41b1-7bfc-4607-a92c-21f77ebdfee1","sequenceId":70},{"id":71,"end":364.02,"note":"","text":"古峨氏が収集した古い時計で いっぱいだとか","start":360.53,"favorite":false,"stableId":"72d72de3-3491-4bec-bd34-21fbeed1d4c7","sequenceId":71},{"id":72,"end":367.54,"note":"","text":"その特別企画というのは 具体的には？","start":364.07,"favorite":false,"stableId":"54e3a02d-e745-4e60-a257-ce2aa7b3c7b6","sequenceId":72},{"id":73,"end":370.5,"note":"","text":"それがですね…","start":368.06,"favorite":false,"stableId":"8f960259-4b24-400a-81a8-4e66dca8a64d","sequenceId":73},{"id":74,"end":372.41,"note":"","text":"うん？ どうかしたのかい？","start":370.73,"favorite":false,"stableId":"addae3bd-11d0-4dd3-ab49-ece515a8cd9e","sequenceId":74},{"id":75,"end":374.7,"note":"","text":"408号室 隣ですよね？","start":372.46,"favorite":false,"stableId":"4debd154-9dca-4d07-832c-3b4bb95e3f23","sequenceId":75},{"id":76,"end":377.39,"note":"","text":"(鹿谷) うん (江南) 住んでる人 ご存じですか？","start":374.75,"favorite":false,"stableId":"19e96472-1269-4857-9ee9-df987c940b51","sequenceId":76},{"id":77,"end":382.54,"note":"","text":"確か 光明寺とかいう名字の 女性だったかな？","start":377.82,"favorite":false,"stableId":"5701aaf9-3cf5-4955-beb4-ed795767a204","sequenceId":77},{"id":78,"end":384.21,"note":"","text":"(江南)“光明寺美琴”","start":382.59,"favorite":false,"stableId":"ec4629cf-a86f-49e0-9490-1c6296b2ba97","sequenceId":78},{"id":79,"end":387.38,"note":"","text":"最近 売り出し中の いわゆる 霊能者です","start":384.26,"favorite":false,"stableId":"90eb1818-939a-4112-8497-65f6c0727086","sequenceId":79},{"id":80,"end":389.09,"note":"","text":"(鹿谷) フッ… 霊能者？","start":387.43,"favorite":false,"stableId":"3c033bc2-a01b-43d8-a598-ad5135a81e28","sequenceId":80},{"id":81,"end":393.32,"note":"","text":"(江南) ええ　ウチの雑誌にも 何度か記事に登場したことが","start":389.14,"favorite":false,"stableId":"02186133-c8c2-44af-bb1f-16eb31acd34b","sequenceId":81},{"id":82,"end":395.82,"note":"","text":"さっき たまたま 下で見かけて――","start":393.46,"favorite":false,"stableId":"3ce762f2-b090-4ad2-ab59-364d0f8086fd","sequenceId":82},{"id":83,"end":397.85,"note":"","text":"すぐに誰か分かりました","start":395.96,"favorite":false,"stableId":"8eea548f-7e04-4ebc-9c8d-552835add77c","sequenceId":83},{"id":84,"end":398.97,"note":"","text":"(鹿谷) ふ～ん…","start":397.9,"favorite":false,"stableId":"ab471d25-fb46-49d7-9634-3b595a963ac1","sequenceId":84},{"id":85,"end":402.98,"note":"","text":"そんな特殊技能の持ち主には 見えないけどねえ","start":399.02,"favorite":false,"stableId":"cf91697e-cc75-4811-8a27-3d923c44f5f0","sequenceId":85},{"id":86,"end":406.21,"note":"","text":"たまに廊下で すれ違って 挨拶ぐらいは交わすんだが","start":403.03,"favorite":false,"stableId":"d5d96aba-aa2f-4c40-a011-e91e9d44a695","sequenceId":86},{"id":87,"end":408.78,"note":"","text":"１人住まいなんですか？ 彼女","start":406.64,"favorite":false,"stableId":"99b48dd6-c51e-4320-83d0-bd0601b43a21","sequenceId":87},{"id":88,"end":410.79,"note":"","text":"…のようだね","start":408.83,"favorite":false,"stableId":"7d197f06-5b8e-415d-88e9-c218c1ecaa8b","sequenceId":88},{"id":89,"end":415.78,"note":"","text":"んん～ ときどき 年上の男が通ってるようではあるが","start":411.31,"favorite":false,"stableId":"73bd45cc-61e5-48cb-b4bb-8b5c5a695a68","sequenceId":89},{"id":90,"end":417.2,"note":"","text":"父親には見えないから――","start":415.83,"favorite":false,"stableId":"c45c0cda-5e04-42da-ab47-2b6bfd92bf9f","sequenceId":90},{"id":91,"end":420.3,"note":"","text":"おおかた 愛人とか その辺なんだろう","start":417.25,"favorite":false,"stableId":"fdaa4a54-6f08-4a44-8a2b-6081dc878e66","sequenceId":91},{"id":92,"end":421.75,"note":"","text":"うん　なるほど","start":420.4,"favorite":false,"stableId":"2856e0db-3bb9-428a-a21a-6ac1d92cc134","sequenceId":92},{"id":93,"end":424.42,"note":"","text":"“時計屋敷の亡霊”の取材に――","start":421.8,"favorite":false,"stableId":"f5b5088a-e543-4bdc-8176-3a84103c8e22","sequenceId":93},{"id":94,"end":427.92,"note":"","text":"｢CHAOS｣編集部は 彼女を起用しようと決めたわけだ","start":424.47,"favorite":false,"stableId":"c300c973-1588-4899-a60b-adf8a417fbb2","sequenceId":94},{"id":95,"end":433.3,"note":"","text":"２週間後 今月の30日の夕方から 丸３日間","start":427.97,"favorite":false,"stableId":"3d91a34e-28b4-40f7-85b5-6181b1bf1901","sequenceId":95},{"id":96,"end":438.76,"note":"","text":"取材チームとＷ大の学生たちが 時計館の中に閉じこもって――","start":433.35,"favorite":false,"stableId":"fe041cb8-2429-499c-b52e-3f88016343f9","sequenceId":96},{"id":97,"end":444.04,"note":"","text":"光明寺美琴を霊媒役に 本格的な交霊会を開こうという","start":438.81,"favorite":false,"stableId":"6fbb8469-0669-48f4-a5e9-ec6b8e5347bb","sequenceId":97},{"id":98,"end":449.9,"note":"","text":"う～ん… 丸３日も その屋敷に 閉じこもるっていうのは――","start":444.39,"favorite":false,"stableId":"d9880a95-217a-464c-84a5-4ef46a65f2a3","sequenceId":98},{"id":99,"end":452.36,"note":"","text":"どうも いただけないなぁ","start":449.95,"favorite":false,"stableId":"2df50946-8521-498b-b4d4-1734444ebd9e","sequenceId":99},{"id":100,"end":456.57,"note":"","text":"何か悪い事件が 起きるかもしれないと？","start":452.41,"favorite":false,"stableId":"0f676b50-7753-42f4-bcab-890b8236e9c6","sequenceId":100},{"id":101,"end":458.83,"note":"","text":"いや　何の根拠もないことだから","start":456.62,"favorite":false,"stableId":"f074806a-f710-46da-a54c-cc1bb9dce952","sequenceId":101},{"id":102,"end":461.68,"note":"","text":"取り越し苦労と思ってくれれば いいんだけどね","start":458.88,"favorite":false,"stableId":"9f8d7787-d3e1-4808-9bbd-91b0b11132e5","sequenceId":102},{"id":103,"end":465.12,"note":"","text":"(江南) もし良かったら 鹿谷さんも一緒に…","start":462.99,"favorite":false,"stableId":"725065b2-77e7-4af7-833e-595e10cf9fe0","sequenceId":103},{"id":104,"end":468.81,"note":"","text":"ハハハッ… まあ できれば 同行したいところなんだけども","start":465.17,"favorite":false,"stableId":"829a4197-59e8-4b97-8de3-2805752a4ab4","sequenceId":104},{"id":105,"end":473.4,"note":"","text":"今 書いてる長編の 締め切りが10日後なんだよ","start":469.29,"favorite":false,"stableId":"a4adac12-49c3-4753-aebc-bf635580c64e","sequenceId":105},{"id":106,"end":479.14,"note":"","text":"まあ とにかく 気をつけるんだよ","start":476.67,"favorite":false,"stableId":"b85493e7-36b6-44ad-908a-799a86b2fed6","sequenceId":106},{"id":107,"end":482.98,"note":"","text":"僕もヒマがあれば １人でも訪ねてみるから","start":479.19,"favorite":false,"stableId":"c19a3f9a-156b-47a4-9086-162339bbf2d7","sequenceId":107},{"id":108,"end":487.1,"note":"","text":"いや 中村青司が設計した建物なら――","start":483.03,"favorite":false,"stableId":"32f13d02-6067-460c-bd00-e782ceec86e8","sequenceId":108},{"id":109,"end":489.61,"note":"","text":"この目で一度は見ておかないとね","start":487.15,"favorite":false,"stableId":"64dacb9b-31f6-4bf4-a7ae-808a50a825bf","sequenceId":109},{"id":110,"end":493.82,"note":"","text":"(江南)<この時点では 僕は まだ予想だにしていなかった>","start":489.66,"favorite":false,"stableId":"a7d7cda3-2213-4511-b7a9-e50e7a28a946","sequenceId":110},{"id":111,"end":496.99,"note":"","text":"<２週間後に訪れる その館において――>","start":493.87,"favorite":false,"stableId":"e66e2482-035a-4274-b2bd-85a60df35529","sequenceId":111},{"id":112,"end":498.49,"note":"","text":"<まさか 自分が――>","start":497.04,"favorite":false,"stableId":"f7b45cbb-2ac4-43ac-9fdc-c634eaa7b979","sequenceId":112},{"id":113,"end":503.64,"note":"","text":"<あのような途方もない悪夢を 経験することになろうとは>","start":498.54,"favorite":false,"stableId":"7423e6a7-7b6f-454a-849c-7844abb8dad1","sequenceId":113},{"id":114,"end":584.84,"note":"","text":"(江南) ンッ…","start":583.36,"favorite":false,"stableId":"fa5859fc-5f84-46f5-bd2e-da0b611c4fa1","sequenceId":114},{"id":115,"end":607.16,"note":"","text":"(樫 早紀子) ねえ この辺り 見覚えない？","start":603.3,"favorite":false,"stableId":"e3fe19e8-af70-48ed-bcf0-d9de90535571","sequenceId":115},{"id":116,"end":610.6,"note":"","text":"(河原崎潤一) あ～ さあ？","start":608.59,"favorite":false,"stableId":"e3e4dc39-1706-4fa4-9dcd-6284b6a07f0f","sequenceId":116},{"id":117,"end":613.08,"note":"","text":"何しろ 10年ぶりだからな","start":610.65,"favorite":false,"stableId":"3a9e8b08-3fd7-41b3-a10a-43d7dd6128ac","sequenceId":117},{"id":118,"end":615.44,"note":"","text":"(内海篤志) 前に来たことあるんだ？","start":613.22,"favorite":false,"stableId":"f77cac5f-5728-48f3-b86f-f86477d2d2d0","sequenceId":118},{"id":119,"end":617.36,"note":"","text":"(早紀子) はい　５年生の夏に――","start":615.49,"favorite":false,"stableId":"ae8a96ee-8818-4540-83e0-3c43ac85aa01","sequenceId":119},{"id":120,"end":620.99,"note":"","text":"中学受験の塾の合宿が この近くであって","start":617.41,"favorite":false,"stableId":"09065446-2702-4223-aba1-99b3492ce9da","sequenceId":120},{"id":121,"end":623.41,"note":"","text":"(河原崎) 俺と瓜生と早紀子","start":621.04,"favorite":false,"stableId":"deb6872b-0894-4cef-93c0-98ce500b105c","sequenceId":121},{"id":122,"end":624.95,"note":"","text":"あと 今日 来られなくなった――","start":623.46,"favorite":false,"stableId":"703420b5-b7db-45dd-98ab-81d3810b5786","sequenceId":122},{"id":123,"end":628.26,"note":"","text":"福西の４人が その塾で 一緒だったんです","start":625,"favorite":false,"stableId":"3b08625b-2a3d-4e0f-afc5-636016dca721","sequenceId":123},{"id":124,"end":631.72,"note":"","text":"(渡辺涼介) あっ！ あれが時計塔ですね","start":628.7,"favorite":false,"stableId":"13f109f3-3614-4ca3-9377-f505cd0695ce","sequenceId":124},{"id":125,"end":634.92,"note":"","text":"(瓜生民佐男) うん　文字盤は――","start":632.28,"favorite":false,"stableId":"fd35cb08-0857-4f40-b14b-1897dc192ba5","sequenceId":125},{"id":126,"end":637.59,"note":"","text":"裏庭のほうを 向いた側にだけあって――","start":634.97,"favorite":false,"stableId":"3b0a4219-2004-48cb-8e22-1cb87776b2f3","sequenceId":126},{"id":127,"end":640.38,"note":"","text":"以前' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || 'は ちゃんと 針があったんだけど――","start":637.64,"favorite":false,"stableId":"fe56b293-a404-4dfc-8d90-cd008c9d979e","sequenceId":127},{"id":128,"end":643.39,"note":"","text":"今は針が なくなっているそうだ","start":640.43,"favorite":false,"stableId":"bd8e01e2-2940-476f-b563-fa3338ed6253","sequenceId":128},{"id":129,"end":646.78,"note":"","text":"(新見こずえ) へえ～ 針のない時計塔","start":643.44,"favorite":false,"stableId":"c54bd7ad-a2cd-4d46-a9de-b2b529d978ab","sequenceId":129},{"id":130,"end":649.35,"note":"","text":"(瓜生) 古峨倫典氏が――","start":647.63,"favorite":false,"stableId":"883e66f3-d8d6-489e-9610-90c574d6f044","sequenceId":130},{"id":131,"end":650.98,"note":"","text":"古峨精計社の 会長を辞めて――","start":649.4,"favorite":false,"stableId":"9eca4d1c-375a-47a5-8e89-fb9e83c863f6","sequenceId":131},{"id":132,"end":653.23,"note":"","text":"この土地に 屋敷を建てたのが15年前","start":651.03,"favorite":false,"stableId":"6bb4eccb-46b8-4d48-82fd-6db1cfdeb324","sequenceId":132},{"id":133,"end":656.21,"note":"","text":"１９７４年の 夏でしたよね？","start":653.28,"favorite":false,"stableId":"0467e4f0-ee5f-44d8-a12c-73a766dcc5b2","sequenceId":133},{"id":134,"end":658.73,"note":"","text":"そのときには こっちの洋館や時計塔は","start":656.56,"favorite":false,"stableId":"7a4b9722-e15d-4675-afa6-2ee745715fcf","sequenceId":134},{"id":135,"end":660.32,"note":"","text":"まだ 建てられていなかった","start":658.78,"favorite":false,"stableId":"91520de0-cd3f-4988-a4e5-4b821796e725","sequenceId":135},{"id":136,"end":661.24,"note":"","text":"それから５年後――","start":660.37,"favorite":false,"stableId":"336bc8e7-d966-4ed6-a60c-24df0c968601","sequenceId":136},{"id":137,"end":663.61,"note":"","text":"１９７９年に 増築が始まって――","start":661.29,"favorite":false,"stableId":"6b89c1ca-400b-4cda-aa72-6fa3ac652572","sequenceId":137},{"id":138,"end":667.87,"note":"","text":"翌80年の夏に 時計館は 今の形になったようです","start":663.66,"favorite":false,"stableId":"1f5502b5-db5e-4496-b03c-2bdc0718c94d","sequenceId":138},{"id":139,"end":672.29,"note":"","text":"残念ながら その直後に 古峨倫典氏は急逝してしまった","start":667.92,"favorite":false,"stableId":"986fdb97-eed9-453e-9ad7-df55bfa936b4","sequenceId":139},{"id":140,"end":674.12,"note":"","text":"(江南) それと前後して――","start":672.34,"favorite":false,"stableId":"3ab57718-37a3-4417-b3b2-a67b4d9251f1","sequenceId":140},{"id":141,"end":677.34,"note":"","text":"何人もの人が 相次いで亡くなったと聞いてるけど","start":674.17,"favorite":false,"stableId":"3f7bc9b3-d91a-44d0-b6a0-dd572738f0c5","sequenceId":141},{"id":142,"end":680.51,"note":"","text":"(瓜生) そう その中に古峨倫典氏の娘もいた","start":677.39,"favorite":false,"stableId":"7a955af8-baee-4d21-a821-c9c9d34c142d","sequenceId":142},{"id":143,"end":684.57,"note":"","text":"その少女の亡霊が 現れるって話ですよね","start":680.56,"favorite":false,"stableId":"7b989254-ee6a-4cbc-9e9a-9797de2e5174","sequenceId":143},{"id":144,"end":700.17,"note":"","text":"(伊波紗世子) こちらへ どうぞ","start":698.27,"favorite":false,"stableId":"442909cd-ed3c-40f3-b390-9191c445b790","sequenceId":144},{"id":145,"end":708.7,"note":"","text":"(伊波) 失礼ですが 皆さんのお名前を確認できますか？","start":704.02,"favorite":false,"stableId":"d5206b7f-3896-46c9-b8b2-a60f04f2e416","sequenceId":145},{"id":146,"end":710.76,"note":"","text":"(小早川茂郎) ええ　そりゃ もちろん","start":708.75,"favorite":false,"stableId":"10832661-7166-411f-9b23-8a691b7b5156","sequenceId":146},{"id":147,"end":712.45,"note":"","text":"(小早川) リストは 届いてますよね？","start":710.99,"favorite":false,"stableId":"3ec40b30-e948-470c-bd97-c483a769d965","sequenceId":147},{"id":148,"end":713.85,"note":"","text":"(伊波) はい","start":712.5,"favorite":false,"stableId":"4f055ddf-1f2a-4546-b955-4988529c7fd3","sequenceId":148},{"id":149,"end":718.52,"note":"","text":"こっちの５人が Ｗ大の学生諸君です","start":714.7,"favorite":false,"stableId":"847a5888-a701-40a0-8f38-a53cf634dfcc","sequenceId":149},{"id":150,"end":720.65,"note":"","text":"順番に","start":719.33,"favorite":false,"stableId":"ba180e5d-f940-4d7b-8f7d-45289b4a8b4e","sequenceId":150},{"id":151,"end":723.52,"note":"","text":"瓜生民佐男くん","start":721.79,"favorite":false,"stableId":"3b23dfc3-6e9f-4b27-aa39-bea4729ed2f4","sequenceId":151},{"id":152,"end":728.15,"note":"","text":"河原崎潤一くん","start":726,"favorite":false,"stableId":"4d64ce5d-9031-43a0-a3b5-20d47f208eda","sequenceId":152},{"id":153,"end":732.41,"note":"","text":"樫 早紀子さん","start":730.34,"favorite":false,"stableId":"10066da4-9d11-48ff-b143-87f71f7db07b","sequenceId":153},{"id":154,"end":736.75,"note":"","text":"渡辺涼介くん","start":734.76,"favorite":false,"stableId":"659b6bb0-d93b-427a-85f0-5533f72d68f6","sequenceId":154},{"id":155,"end":741.17,"note":"","text":"(伊波) そちらが福西さん？","start":738.93,"favorite":false,"stableId":"7657fd2f-f348-4700-85e3-0451c18085ec","sequenceId":155},{"id":156,"end":744.28,"note":"","text":"(内海) いえ","start":743.06,"favorite":false,"stableId":"e6b31535-1973-4cb1-b3b2-d547aa4a7a37","sequenceId":156},{"id":157,"end":747.95,"note":"","text":"俺は 稀譚社のカメラマンで 内海篤志といいます","start":744.33,"favorite":false,"stableId":"9e44b5ce-b8c4-4c2a-bfcd-ea966fe20706","sequenceId":157},{"id":158,"end":750.83,"note":"","text":"(こずえ) あっ 福西先輩 あの 高校生の従兄弟に――","start":748,"favorite":false,"stableId":"b5eceee3-01fe-4d83-bbf8-18d0d65da356","sequenceId":158},{"id":159,"end":753.25,"note":"","text":"急な ご不幸があって 来られなくなって――","start":750.88,"favorite":false,"stableId":"a8caf749-91f1-49d6-bf49-4d0f65f4e4c8","sequenceId":159},{"id":160,"end":755.04,"note":"","text":"ピンチヒッターで あたしが","start":753.3,"favorite":false,"stableId":"a46b453a-7084-49ff-ad48-40a36734a7d3","sequenceId":160},{"id":161,"end":757.39,"note":"","text":"新見こずえです","start":755.09,"favorite":false,"stableId":"edb07346-1a6c-4417-bf4c-a2eeef26fc6f","sequenceId":161},{"id":162,"end":759.25,"note":"","text":"(伊波) 分かりました","start":757.49,"favorite":false,"stableId":"371827c2-1e80-4ff1-90fa-a536462ecc97","sequenceId":162},{"id":163,"end":762.4,"note":"","text":"新見こずえさんですね","start":759.3,"favorite":false,"stableId":"78c938aa-c2c4-49f1-b20a-4835b7a73a85","sequenceId":163},{"id":164,"end":769.3,"note":"","text":"(小早川) こっちの若いのが ウチの編集部員の江南孝明です","start":764.96,"favorite":false,"stableId":"dc10c8cc-8f33-4bbd-9c0d-4e6a9920d5d7","sequenceId":164},{"id":165,"end":771.57,"note":"","text":"よろしくお願いいたします","start":769.35,"favorite":false,"stableId":"82ed3fa9-e276-488e-96b7-cbec83ec47ac","sequenceId":165},{"id":166,"end":775.27,"note":"","text":"(伊波) 最初に わたくしのほうから――","start":773.22,"favorite":false,"stableId":"2ff5a49e-14d4-4816-bc7a-b5fb0bd9f6c0","sequenceId":166},{"id":167,"end":777.54,"note":"","text":"いくつか ご注意を","start":775.32,"favorite":false,"stableId":"e4ecd7d9-e11f-488c-b5f9-9b107613b8f1","sequenceId":167},{"id":168,"end":783.63,"note":"","text":"まず 今日から皆さんが お入りになる当家の旧館には――","start":777.89,"favorite":false,"stableId":"3e45275a-cc95-4c34-900a-da626805c806","sequenceId":168},{"id":169,"end":789.01,"note":"","text":"先代の主人 古峨倫典が残した 時計のコレクションがございます","start":783.68,"favorite":false,"stableId":"6acffedd-1ee9-431c-954d-82fba9b0685c","sequenceId":169},{"id":170,"end":791.91,"note":"","text":"非常に貴重な品ばかりですので――","start":789.56,"favorite":false,"stableId":"91df18d2-9506-4c58-a0b2-80374e87c7b0","sequenceId":170},{"id":171,"end":795.87,"note":"","text":"決して お触れにならないように お願いいたします","start":791.96,"favorite":false,"stableId":"c56afd23-8867-417a-a1ee-711fd6749920","sequenceId":171},{"id":172,"end":799.54,"note":"","text":"そのほかのものは ご自由にお使いになって結構です","start":795.92,"favorite":false,"stableId":"8c1251d3-8a5a-4355-84f0-87dee1763e4f","sequenceId":172},{"id":173,"end":804.56,"note":"","text":"ただ 水道の水はサビがひどくて 飲用には適しません","start":799.59,"favorite":false,"stableId":"f8f7671c-3ec9-4a3d-9be8-7d9b31563e75","sequenceId":173},{"id":174,"end":808.13,"note":"","text":"飲み水は 別に持ち込んでおく手はずです","start":805,"favorite":false,"stableId":"b3c61da1-2452-4a68-ab00-5abb29cc8b9c","sequenceId":174},{"id":175,"end":809.89,"note":"","text":"ポリタンク 届いてますよね？","start":808.18,"favorite":false,"stableId":"e6145ecd-ed54-4cc1-850a-35e7b1f3e1b6","sequenceId":175},{"id":176,"end":812.68,"note":"","text":"(伊波) はい 水は もう入れておりますので","start":809.94,"favorite":false,"stableId":"e67ba7ae-436d-403b-9634-32007b6b9ca4","sequenceId":176},{"id":177,"end":815.11,"note":"","text":"あっ… 恐縮です","start":812.73,"favorite":false,"stableId":"199899bd-cbd8-4d0e-8ff2-8325d8157d79","sequenceId":177},{"id":178,"end":818.94,"note":"","text":"あと もうひとつ","start":816.76,"favorite":false,"stableId":"927a206e-27a9-4b54-9675-e5232ac2f503","sequenceId":178},{"id":179,"end":821.52,"note":"","text":"(伊波) 旧館のいちばん奥に――","start":818.99,"favorite":false,"stableId":"3ca48326-9eb0-40b3-9338-e47c144b8d2f","sequenceId":179},{"id":180,"end":824.98,"note":"","text":"鍵のかかった一室が ありますが――","start":821.57,"favorite":false,"stableId":"76f29482-1584-4388-8032-0edb5c9acd09","sequenceId":180},{"id":181,"end":826.11,"note":"","text":"ここには 決して――","start":825.03,"favorite":false,"stableId":"211809b9-7370-4bc8-9cc2-a5118f9850c3","sequenceId":181},{"id":182,"end":829.3,"note":"","text":"立ち入らないように していただきたいのです","start":826.16,"favorite":false,"stableId":"658e493a-59ba-438a-a2c1-376f4ed92e68","sequenceId":182},{"id":183,"end":834.03,"note":"","text":"前に少し伺った 振子の部屋ですよね？","start":830.06,"favorite":false,"stableId":"f1d667c2-66fa-49f1-be42-c47acf8dbfa0","sequenceId":183},{"id":184,"end":836.54,"note":"","text":"でも どうして 入っちゃいけないんですか？","start":834.08,"favorite":false,"stableId":"be226897-d395-4cf4-82c1-a133febda688","sequenceId":184},{"id":185,"end":838.68,"note":"","text":"先代のご遺言です","start":836.59,"favorite":false,"stableId":"0da62c14-3bdc-444e-8154-55edd299fa2d","sequenceId":185},{"id":186,"end":843.48,"note":"","text":"あの部屋は お嬢さまのお部屋です","start":839.32,"favorite":false,"stableId":"68308da4-9e2c-4af1-b542-10d0bd48fa5e","sequenceId":186},{"id":187,"end":846.59,"note":"","text":"(伊波) 10年前に亡くなった――","start":844.08,"favorite":false,"stableId":"88b3e3ff-f5af-41ee-b16a-6e882f57416c","sequenceId":187},{"id":188,"end":849.05,"note":"","text":"お嬢さまの","start":846.64,"favorite":false,"stableId":"c9859888-29d4-4089-9e4d-ac5509d3d6fd","sequenceId":188},{"id":189,"end":850.98,"note":"","text":"(小早川) ほかに何か？","start":849.1,"favorite":false,"stableId":"315d4e57-0adf-4192-8958-832ef15efa0b","sequenceId":189},{"id":190,"end":855.2,"note":"","text":"では 私のほうから","start":853,"favorite":false,"stableId":"ff922ec7-ae55-4574-8e60-87f6a319e8cc","sequenceId":190},{"id":191,"end":862.81,"note":"","text":"光明寺さん 例の件について お話し願え…","start":860.22,"favorite":false,"stableId":"9493b077-8b7c-46ba-a232-47331c0810de","sequenceId":191},{"id":192,"end":864.79,"note":"","text":"(光明寺美琴) これから――","start":862.86,"favorite":false,"stableId":"c42ba987-370a-487a-a8eb-37c746a2f8de","sequenceId":192},{"id":193,"end":869.34,"note":"","text":"私たちが行おうとしていることは――","start":865.47,"favorite":false,"stableId":"ec67d8b7-d784-4563-917c-4c4d4c2c6f59","sequenceId":193},{"id":194,"end":874.72,"note":"","text":"この家に 住み着いているとウワサされる――","start":871.15,"favorite":false,"stableId":"a3111e4e-5f96-48c2-bbf6-be5235fbc1bc","sequenceId":194},{"id":195,"end":878.55,"note":"","text":"死者の霊魂とのコンタクトです","start":874.9,"favorite":false,"stableId":"71f1b902-1002-4233-9e0a-8820221f01b1","sequenceId":195},{"id":196,"end":885.23,"note":"","text":"霊は とてもナーバスな性質を 持っていて――","start":879.28,"favorite":false,"stableId":"75ad53f6-d3e4-44e7-82e7-39ccbfad5bb6","sequenceId":196},{"id":197,"end":888.35,"note":"","text":"不純物を非常に嫌います","start":885.29,"favorite":false,"stableId":"77c59aff-1e45-43d3-83c2-bc413fa6a803","sequenceId":197},{"id":198,"end":892.3,"note":"","text":"ですから 私たちは――","start":890,"favorite":false,"stableId":"a565fb59-f5d1-4b69-ae83-41ace35576b5","sequenceId":198},{"id":199,"end":899.45,"note":"","text":"なるべ～く純粋な状態に 保たなければなりません","start":892.35,"favorite":false,"stableId":"64c29aea-67b3-4d57-8d65-aaf36e50bd70","sequenceId":199},{"id":200,"end":912.17,"note":"","text":"こちらは “霊衣”と呼ばれる衣装です","start":908.85,"favorite":false,"stableId":"9c2342ad-6471-42b9-b030-810c5c8f7956","sequenceId":200},{"id":201,"end":918.62,"note":"","text":"これから皆さんには この衣装に 着替えていただかねばなりません","start":912.9,"favorite":false,"stableId":"31d1b000-0b69-450c-84c3-eb1f87f83cda","sequenceId":201},{"id":202,"end":920.6,"note":"","text":"よろしいですね？","start":918.67,"favorite":false,"stableId":"32f82a41-4f38-40f5-9489-3dafaee2e968","sequenceId":202},{"id":203,"end":924.67,"note":"","text":"(美琴) 今 身に着けている物は――","start":921.61,"favorite":false,"stableId":"b5b54008-5340-4fb1-b870-28314dde84a1","sequenceId":203},{"id":204,"end":929.65,"note":"","text":"下着以外は 全て取るようにしてください","start":924.72,"favorite":false,"stableId":"d2f8f489-5e5b-4dc4-a1dc-bcf24a436ae4","sequenceId":204},{"id":205,"end":937.39,"note":"","text":"ネックレスやイヤリング 指輪 腕時計といったものも全てです","start":930.5,"favorite":false,"stableId":"63bda478-47eb-4a13-be29-b0def1702be7","sequenceId":205},{"id":206,"end":940.77,"note":"","text":"そのほか 不必要な荷物は――","start":937.44,"favorite":false,"stableId":"58625fa3-139d-4ddd-887a-185220d65c12","sequenceId":206},{"id":207,"end":944.95,"note":"","text":"一切 持って入らないよう お願いします","start":940.82,"favorite":false,"stableId":"5f4fddcb-9d9c-4c0b-af7c-6cfa3e3a2e47","sequenceId":207},{"id":208,"end":957.2,"note":"","text":"(小早川) 旧館の前まで 食料 運んどいたから","start":954.98,"favorite":false,"stableId":"8ee7d6f2-9bf8-4593-9a9f-d1a96e1a8bb2","sequenceId":208},{"id":209,"end":958.33,"note":"","text":"(江南) すみません","start":957.25,"favorite":false,"stableId":"6d770818-bbb4-4a75-8641-d1c31e0cf971","sequenceId":209},{"id":210,"end":960.58,"note":"","text":"(内海) カメラが お許しが出て助かったよ","start":958.38,"favorite":false,"stableId":"4862120b-fdcd-4ba4-8c0c-33b6e6bd4b3b","sequenceId":210},{"id":211,"end":962.51,"note":"","text":"(小早川) 取材だからな","start":960.63,"favorite":false,"stableId":"17ae269d-c1e4-4968-ba87-48355babab3d","sequenceId":211},{"id":212,"end":965.75,"note":"","text":"メモや最小限の筆記具も 大丈夫だそうだ","start":962.7,"favorite":false,"stableId":"79d80fb9-3c1e-44dd-89b6-17cb3694e91d","sequenceId":212},{"id":213,"end":967.89,"note":"","text":"(河原崎･瓜生) ありがとうございます","start":965.8,"favorite":false,"stableId":"e97e8473-d29a-42bd-a239-3cdbee7d520e","sequenceId":213},{"id":214,"end":971.06,"note":"","text":"(河原崎) それにしても 民佐男","start":968.41,"favorite":false,"stableId":"694668d5-b32b-4557-92ca-1dadbf30657f","sequenceId":214},{"id":215,"end":974.55,"note":"","text":"あの伊波っておばさん","start":972.08,"favorite":false,"stableId":"693c0f1d-67c6-4f50-8012-4cde690d8fc5","sequenceId":215},{"id":216,"end":977.76,"note":"","text":"前に来たときとは えらくサービスぶりが違うよな","start":974.6,"favorite":false,"stableId":"7136fa6a-3657-46e9-9b33-20840a45e515","sequenceId":216},{"id":217,"end":978.93,"note":"","text":"(瓜生) フフッ…","start":977.81,"favorite":false,"stableId":"8d6479ee-5406-49a4-b676-d264c9808567","sequenceId":217},{"id":218,"end":981.32,"note":"","text":"(江南) 前にも来たことあるんだ？","start":978.98,"favorite":false,"stableId":"612aa509-5b54-457e-9375-584f934a4c85","sequenceId":218},{"id":219,"end":986.1,"note":"","text":"(瓜生) ええ 実は 渡辺の実家が鎌倉で――","start":981.63,"favorite":false,"stableId":"e1ffc74c-6041-43f0-aeb6-9f36ca06102d","sequenceId":219},{"id":220,"end":990.29,"note":"","text":"時計屋敷の亡霊のウワサも 彼から聞いたんですよ","start":986.15,"favorite":false,"stableId":"c2e3c909-b189-4881-92c9-c2e384f23dd6","sequenceId":220},{"id":221,"end":993.23,"note":"","text":"(渡辺) 去年の秋 瓜生先輩たちと ここへ来て――","start":990.39,"favorite":false,"stableId":"c743cf79-72bc-456c-a038-5c9f6f00aefd","sequenceId":221},{"id":222,"end":996.53,"note":"","text":"取材させてほしいって お願いしたんですけど…","start":993.28,"favorite":false,"stableId":"a1e73246-0486-419d-b02f-7ebfbe4f9b1c","sequenceId":222},{"id":223,"end":997.99,"note":"","text":"(河原崎) あのおばさんに――","start":996.58,"favorite":false,"stableId":"2b2784e0-e6ff-4cd1-9c32-dbfcbd56ef4c","sequenceId":223},{"id":224,"end":1001.76,"note":"","text":"にべもなく 門前払いされたってわけですよ","start":998.04,"favorite":false,"stableId":"988e08c0-f92c-47bd-a6c8-332e591c41d9","sequenceId":224},{"id":225,"end":1003.59,"note":"","text":"(こずえ) あっ！","start":1002.11,"favorite":false,"stableId":"c5600eeb-352e-42c9-99ee-30ff1219187c","sequenceId":225},{"id":226,"end":1011.81,"note":"","text":"(古峨由季弥) 姉さん…","start":1010.08,"favorite":false,"stableId":"15b7131c-8c32-4dfe-8618-884c0a07fa28","sequenceId":226},{"id":227,"end":1016.11,"note":"","text":"(江南) 君は？","start":1014.41,"favorite":false,"stableId":"e8c4227d-81c9-4a52-805f-9938f4c5ae9e","sequenceId":227},{"id":228,"end":1020.57,"note":"","text":"(由季弥) 姉さんは どこ？","start":1018.46,"favorite":false,"stableId":"fe8fa91f-64a3-447f-aea4-cf328af3d2ee","sequenceId":228},{"id":229,"end":1031.83,"note":"","text":"姉さんは どこ？","start":1029.76,"favorite":false,"stableId":"68ad7a65-cad2-410a-b529-523b1bbb233c","sequenceId":229},{"id":230,"end":1039.46,"note":"","text":"姉さんは どこ？","start":1037.48,"favorite":false,"stableId":"9059e596-ee66-464c-8425-196bbb814b11","sequenceId":230},{"id":231,"end":1041.59,"note":"","text":"(伊波) 由季弥さま","start":1039.94,"favorite":false,"stableId":"b4f6ce4f-5d61-4527-bc5a-cfbb161f70ed","sequenceId":231},{"id":232,"end":1048.39,"note":"","text":"どうなさったのですか？ 由季弥さま","start":1044.65,"favorite":false,"stableId":"1670e617-c53a-43cf-b6aa-cbf73e6010ef","sequenceId":232},{"id":233,"end":1051.73,"note":"","text":"(由季弥) この人たち 誰？","start":1048.99,"favorite":false,"stableId":"6acf73e0-29a4-4618-b429-34998d2efc88","sequenceId":233},{"id":234,"end":1057.15,"note":"","text":"(伊波) お客さまです 前に お話ししましたでしょう","start":1052.79,"favorite":false,"stableId":"57773142-38c5-4a4e-8c1a-4c52adec8ee8","sequenceId":234},{"id":235,"end":1061.64,"note":"","text":"姉さんを いじめに来たんじゃないだろうね？","start":1058.25,"favorite":false,"stableId":"8da836b3-567d-4507-a457-4b0c095925ca","sequenceId":235},{"id":236,"end":1063.74,"note":"","text":"だったら 僕が やっつけてやる","start":1061.69,"favorite":false,"stableId":"ea31f93e-3778-4a92-851e-0bfafbddd9d5","sequenceId":236},{"id":237,"end":1066.95,"note":"","text":"姉さんをいじめるヤツは――","start":1064.88,"favorite":false,"stableId":"b7a7eabc-e22c-4bc4-8dc3-212c2bc41265","sequenceId":237},{"id":238,"end":1070.69,"note":"","text":"僕が みんな みんな 殺してやるんだから","start":1067.05,"favorite":false,"stableId":"cfbe9143-f3be-4639-8030-56094b3a4050","sequenceId":238},{"id":239,"end":1072.36,"note":"","text":"違います","start":1070.74,"favorite":false,"stableId":"245684a8-7492-4506-937c-deed65d157d4","sequenceId":239},{"id":240,"end":1075.33,"note":"","text":"誰も お姉さまを いじめたりは いたしません","start":1072.41,"favorite":false,"stableId":"6ff89f3d-4508-4e13-b3d8-f2193dbcb77d","sequenceId":240},{"id":241,"end":1077.9,"note":"","text":"ですから お部屋へお戻りください","start":1075.43,"favorite":false,"stableId":"851fcd8e-f65e-4468-aa98-f1a88c2c6945","sequenceId":241},{"id":242,"end":1078.82,"note":"","text":"田所さん","start":1077.95,"favorite":false,"stableId":"1c2cc4ac-a4e3-46a7-ae9b-4fa8ea5f4df2","sequenceId":242},{"id":243,"end":1080.2,"note":"","text":"(田所嘉明) はい (伊波) 由季弥さまを――","start":1078.87,"favorite":false,"stableId":"0201590f-539d-4dd9-a9e6-b01717ce4b85","sequenceId":243},{"id":244,"end":1081.7,"note":"","text":"塔のお部屋へ お連れしてください","start":1080.25,"favorite":false,"stableId":"74b43500-38bf-4873-a25d-67be08ee67d9","sequenceId":244},{"id":245,"end":1082.7,"note":"","text":"(田所) かしこまりました","start":1081.75,"favorite":false,"stableId":"bc467d8b-26ea-48fd-a99d-43a1519254e8","sequenceId":245},{"id":246,"end":1085.13,"note":"","text":"さあ まいりましょう","start":1082.75,"favorite":false,"stableId":"d0cbdce3-45d7-4462-b215-576354b8e97c","sequenceId":246},{"id":247,"end":1094.44,"note":"","text":"(ドアの閉まる音)","start":1092.91,"favorite":false,"stableId":"aa0ea67b-ca71-4b98-af1e-e771f3b0c334","sequenceId":247},{"id":248,"end":1098.82,"note":"","text":"(早紀子) もしかして あの子…","start":1095.62,"favorite":false,"stableId":"87051e39-fcf2-4685-a1a5-32ed3b5dfbb3","sequenceId":248},{"id":249,"end":1114.37,"note":"","text":"(ドアの閉まる音)","start":1110.89,"favorite":false,"stableId":"6665f23b-be93-429d-935a-2169c9c8cd81","sequenceId":249},{"id":250,"end":1127.58,"note":"","text":"(伊波) この扉より向こうが――","start":1125.57,"favorite":false,"stableId":"4d7728ca-fefe-4832-a923-e0fd5f584f3e","sequenceId":250},{"id":251,"end":1129.97,"note":"","text":"旧館になります","start":1127.63,"favorite":false,"stableId":"aedf1ba6-c4ab-49c8-be29-2e052376a164","sequenceId":251},{"id":252,"end":1133.08,"note":"","text":"(鍵を開けようとする音)","start":1131.16,"favorite":false,"stableId":"12615249-4c88-41e7-9d4b-f4c9acbab033","sequenceId":252},{"id":253,"end":1135.23,"note":"","text":"(野之宮泰斉) お待ちなさい","start":1133.13,"favorite":false,"stableId":"fe1a4316-e098-44de-9d25-a783c54eb6b2","sequenceId":253},{"id":254,"end":1142.3,"note":"","text":"(伊波) 野之宮さん　いけません","start":1139.21,"favorite":false,"stableId":"87ce6921-5bfe-4512-9783-9d6bb0622dea","sequenceId":254},{"id":255,"end":1143.64,"n' WHERE "id" = '9ca51cd4-28eb-4034-ac60-51fd60f0f625' AND json_valid("content_payload") = 0;

UPDATE "materials" SET "content_payload" = "content_payload" || 'ote":"","text":"お戻りください","start":1142.35,"favorite":false,"stableId":"8d03aed4-45dd-4fca-8177-09ff63e59552","sequenceId":255},{"id":256,"end":1146.1,"note":"","text":"(野之宮) 不吉な兆しが見える","start":1143.69,"favorite":false,"stableId":"71d9fa91-bbc2-44ff-99bf-5bc2e3d0dc51","sequenceId":256},{"id":257,"end":1148.77,"note":"","text":"死んだ者どもに 取り殺されたくなければ――","start":1146.15,"favorite":false,"stableId":"8a888f39-598a-4c25-8ec1-5646bc9d4947","sequenceId":257},{"id":258,"end":1150.81,"note":"","text":"この屋敷から出ていくことじゃ！","start":1148.82,"favorite":false,"stableId":"0c21613b-2c99-4f2c-a7dd-587a9aced493","sequenceId":258},{"id":259,"end":1151.85,"note":"","text":"(伊波) その件については――","start":1150.86,"favorite":false,"stableId":"3fbbeed2-2977-478e-8ab0-7c7970fdb80c","sequenceId":259},{"id":260,"end":1154.19,"note":"","text":"わたくしのほうで 皆さんに お伝えしときますから","start":1151.9,"favorite":false,"stableId":"db7f6b48-219d-4dc1-87b5-dea9eb67050a","sequenceId":260},{"id":261,"end":1158.02,"note":"","text":"(野之宮) わしは夢を見たぞ 恐ろしい夢じゃった！","start":1154.24,"favorite":false,"stableId":"9b6c7e4f-bccd-4e88-9d54-cd25647c672d","sequenceId":261},{"id":262,"end":1160.74,"note":"","text":"また人が死ぬ！ 家が崩れるぞ！","start":1158.07,"favorite":false,"stableId":"41ab6f9f-79d1-4f10-818b-76f8f83054b7","sequenceId":262},{"id":263,"end":1161.82,"note":"","text":"(伊波) お戻りください (野之宮) 破滅じゃ！","start":1160.79,"favorite":false,"stableId":"d394a655-b42e-42e6-a005-4b14d8248e12","sequenceId":263},{"id":264,"end":1163.99,"note":"","text":"(伊波) 野之宮さん お戻りください","start":1161.87,"favorite":false,"stableId":"f8c7b90d-4242-44c0-8ecd-22a9ffd8de2b","sequenceId":264},{"id":265,"end":1166.42,"note":"","text":"さあ さあ…","start":1164.04,"favorite":false,"stableId":"fed5a086-5ca1-4f32-9b7e-71c4b31de582","sequenceId":265},{"id":266,"end":1169.74,"note":"","text":"(小早川) 誰ですか？ 今の人","start":1167.36,"favorite":false,"stableId":"b2148aef-a938-4be7-89ec-52599d1b6adb","sequenceId":266},{"id":267,"end":1174,"note":"","text":"(伊波) 野之宮泰斉さんという 占い師の先生です","start":1169.79,"favorite":false,"stableId":"0a3aeea4-0cc1-4075-a363-095047480cf0","sequenceId":267},{"id":268,"end":1176.77,"note":"","text":"どうか お気になさらないでください","start":1174.05,"favorite":false,"stableId":"589186c7-79af-44d7-a65b-6f9f95dd8787","sequenceId":268},{"id":269,"end":1185.34,"note":"","text":"くれぐれも皆さま","start":1183.12,"favorite":false,"stableId":"8de38fc2-67fc-4fc1-b764-922d703bffb1","sequenceId":269},{"id":270,"end":1189.66,"note":"","text":"先に申しましたことは 守っていただきますように","start":1185.39,"favorite":false,"stableId":"af05537c-8bed-49c3-bec9-aa96e0264ece","sequenceId":270},{"id":271,"end":1198.37,"note":"","text":"(小早川) では 72時間後 ８月２日の この時刻まで","start":1192.72,"favorite":false,"stableId":"8f123387-38b9-4e17-bc4a-4cc4c0674951","sequenceId":271},{"id":272,"end":1200.5,"note":"","text":"(扉の閉まる音)","start":1198.52,"favorite":false,"stableId":"a3fa7008-b804-4754-aeb7-d072404e65dd","sequenceId":272},{"id":273,"end":1201.96,"note":"","text":"(鍵の閉まる音)","start":1200.55,"favorite":false,"stableId":"181ccfea-557b-4ba7-9bc0-3ecd2490d2ca","sequenceId":273},{"id":274,"end":1208.88,"note":"","text":"この向こうが 時計館の旧館","start":1204.35,"favorite":false,"stableId":"29ca2d93-2ece-4830-b058-bef1e114341b","sequenceId":274},{"id":275,"end":1213.93,"note":"","text":"(時鐘音)","start":1209.11,"favorite":false,"stableId":"178b78f5-8636-4284-8592-c1820b87bf15","sequenceId":275},{"id":276,"end":1222.73,"note":"","text":"(車のドアの閉まる音) (鹿谷) ハァ…","start":1219.54,"favorite":false,"stableId":"8da5e3e1-2cb4-47d1-bf54-6f24d458fdc9","sequenceId":276},{"id":277,"end":1225.63,"note":"","text":"どうしちゃったのかな？","start":1223.29,"favorite":false,"stableId":"98d54af0-f5a7-4ddb-9db5-9dbff59258ef","sequenceId":277},{"id":278,"end":1226.86,"note":"","text":"ンッ！","start":1225.68,"favorite":false,"stableId":"c1c8126d-3e5d-4c1c-9be4-6186ee3155ea","sequenceId":278},{"id":279,"end":1232.45,"note":"","text":"う～ん…","start":1229,"favorite":false,"stableId":"c99ee63f-04d2-4ed6-bbdb-e21deb38a97b","sequenceId":279},{"id":280,"end":1238.54,"note":"","text":"(福西涼太) あの…","start":1236.85,"favorite":false,"stableId":"b6b4d666-9e03-40c9-8f3a-6c879893f3b4","sequenceId":280},{"id":281,"end":1242.54,"note":"","text":"(福西) トラブルですか？","start":1240.6,"favorite":false,"stableId":"97c385fe-77a5-44b4-894e-5fdf6af79eab","sequenceId":281},{"id":282,"end":1245.78,"note":"","text":"(エンジンが かからない)","start":1244.1,"favorite":false,"stableId":"1203bf8d-8d44-4eed-9a86-1c5cc13e29f8","sequenceId":282},{"id":283,"end":1246.99,"note":"","text":"(エンジン音)","start":1245.83,"favorite":false,"stableId":"3c5827a6-4918-4005-88ca-c24a2c0e071f","sequenceId":283},{"id":284,"end":1249.95,"note":"","text":"(鹿谷) あ～ かかった かかった！","start":1247.04,"favorite":false,"stableId":"fc163969-87ee-4c25-acae-ac06c7d10ea0","sequenceId":284},{"id":285,"end":1251.87,"note":"","text":"ありがとう　助かりましたよ！","start":1250,"favorite":false,"stableId":"41348fb3-c507-47b6-a138-f01dfdec9407","sequenceId":285},{"id":286,"end":1253.2,"note":"","text":"(福西) いえ","start":1251.92,"favorite":false,"stableId":"963febba-375f-411b-a88b-1fd64806b8ea","sequenceId":286},{"id":287,"end":1255.76,"note":"","text":"(鹿谷) あ～ 良かった","start":1253.25,"favorite":false,"stableId":"6bb8b101-4a59-4df1-80c1-eabed2ab5ef3","sequenceId":287},{"id":288,"end":1259.46,"note":"","text":"(福西) これから どちらへ？","start":1257.78,"favorite":false,"stableId":"eb590efd-5253-43e4-a245-ba82b1678a50","sequenceId":288},{"id":289,"end":1260.79,"note":"","text":"(鹿谷) えっ？","start":1259.51,"favorite":false,"stableId":"917108d8-a8a1-4246-9867-23df19703d76","sequenceId":289},{"id":290,"end":1264.09,"note":"","text":"この先に 時計館という 建物があるの知ってます？","start":1260.84,"favorite":false,"stableId":"09bba513-b3d6-45bd-9923-d6aa4b292155","sequenceId":290},{"id":291,"end":1265.3,"note":"","text":"そちらに","start":1264.14,"favorite":false,"stableId":"0a19ab71-fce9-4733-8c65-3e2c2a8fbde8","sequenceId":291},{"id":292,"end":1267.02,"note":"","text":"(福西) へえ～","start":1265.35,"favorite":false,"stableId":"d7419d78-a0ae-4ad5-b8a6-4020ab107a8a","sequenceId":292},{"id":293,"end":1268.93,"note":"","text":"(鹿谷) あれ？","start":1267.54,"favorite":false,"stableId":"08a3960d-95c0-424b-acfe-04e3a1d48a49","sequenceId":293},{"id":294,"end":1272.91,"note":"","text":"もしかして 君も 稀譚社の取材に参加するとか？","start":1268.98,"favorite":false,"stableId":"5851c637-f466-4b25-954c-314f0e546c28","sequenceId":294},{"id":295,"end":1274.39,"note":"","text":"(福西) はい","start":1273.26,"favorite":false,"stableId":"7389866b-1e2d-49e9-a237-219829750697","sequenceId":295},{"id":296,"end":1277.69,"note":"","text":"僕は Ｗ大学のミステリー研究会で…","start":1274.44,"favorite":false,"stableId":"c58a6b6a-836e-42d2-b241-d8d8d41e2c7b","sequenceId":296},{"id":297,"end":1278.98,"note":"","text":"あっ ミステリーっていっても――","start":1277.74,"favorite":false,"stableId":"461b822f-fbeb-40f7-89ab-bcbb3dd2cf41","sequenceId":297},{"id":298,"end":1282.02,"note":"","text":"推理小説じゃなくて 超常現象のほうですけど","start":1279.03,"favorite":false,"stableId":"d6ec8850-4585-4ac2-8824-130e6bdef6a6","sequenceId":298},{"id":299,"end":1285.15,"note":"","text":"(鹿谷) なるほど 遅刻してきたってわけか","start":1282.07,"favorite":false,"stableId":"3a80c586-b312-4a74-933c-82f920e607da","sequenceId":299},{"id":300,"end":1289.2,"note":"","text":"確か 今日のイベント 始まるのは午後６時からだよね？","start":1285.2,"favorite":false,"stableId":"cca03837-d8f0-469d-b960-a67b10577c36","sequenceId":300},{"id":301,"end":1291.03,"note":"","text":"(福西) どうして… (鹿谷) 一緒に乗ってくよね？","start":1289.25,"favorite":false,"stableId":"9c110cba-cc5f-459a-8ae6-bad801b88fcc","sequenceId":301},{"id":302,"end":1292.59,"note":"","text":"君 名前は？","start":1291.08,"favorite":false,"stableId":"ddb76024-4adf-4190-93db-8cd85ccab04a","sequenceId":302},{"id":303,"end":1294.04,"note":"","text":"福西です","start":1292.78,"favorite":false,"stableId":"3c441e03-58f1-4c7d-b50f-582060c60e1b","sequenceId":303},{"id":304,"end":1296.87,"note":"","text":"(鹿谷) 福西くん　んん…","start":1294.09,"favorite":false,"stableId":"a9f06858-681e-4d72-bb7c-4244e28f7e55","sequenceId":304},{"id":305,"end":1298.25,"note":"","text":"実を言うとね","start":1296.92,"favorite":false,"stableId":"33c828d4-feea-4eb9-97b2-695cd98638c4","sequenceId":305},{"id":306,"end":1301.98,"note":"","text":"誰か仲間がいてくれたほうが 心強いんだ","start":1298.3,"favorite":false,"stableId":"b3c6b9e6-d1c1-4456-a50c-499140f6ad76","sequenceId":306},{"id":307,"end":1329.84,"note":"","text":"(振子の音)","start":1324.43,"favorite":false,"stableId":"35e33535-b21f-48ed-b27c-da8657191575","sequenceId":307},{"id":308,"end":1350.97,"note":"","text":"(内海) すごい","start":1348.46,"favorite":false,"stableId":"ebc9b938-4c4f-49f0-801a-10f25ceefa94","sequenceId":308},{"id":309,"end":1354.43,"note":"","text":"まさに 時計の館ですね","start":1351.02,"favorite":false,"stableId":"e0cc4082-9092-4206-9636-3c6b043c8c1e","sequenceId":309},{"id":310,"end":1356.06,"note":"","text":"(小早川) 圧巻だね","start":1354.48,"favorite":false,"stableId":"c895d919-27ae-4e92-b9a1-6350d8d902f5","sequenceId":310},{"id":311,"end":1360.39,"note":"","text":"(河原崎) なんか こんだけあると 気味が悪いもんだな","start":1356.11,"favorite":false,"stableId":"82e445fa-9716-408f-81b0-e56f36dfe6f2","sequenceId":311},{"id":312,"end":1361.91,"note":"","text":"(瓜生) うん","start":1360.44,"favorite":false,"stableId":"267dca69-20f3-4248-b830-7f5180e6cfb0","sequenceId":312},{"id":313,"end":1367,"note":"","text":"どれも ちゃんと動いているんですね","start":1363.47,"favorite":false,"stableId":"640e0f01-89ff-4112-a6a8-78cb79594894","sequenceId":313},{"id":314,"end":1371.96,"note":"","text":"(早紀子) しかも みんな同じ時刻","start":1368.1,"favorite":false,"stableId":"d14bfcf1-5b09-47c9-b949-d05548772986","sequenceId":314},{"id":315,"end":1375.49,"note":"","text":"(小早川) ただし ここで こうして動いてる時計は――","start":1372.19,"favorite":false,"stableId":"4add0452-64cb-489d-9ce2-b5d56cd46b96","sequenceId":315},{"id":316,"end":1377.54,"note":"","text":"どれも偽物なんだそうだ","start":1375.54,"favorite":false,"stableId":"da9d36aa-bf8f-47ce-b965-8bf6c1c8f76f","sequenceId":316},{"id":317,"end":1380.37,"note":"","text":"(渡辺) 偽物？ どういう意味ですか？","start":1377.59,"favorite":false,"stableId":"32f9fc5c-f4ac-4907-99f6-c14e9315a9c0","sequenceId":317},{"id":318,"end":1383.14,"note":"","text":"(小早川) 本物の アンティークじゃないってことさ","start":1380.42,"favorite":false,"stableId":"e006ddda-6c72-446c-90a3-86e0904a8433","sequenceId":318},{"id":319,"end":1386.96,"note":"","text":"古峨倫典が集めた 本物の古時計は 全て――","start":1383.37,"favorite":false,"stableId":"4380bdbe-40d5-49ba-866b-736124a2a401","sequenceId":319},{"id":320,"end":1390.52,"note":"","text":"資料室の陳列ケースの中に 保管されている","start":1387.01,"favorite":false,"stableId":"ea498c2d-c3b7-46a9-9f22-3b74de1221e5","sequenceId":320},{"id":321,"end":1393.72,"note":"","text":"外に出して 動かしてるのは 全部――","start":1390.57,"favorite":false,"stableId":"780dc3a1-bb3e-410f-beae-67ff664135a5","sequenceId":321},{"id":322,"end":1397.36,"note":"","text":"彼が作らせた 精巧なイミテーションらしい","start":1393.77,"favorite":false,"stableId":"e601438b-1a65-4d33-b096-70687188ecc2","sequenceId":322},{"id":323,"end":1400.52,"note":"","text":"(江南) 特注の模造品ってことですか","start":1397.51,"favorite":false,"stableId":"d28d48fe-46da-421b-bd92-bd8343bf01a7","sequenceId":323},{"id":324,"end":1403.23,"note":"","text":"(こずえ) すっごくお金かかってますよね","start":1400.57,"favorite":false,"stableId":"af2dd2bb-b4f6-4a2c-b030-7157600caa12","sequenceId":324},{"id":325,"end":1406.08,"note":"","text":"(小早川) 全部で108個あるそうだ","start":1403.28,"favorite":false,"stableId":"f6917add-5373-485f-8b8f-439ba67993eb","sequenceId":325},{"id":326,"end":1409.08,"note":"","text":"(江南) 108個も…","start":1406.26,"favorite":false,"stableId":"bf55f058-806d-4935-b90c-c8f9ac1f090d","sequenceId":326},{"id":327,"end":1414.09,"note":"","text":"(鍵の閉まる音)","start":1412.6,"favorite":false,"stableId":"f902b6ac-1e3e-4691-9206-42c6c147191a","sequenceId":327},{"id":328,"end":1427.94,"note":"","text":"(早紀子) へえ～ こうなってるんだ","start":1424.32,"favorite":false,"stableId":"2422b816-b9d4-445b-923d-a18dc591b606","sequenceId":328},{"id":329,"end":1431.15,"note":"","text":"(小早川) 大したもんだね","start":1428.7,"favorite":false,"stableId":"b1c93d87-bd6a-44b1-bc42-b475a874a41c","sequenceId":329},{"id":330,"end":1434.34,"note":"","text":"(瓜生) 大学じゃ 一応 建築が専門なんですよ","start":1431.2,"favorite":false,"stableId":"0540bffc-2cb3-47df-be42-09180e5db465","sequenceId":330},{"id":331,"end":1436.3,"note":"","text":"ですから このくらいは","start":1434.39,"favorite":false,"stableId":"613df9a8-67c2-4f55-bca8-2b75c776e3d9","sequenceId":331},{"id":332,"end":1438.22,"note":"","text":"(江南) こういう形してるんだ","start":1436.35,"favorite":false,"stableId":"925a87e0-6e60-402a-8fef-dacb9af51c7f","sequenceId":332},{"id":333,"end":1441.18,"note":"","text":"(瓜生) ええ 外側に資料室が12部屋","start":1438.27,"favorite":false,"stableId":"dc92390f-f273-4e3a-a21c-ec9d0928d3db","sequenceId":333},{"id":334,"end":1444.03,"note":"","text":"文字盤のように配置された造りでした","start":1441.23,"favorite":false,"stableId":"93eddaf6-2676-4143-bd29-3549f1ae739f","sequenceId":334},{"id":335,"end":1446.15,"note":"","text":"(渡辺) 凝った造りですね","start":1444.09,"favorite":false,"stableId":"4acd0347-7fd7-4569-ae35-38c182d5c350","sequenceId":335},{"id":336,"end":1451.5,"note":"","text":"(河原崎) さすが 古峨精計社の 会長だっただけあるな","start":1446.2,"favorite":false,"stableId":"edd56d8f-78d2-422c-b0b7-944247c52e6d","sequenceId":336},{"id":337,"end":1453.17,"note":"","text":"(こずえ) 分かった！","start":1451.55,"favorite":false,"stableId":"c53567b3-f41e-42ce-8d16-c93337b17df9","sequenceId":337},{"id":338,"end":1459.8,"note":"","text":"真ん中の時計から延びた先だから “振子の部屋”なんだ","start":1454.31,"favorite":false,"stableId":"2ee27729-6842-4932-becb-84ca4da4aaa2","sequenceId":338},{"id":339,"end":1461.62,"note":"","text":"(渡辺) ホントだ","start":1459.94,"favorite":false,"stableId":"6c0cd7f7-9292-4943-8651-5f15ad6cd942","sequenceId":339},{"id":340,"end":1463.2,"note":"","text":"確かに 振子みたいだよね","start":1461.67,"favorite":false,"stableId":"4ec84e9e-2ddc-43b1-a0d2-72e9cad829c6","sequenceId":340},{"id":341,"end":1465.71,"note":"","text":"(河原崎) 立ち入り禁止だけどな","start":1463.25,"favorite":false,"stableId":"1227b529-d543-495b-bf74-1ae54b4763f7","sequenceId":341},{"id":342,"end":1468.84,"note":"","text":"(江南)<これが中村青司の…>","start":1465.76,"favorite":false,"stableId":"cde7494b-e30a-44a5-b89d-aa0120bb440f","sequenceId":342},{"id":343,"end":1471.13,"note":"","text":"(瓜生) それはそうと 小早川さん","start":1468.89,"favorite":false,"stableId":"45df0a17-66e2-422a-9f2d-31d58bce6a80","sequenceId":343},{"id":344,"end":1473.01,"note":"","text":"夜は どこで寝ればいいんですか？","start":1471.18,"favorite":false,"stableId":"3aedd82a-b298-48b6-9ef9-815ec446cc2c","sequenceId":344},{"id":345,"end":1475.42,"note":"","text":"寝室は３つしかないみたいですけど","start":1473.06,"favorite":false,"stableId":"b0334ebb-39ce-4ce9-ae26-046322f74e7c","sequenceId":345},{"id":346,"end":1477.68,"note":"","text":"(小早川) そう　それなんだが――","start":1475.47,"favorite":false,"stableId":"6440e3ad-a91f-4853-9f6a-19cfaec2b5b1","sequenceId":346},{"id":347,"end":1481.01,"note":"","text":"寝室は使用していいと 伊波さんの許可を取ってある","start":1477.73,"favorite":false,"stableId":"dc6b041b-f64d-4200-ac9a-53decda086cd","sequenceId":347},{"id":348,"end":1483.68,"note":"","text":"女性３人に そこを使ってもらうとして――","start":1481.06,"favorite":false,"stableId":"00d689d5-60bc-4e56-a1ed-cfc3629c4345","sequenceId":348},{"id":349,"end":1485.7,"note":"","text":"あとの６人は――","start":1483.73,"favorite":false,"stableId":"1e6ae4ab-31ab-43b0-a6c0-64b95039ddbf","sequenceId":349},{"id":350,"end":1488.2,"note":"","text":"資料室に――","start":1485.97,"favorite":false,"stableId":"e1734801-115f-4b8d-9f39-08c4d340000d","sequenceId":350},{"id":351,"end":1492.63,"note":"","text":"毛布を持ち込んでと 考えてるんだがね","start":1488.89,"favorite":false,"stableId":"c3f1d784-3d91-46f9-8b1d-976398255e9c","sequenceId":351},{"id":352,"end":1494.94,"note":"","text":"(内海) あそこで寝るんですか？","start":1492.89,"favorite":false,"stableId":"277be050-a2ee-442a-a57a-491791fc42a8","sequenceId":352},{"id":353,"end":1496.82,"note":"","text":"１人ずつバラバラで？","start":1494.99,"favorite":false,"stableId":"ea7b63ac-7a3c-44ae-9ca2-51b8dc1e547c","sequenceId":353},{"id":354,"end":1501.03,"note":"","text":"だったら 俺は その辺で みんなで 雑魚寝でも かまわないですけど","start":1496.87,"favorite":false,"stableId":"24b48b72-edaa-49b0-8c56-d38bfe1d014d","sequenceId":354},{"id":355,"end":1502.12,"note":"","text":"(小早川) 光明寺さんは――","start":1501.08,"favorite":false,"stableId":"55b35441-14c8-4c52-a06e-8fadf4983d57","sequenceId":355},{"id":356,"end":1503.34,"note":"","text":"どう思われますか？","start":1502.17,"favorite":false,"stableId":"dd722e4d-d699-4236-b3e1-8e3d1006f849","sequenceId":356},{"id":357,"end":1510.85,"note":"","text":"(美琴) この家に――","start":1508.91,"favorite":false,"stableId":"b96f3cf5-eb49-4d86-9b4b-de0f14010d13","sequenceId":357},{"id":358,"end":1517.4,"note":"","text":"何者かの霊魂が住み着いているのは 間違いなさそうです","start":1511.33,"favorite":false,"stableId":"011fee02-290d-42e3-ba24-6ee2e793cfd3","sequenceId":358},{"id":359,"end":1531,"note":"","text":"敵意は持っていません","start":1528.05,"favorite":false,"stableId":"1da6eb19-521b-4f13-a2d4-8d54f42a2b61","sequenceId":359},{"id":360,"end":1537.45,"note":"","text":"むしろ 私たちに――","start":1534.89,"favorite":false,"stableId":"c628dd54-09af-4621-ba3d-0fe7de2f14a7","sequenceId":360},{"id":361,"end":1541.09,"note":"","text":"おびえているような波動を感じます","start":1537.5,"favorite":false,"stableId":"7346aae5-0b3a-4258-a225-52b2a127ef38","sequenceId":361},{"id":362,"end":1542.84,"note":"","text":"(小早川) おびえている…","start":1541.27,"favorite":false,"stableId":"e4b43721-8af7-4fd8-9c3a-397d32127a11","sequenceId":362},{"id":363,"end":1546.66,"note":"","text":"(美琴) ですから 私たちは――","start":1544.53,"favorite":false,"stableId":"6f9a3141-afab-4c80-b72a-91d1abec7a25","sequenceId":363},{"id":364,"end":1549.6,"note":"","text":"ひとつの場所に 固まるよりも――","start":1546.71,"favorite":false,"stableId":"4132bfc2-8041-46d4-a82c-4baf60282deb","sequenceId":364},{"id":365,"end":1552.46,"note":"","text":"１人ずつ バラバラで過ごす時間を","start":1550.12,"favorite":false,"stableId":"cab69ff6-c0f3-4014-aca4-9a9737c8e0be","sequenceId":365},{"id":366,"end":1555.27,"note":"","text":"持ったほうがいいのでは ないかと思います","start":1552.51,"favorite":false,"stableId":"f43395b4-9b24-4b14-9d29-6688bc164e30","sequenceId":366},{"id":367,"end":1560.22,"note":"","text":"霊と うまく交信するためにも","st